window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0213", [{"word":"mechanical system","ipa_uk":"/məˈkænɪkəl ˈsɪstəm/","ipa_us":"/məˈkænɪkəl ˈsɪstəm/","definition_zh":"由相互连接的部件组成、共同传递力与运动的整套装置；也指力学分析中被一起处理的受力物体组合","definition_en":"a set of connected parts that work together to carry force and motion, or the group of bodies treated together in a mechanics analysis","core_image":"齿轮、连杆与轴承咬合成一条传力路线，动力从输入轴进入，经各部件推到输出端","scene":"装配车间里，工程师转动输入轴，观察齿轮与连杆怎样把动力送到输出端。The engineers tested the mechanical system before shipping it.","sceneCN":"这里指由齿轮、连杆等部件组成并共同传力的整套装置（第 1 个义项：由相互连接的部件组成、共同传递力与运动的整套装置）；句意：工程师在发货前测试了这套机械系统。","pos":[{"tag":"n.","zh":"机械系统；力学系统；机械装置"}],"collocations":[{"phrase":"mechanical system design","zh":"机械系统设计"},{"phrase":"mechanical system failure","zh":"机械系统故障"},{"phrase":"complex mechanical system","zh":"复杂的机械系统"},{"phrase":"mechanical system analysis","zh":"机械系统分析"},{"phrase":"vehicle mechanical system","zh":"车辆机械系统"}],"forms":[{"label":"单数形式","form":"mechanical system"},{"label":"复数形式","form":"mechanical systems"},{"label":"形容词形式","form":"mechanical"},{"label":"副词形式","form":"mechanically"},{"label":"名词形式","form":"mechanism"},{"label":"动词形式","form":"mechanize"}],"derivatives":[{"word":"mechanic","pos":"n.","zh":"由「机械的」这一形容词转成的名词，义为「机械师、修理工」"},{"word":"mechanical","pos":"adj.","zh":"由「机械」的希腊语名词加形容词词尾构成，义为「机械的」"},{"word":"mechanism","pos":"n.","zh":"由「机械」词干加表示「结构、装置」的名词词尾构成，义为「机构、机理」"},{"word":"mechanize","pos":"v.","zh":"由「机械」词干加表示「使成为」的动词词尾构成，义为「使机械化」"},{"word":"system","pos":"n.","zh":"由希腊语表示「一起放置」的词构成，义为「系统」"},{"word":"systematic","pos":"adj.","zh":"由「系统」加形容词词尾构成，义为「系统的、有条理的」"},{"word":"systematize","pos":"v.","zh":"由「系统的」加动词词尾构成，义为「使系统化」"}],"senses":[{"no":"01","title":"A set of connected parts","titleCN":"一套相互连接的部件","definition":"an assembly of linked parts that transmits force or motion from one point to another","definitionCN":"由相互连接的部件组成、把力或运动从一处传到另一处的组合体","example":"The gearbox is only one part of the mechanical system.","exampleCN":"齿轮箱只是这套机械系统的一部分。","why":"Mechanical names whatever works through physical parts, and system names an organized whole, so the phrase is a whole built out of parts.","whyCN":"「机械」指靠实体部件运作的事物，「系统」指有组织的整体，因此这个词组就是由部件搭成的整体。"},{"no":"02","title":"Bodies treated together in mechanics","titleCN":"力学中一起分析的受力物体","definition":"the group of bodies and forces that an analysis treats as one connected problem","definitionCN":"力学分析中被当作一个连通的整体来处理的一群物体及其受力","example":"In the lab they treated the pulley and the hanging weight as one mechanical system.","exampleCN":"在实验室里，他们把滑轮和悬挂的重物当成一个机械系统来处理。","why":"The phrase is borrowed from physics, where any chosen group of interacting bodies can be cut out of the world and studied as a system.","whyCN":"这个说法借自物理学：任何一组相互作用的物体都可以从世界中划出来，作为一个系统来研究。"},{"no":"03","title":"A machine guided by sensors","titleCN":"带传感器与控制的机械装置","definition":"a machine whose moving parts are monitored and corrected by sensors, actuators and a controller","definitionCN":"由传感器、执行器与控制器监测并修正运动部件的机器","example":"The robot arm is a mechanical system guided by sensors.","exampleCN":"这条机械臂是由传感器引导的机械系统。","why":"Once control hardware is added, the mechanical parts still carry the motion, so the old phrase now covers the whole controlled machine.","whyCN":"加上控制硬件之后，运动的仍由机械部件承担，于是旧说法扩展为整台受控机器。"},{"no":"04","title":"The wheel train of a clock","titleCN":"钟表内的轮系","definition":"the train of wheels and springs inside a watch or clock that turns the hands","definitionCN":"钟表内部带动指针的轮系与发条","example":"A watch is a small mechanical system that has no battery.","exampleCN":"机械表是一套不需要电池的小型机械系统。","why":"Before electronics, every timed device was a linked set of gears, and that literal picture survives in the phrase.","whyCN":"在电子技术出现之前，所有计时装置都是连成一套的齿轮，这个词组保留了那幅字面画面。"},{"no":"05","title":"The drive line of a vehicle","titleCN":"车辆的传动系","definition":"the engine, clutch, gearbox and shaft that together send power to the wheels","definitionCN":"把发动机的动力传到车轮的发动机、离合器、变速箱与传动轴组合","example":"The car's mechanical system includes the clutch and the driveshaft.","exampleCN":"这辆车的机械系统包括离合器与传动轴。","why":"A drive line is exactly a chain of parts handing force along, so the general phrase settles on this familiar example.","whyCN":"传动系正是一条逐级传递力的部件链，因此这个泛称自然落在这一常见例子上。"},{"no":"06","title":"The frame of a living body","titleCN":"生物体的力学构造","definition":"the bones, joints and muscles of an animal viewed as a structure that carries load and produces motion","definitionCN":"把动物的骨骼、关节与肌肉看作承重并产生运动的结构","example":"The bird's wing is a light mechanical system of bone and muscle.","exampleCN":"鸟的翅膀是由骨骼与肌肉构成的轻巧机械系统。","why":"Because bones and muscles also form levers and linkages, biologists borrow the engineering phrase for living bodies.","whyCN":"骨骼与肌肉同样构成杠杆与连杆，生物学家便借用了这个工程说法来描述活体。"},{"no":"07","title":"A rigid routine","titleCN":"机械刻板的运作方式","definition":"an organization or process that repeats fixed steps without adapting to circumstances","definitionCN":"不随情况调整、只重复固定步骤的组织或流程","example":"The old office ran like a mechanical system, with every form checked twice.","exampleCN":"这个旧办公室运作得像一套机械系统，每张表格都要核对两遍。","why":"When people act without judgment, they are imagined as gears rather than thinkers, so the machine phrase becomes a criticism.","whyCN":"当人不动判断地行事时，就被想象成齿轮而不是思考者，于是机械的说法变成了批评。"},{"no":"08","title":"Rule-bound logic in software","titleCN":"按固定规则运作的程序逻辑","definition":"a module or procedure whose output is fully determined by its input and fixed rules","definitionCN":"输出完全由输入与固定规则决定的模块或流程","example":"The billing module behaves as a mechanical system: the same input always gives the same output.","exampleCN":"计费模块表现得像一套机械系统：相同的输入总是给出相同的输出。","why":"Programmers reuse the phrase for deterministic code, because such code follows rules the way gears follow teeth.","whyCN":"程序员把这个说法用于确定性代码，因为这类代码遵守规则，就像齿轮咬合齿一样。"}],"etymology":{"intro":{"en":"The phrase joins a Greek-derived adjective for things that work by parts with a Greek-derived noun for an organized whole, and English engineers combined them in the nineteenth century.","cn":"这个词组把一个源自希腊语、表示「靠部件运作」的形容词，与一个同样源自希腊语、表示「有组织的整体」的名词拼在一起，英语工程界在十九世纪把它们固定成词组。"},"items":[{"era":"GREEK MEKHANE","en":"Mekhane meant a device, a contrivance or a means of getting something done, and it already carried the idea of parts arranged for a purpose; this Greek word is the direct source of the first half, while its still earlier root is a matter of reconstruction rather than settled fact.","cn":"这个希腊语名词指装置、巧计或达成目的的手段，本身已含「为某一目的而安排部件」的意思；它是前半的直接来源，其更早的词根属重构性质，尚无定论。"},{"era":"GREEK MEKHANIKOS","en":"The derived adjective described what belongs to a device or is cleverly contrived, and it passed into Latin as mechanicus.","cn":"由它派生的形容词表示「属于装置的、精巧设计的」，并以「机械的」这一形式进入拉丁语。"},{"era":"LATIN MECHANICUS","en":"Latin mechanicus kept the sense of something built or worked by physical means, and French and English took it over in the sense of machines.","cn":"拉丁语保留了「靠实体手段造成或运作」的含义，法语与英语随后以「机器」的意思接过这个词。"},{"era":"GREEK SYSTEMA","en":"Systema meant a whole composed of several parts set together; it combines syn, meaning together, with histanai, meaning to set up or stand.","cn":"这个希腊语名词指由若干部分合在一起构成的整体，由表示「一起」的前缀与表示「安置、立起」的动词组合而成。"},{"era":"LATIN SYSTEMA AND ENGLISH SYSTEM","en":"Late Latin systema and sixteenth-century English system kept the picture of parts standing together as one body.","cn":"晚期拉丁语与十六世纪英语都保留了「各部分立在一起成为一个整体」的画面。"},{"era":"NINETEENTH CENTURY COMPOUND · FIRST RECORD DATE UNCERTAIN","en":"As machine building became a science of linked parts, English joined mechanical to system for the whole assembly and for the body group that mechanics analyses; the exact year when the compound first appeared in print is uncertain.","cn":"随着机械制造成为研究部件连接的科学，英语把「机械的」与「系统」组合起来，既指整套装置，也指力学所分析的物体组合；该词组具体首见于何年并不确定。"}]},"similar":{"note":{"en":"The first group shares a word element with the target; the second group names nearby kinds of assembled equipment.","cn":"第一组与目标词共享构词成分；第二组是相邻的成套装备说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"noun","definition":"The working arrangement inside a device; it is the inner linkage, not the whole system.","definitionCN":"装置内部的运作机构；指内部连杆关系，而不是整套系统。"},{"word":"mechanical","ipa":"/məˈkænɪkəl/","tag":"adjective","definition":"Worked by physical parts rather than by electricity or thought.","definitionCN":"靠实体部件而非电力或思维运作的。"},{"word":"machine","ipa":"/məˈʃiːn/","tag":"noun","definition":"One powered device; a system may contain several machines.","definitionCN":"单台动力装置；一套系统可能包含多台机器。"},{"word":"mechanize","ipa":"/məˈkænəˌzaɪz/","tag":"verb","definition":"To replace human or animal work with machines.","definitionCN":"用机器替代人力或畜力。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assembly","ipa":"/əˈsemblɪ/","tag":"noun","definition":"A group of parts put together; it stresses the putting together rather than the working whole.","definitionCN":"把零件装成的组合体；强调组装动作，而非运作整体。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"noun","definition":"A set of equipment for a particular use, often in a lab; it stresses the equipment rather than linked motion.","definitionCN":"为特定用途配置的一套器械，常见于实验室；强调器械本身，而非连动关系。"},{"word":"rig","ipa":"/rɪɡ/","tag":"noun","definition":"A temporary or improvised set of parts arranged for a test; it is rougher and less permanent than a system.","definitionCN":"为试验临时搭起的一套部件；比系统更粗糙、更临时。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Mechanical points to physical parts, and system points to an organized whole.","cn":"「机械的」指向实体部件，「系统」指向有组织的整体。"},{"en":"The family runs mechanism, mechanize, mechanical and mechanically.","cn":"同族词包括机构、使机械化、机械的与机械地。"},{"en":"Fixed phrases mark it: mechanical system design, mechanical system failure, mechanical system analysis.","cn":"固定搭配可标记它：机械系统设计、机械系统故障、机械系统分析。"},{"en":"A clock is the smallest familiar example: wheels and springs turning hands.","cn":"钟表是最小的熟悉例子：轮系与发条带动指针。"},{"en":"A car drive line is the largest everyday example: engine, clutch, gearbox, shaft, wheels.","cn":"汽车传动系是日常最大的例子：发动机、离合器、变速箱、传动轴、车轮。"}],"abstract":[{"en":"Picture a row of hands passing a bucket along, each hand doing one fixed job.","cn":"想象一排手依次传递水桶，每只手只做一件固定的事。"},{"en":"Picture a locked staircase where every step must be trodden in the same order.","cn":"想象一道固定的楼梯，每一步都必须按同样顺序踩过。"},{"en":"Picture a company whose every form travels the same conveyor belt of desks.","cn":"想象一家公司，每张表格都沿着同一条桌面传送带流转。"}]},"examples":[{"en":"The pump and the motor form one mechanical system on the test bench.","cn":"泵与电机在试验台上构成一套机械系统。"},{"en":"Students drew the pulley, the rope and the weight as a single mechanical system.","cn":"学生们把滑轮、绳与重物画成一个机械系统。"},{"en":"The factory floor is a mechanical system that still needs a human eye.","cn":"车间是一套机械系统，但仍然需要人的眼睛。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「机械」加「系统」——零件拼成一条传力链，环环相扣","word":"mechanical system"},"root":"「机械」一词可追至希腊语表示「装置」的名词，该词更早的来源存疑；「系统」由希腊语「一起」与「安置」构成，两词经拉丁语进入英语，十九世纪合成词组。","sensesIntro":{"en":"Eight senses follow one idea: parts linked so that force passes through them. The parts may be gears, physical bodies, sensors, bones, or even fixed office steps.","cn":"八个义项围绕一个观念：部件连在一起，让力在其中通过。这些部件可以是齿轮、受力的物体、传感器、骨骼，甚至固定的办公步骤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a chain of parts biting into one another so that motion entered at one end comes out at the other.","cn":"核心意象：一串部件彼此咬合，从一端输入的运动从另一端输出。"},"chain":["BOLTED PARTS","LINKED MOTION","FORCE MODEL","CONTROLLED MACHINE","VEHICLE DRIVE","FIXED ROUTINE"],"branches":[{"senses":"01 · 02","en":"THE PHYSICAL CORE: an assembly of parts, and the same group treated as a problem in mechanics.","cn":"实体核心：部件的组合体，以及被当作力学问题处理的同一组物体。"},{"senses":"03","en":"THE CONTROLLED VERSION: sensors and actuators steer the moving parts.","cn":"受控版本：传感器与执行器操纵运动部件。"},{"senses":"04 · 05","en":"FAMILIAR EXAMPLES: the wheel train of a clock and the drive line of a car.","cn":"熟悉的例子：钟表轮系与汽车传动系。"},{"senses":"06","en":"THE LIVING VERSION: bones, joints and muscles acting as levers.","cn":"活的版本：骨骼、关节与肌肉充当杠杆。"},{"senses":"07 · 08","en":"THE METAPHOR: people or code repeating fixed steps without judgment.","cn":"比喻用法：人或代码不加判断地重复固定步骤。"}]},"affixes":{"intro":{"en":"Both halves come from Greek through Latin; the adjective half carries the device root and the noun half carries the putting-together root.","cn":"两半都经拉丁语来自希腊语：形容词一半带「装置」词根，名词一半带「一起安置」词根。"},"latinIntro":{"en":"Latin supplied mechanicus and systema, both borrowed from Greek, so the Latin entries below are the forms English actually received.","cn":"拉丁语提供了「机械的」与「系统」两个借自希腊语的词形，下列拉丁词条就是英语实际接收的形式。"},"items":[{"word":"mekhane","structure":"Greek noun","meaning":"a device, contrivance or means","meaningCN":"装置、巧计、手段","example":"The Greek noun already implies parts arranged for a purpose.","exampleCN":"这个希腊名词已含「为某目的安排部件」之意。"},{"word":"mekhanikos","structure":"Greek adjective","meaning":"belonging to a device; inventive","meaningCN":"属于装置的；巧妙的","example":"The adjective described cleverly built things.","exampleCN":"这个形容词描述精巧造出的东西。"},{"word":"mechanicus","structure":"Latin adjective","meaning":"worked by physical means","meaningCN":"靠实体手段运作的","example":"Latin passed the adjective to French and English.","exampleCN":"拉丁语把这个形容词传给了法语与英语。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes an adjective from a noun stem.","exampleCN":"这个词尾把名词词干变成形容词。"},{"word":"systema","structure":"Greek noun","meaning":"a whole set together","meaningCN":"合在一起的整体","example":"The noun joins a together-prefix with a verb of setting up.","exampleCN":"这个名词把「一起」前缀与「安置」动词结合起来。"},{"word":"syn-","structure":"Greek prefix","meaning":"together, with","meaningCN":"一起、共同","example":"The prefix supplies the togetherness of the whole.","exampleCN":"这个前缀提供整体的「共同」含义。"},{"word":"histanai","structure":"Greek verb","meaning":"to set up, to stand","meaningCN":"立起、安置","example":"The verb supplies the standing of the parts.","exampleCN":"这个动词提供各部分的「立起」含义。"},{"word":"system","structure":"English noun","meaning":"an organized whole of parts","meaningCN":"由部分构成的有组织整体","example":"English shortened the Latin borrowings into system.","exampleCN":"英语把拉丁借词简化为「系统」。"},{"word":"mechanical","structure":"English adjective","meaning":"of machines or physical parts","meaningCN":"机器的、实体部件的","example":"The adjective is the first half of the target phrase.","exampleCN":"这个形容词是目标词组的前半。"},{"word":"-ly","structure":"adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms mechanically from mechanical.","exampleCN":"它把「机械的」变成「机械地」。"}],"latinEntries":[{"word":"mechanicus","structure":"mechanicus (adj., first-second declension)","meaning":"of a machine; mechanical","meaningCN":"机器的；机械的"},{"word":"systema","structure":"systema, systematis (n., third declension, from Greek)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"ingenium","structure":"not the source of either half; listed only to prevent confusion with engineer","meaning":"natural ability, invention","meaningCN":"天赋、发明才能"}],"derivatives":[{"word":"mechanical","pos":"adj.","zh":"由「机械」词干加形容词词尾构成，义为「机械的」"},{"word":"mechanically","pos":"adv.","zh":"由「机械的」加副词词尾构成，义为「机械地」"},{"word":"mechanism","pos":"n.","zh":"由「机械」词干加表示结构的名词词尾构成，义为「机构、机理」"},{"word":"mechanize","pos":"v.","zh":"由「机械」词干加使动词尾构成，义为「使机械化」"},{"word":"system","pos":"n.","zh":"由希腊语「一起安置」经拉丁语进入英语，义为「系统」"},{"word":"systematic","pos":"adj.","zh":"由「系统」加形容词词尾构成，义为「系统的」"}]}},{"word":"electrical engineering","ipa_uk":"/ɪˈlektrɪkəl ˌendʒɪˈnɪərɪŋ/","ipa_us":"/ɪˈlektrɪkəl ˌendʒɪˈnɪrɪŋ/","definition_zh":"研究电与电磁现象，并设计发电、输电、配电及各类电气设备的工程学科","definition_en":"the branch of engineering that studies electricity and electromagnetism and designs power systems, machines and electrical equipment","core_image":"变电站里，母线、开关柜与电缆连成一条供电通路，电流从发电机一端送到用户一端","scene":"变电站控制室里，值班工程师核对线路负荷后合上开关，让电流送入城区电网。The electrical engineering team redesigned the substation relay.","sceneCN":"这里指负责电力与电气设备设计的工程学科及其团队（第 1 个义项：研究电与电磁现象并设计电力与电气设备的工程学科）；句意：电气工程团队重新设计了变电站的继电器。","pos":[{"tag":"n.","zh":"电气工程；电气工程学"}],"collocations":[{"phrase":"electrical engineering department","zh":"电气工程系"},{"phrase":"electrical engineering student","zh":"电气工程专业学生"},{"phrase":"power electrical engineering","zh":"电力电气工程"},{"phrase":"electrical engineering practice","zh":"电气工程实务"},{"phrase":"electrical engineering standard","zh":"电气工程标准"}],"forms":[{"label":"学科名称（不可数）","form":"electrical engineering"},{"label":"从业者","form":"electrical engineer"},{"label":"形容词形式","form":"electrical"},{"label":"名词形式","form":"electricity"},{"label":"动词形式","form":"electrify"},{"label":"相关名词","form":"electrician"}],"derivatives":[{"word":"electric","pos":"adj.","zh":"由希腊语「琥珀」经新拉丁语形容词进入英语，义为「电的」"},{"word":"electricity","pos":"n.","zh":"由「电的」加表示性质的名词词尾构成，义为「电、电学」"},{"word":"electrician","pos":"n.","zh":"由「电的」加表示从业者的词尾构成，义为「电工」"},{"word":"electrify","pos":"v.","zh":"由「电的」加表示「使成为」的动词词尾构成，义为「使带电、使电气化」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「天赋、巧思」经法语进入英语，义为「工程师」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加表示活动的词尾构成，义为「工程、工程学」"},{"word":"electronic","pos":"adj.","zh":"由「电子」加形容词词尾构成，义为「电子的」"}],"senses":[{"no":"01","title":"The discipline itself","titleCN":"学科本身","definition":"the branch of engineering concerned with the study and application of electricity, electromagnetism and electrical devices","definitionCN":"研究并应用电、电磁现象与电气设备的工程分支","example":"She chose electrical engineering because she wanted to design power systems.","exampleCN":"她选择电气工程，是因为她想设计电力系统。","why":"Electrical marks the force, engineering marks the organised profession, so the phrase names the whole discipline.","whyCN":"「电气的」标出所研究的力，「工程」标出有组织的专业，因此这个词组命名了整个学科。"},{"no":"02","title":"Generation, transmission and distribution","titleCN":"发电、输电与配电","definition":"the design and operation of the networks that produce and deliver electric power","definitionCN":"生产并输送电力的网络之设计与运行","example":"Electrical engineering keeps the national grid balanced minute by minute.","exampleCN":"电气工程让全国电网逐分钟保持平衡。","why":"The largest application of the discipline is the power network, so the phrase often means that network's engineering.","whyCN":"该学科最大的应用是电力网络，因此这个词组常指这张网络的工程。"},{"no":"03","title":"Design of building services","titleCN":"建筑电气设计","definition":"the design of wiring, lighting, sockets and protective systems inside buildings","definitionCN":"建筑物内布线、照明、插座与保护系统的设计","example":"Electrical engineering covers the lighting and wiring of the new library.","exampleCN":"电气工程涵盖新图书馆的照明与布线。","why":"Every building needs a safe electric path, so the discipline extends from power stations into rooms.","whyCN":"每栋建筑都需要安全的电路，因此该学科从电站延伸到房间。"},{"no":"04","title":"Electric machines and drives","titleCN":"电机与驱动","definition":"the study and design of motors, generators and the drives that control them","definitionCN":"电动机、发电机及控制它们的驱动装置的研究与设计","example":"Electrical engineering made the factory motor quieter and more efficient.","exampleCN":"电气工程让工厂电机更安静、更高效。","why":"Machines that convert electricity and motion are a core object of the discipline.","whyCN":"在电与运动之间转换的机器是该学科的核心对象。"},{"no":"05","title":"Protection, earthing and safety","titleCN":"保护、接地与安全","definition":"the design of relays, fuses, breakers and earthing so that faults do not spread","definitionCN":"设计继电器、熔断器、断路器与接地，使故障不致扩散","example":"Electrical engineering specifies the breaker size and the earthing route.","exampleCN":"电气工程规定断路器规格与接地路径。","why":"Power is dangerous when it escapes, so the discipline includes the devices that stop it.","whyCN":"电一旦失控便危险，因此该学科包含阻止它外泄的装置。"},{"no":"06","title":"A degree programme","titleCN":"学位课程","definition":"the university course of study that trains students in the discipline","definitionCN":"在大学里培养该学科学生的课程体系","example":"He finished electrical engineering in four years and then joined a utility.","exampleCN":"他用四年读完电气工程，随后进入一家电力公司。","why":"A discipline becomes a named programme, so the phrase also labels the degree.","whyCN":"学科会成为命名的课程，因此这个词组也指学位。"},{"no":"07","title":"Site practice and commissioning","titleCN":"现场施工与调试","definition":"the practical work of installing, testing and switching on electrical plant","definitionCN":"安装、试验并给电气设备送电的现场工作","example":"Electrical engineering on site means checking every cable before energising.","exampleCN":"现场的电气工程意味着在送电前检查每根电缆。","why":"Designs must be carried out in the field, and that field work keeps the discipline's name.","whyCN":"设计必须在现场落实，而这种现场工作仍沿用学科之名。"},{"no":"08","title":"Codes and standards","titleCN":"规范与标准","definition":"the body of rules that fixes how electrical work must be designed and inspected","definitionCN":"规定电气工作如何设计与验收的规则体系","example":"Electrical engineering students must learn the local wiring code.","exampleCN":"电气工程学生必须学习当地的布线规范。","why":"Safety is written into rules, so the discipline is also the standard it enforces.","whyCN":"安全被写进规则，因此该学科也是它所执行的规范。"}],"etymology":{"intro":{"en":"Electrical engineering pairs an adjective from the Greek word for amber with a noun from Latin ingenium, the root of engineer; the pairing names a profession built on the behaviour of charge.","cn":"「电气工程」把一个源自希腊语「琥珀」的形容词，与一个源自拉丁语「天赋、巧思」的名词配对；后者正是「工程师」的词根，整个词组命名了一门以电荷行为为基础的专业。"},"items":[{"era":"GREEK ELEKTRON","en":"Elektron meant amber, the resin that attracts light objects when rubbed; this Greek word is the direct source, while its earlier root is uncertain and the link to a word for the beaming sun remains a suggested reconstruction.","cn":"这个希腊语名词指琥珀，即摩擦后能吸引轻小物体的树脂；它是本词的直接来源，其更早词根存疑，与表示「闪耀太阳」之词的关联只是重构性推测。"},{"era":"LATIN ELECTRUM","en":"Latin electrum named amber and also a pale gold alloy, keeping the Greek word alive in learned writing.","cn":"拉丁语用这个词既指琥珀，也指一种淡金色合金，使这个希腊词在学术写作中存续。"},{"era":"NEW LATIN ELECTRICUS","en":"Sixteenth-century scholars coined electricus for the amber effect, and English electric followed in the seventeenth century.","cn":"十六世纪学者为琥珀的吸引现象造出「电的」这一新拉丁语形容词，英语随后在十七世纪出现「电的」。"},{"era":"ENGLISH ELECTRICAL","en":"The adjective gained a fuller ending in the nineteenth century, when electricity became an industry rather than a curiosity.","cn":"十九世纪，当电从奇观变成工业时，这个形容词获得了更完整的词尾。"},{"era":"LATIN INGENIUM","en":"Ingenium meant natural ability or cleverness; French turned it into engin, a clever device, and English engineer named the person who built such devices.","cn":"这个拉丁语名词指天赋或巧思；法语把它变成指精巧装置的名词，英语的「工程师」则指建造这类装置的人。"},{"era":"MODERN PROFESSIONAL PAIRING · FIRST RECORD DATE UNCERTAIN","en":"In the nineteenth century the two words were joined to name the branch that designs power networks and electrical machines; the exact year of first record is uncertain.","cn":"十九世纪，这两个词被组合起来，用以命名设计电力网络与电机的工程分支；具体首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the amber root; the second group names neighbouring engineering branches.","cn":"第一组共享「琥珀」词根；第二组是相邻的工程分支。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"electric","ipa":"/ɪˈlektrɪk/","tag":"adjective","definition":"Driven by electricity; the shorter adjective often describes a single device.","definitionCN":"由电驱动的；较短的形式常描述单台设备。"},{"word":"electronic","ipa":"/ɪˌlekˈtrɒnɪk/","tag":"adjective","definition":"Working through electrons in circuits rather than through heavy current.","definitionCN":"靠电路中电子运作，而非大电流。"},{"word":"electrician","ipa":"/ɪˈlektrɪʃən/","tag":"noun","definition":"A tradesperson who installs and repairs wiring; not the designer.","definitionCN":"安装与维修线路的技术工人；不是设计者。"},{"word":"electricity","ipa":"/ɪˌlekˈtrɪsəti/","tag":"noun","definition":"The physical phenomenon itself rather than the profession.","definitionCN":"电这一物理现象本身，而非专业。"}]},{"heading":"NEAR MEANING","entries":[{"word":"power engineering","ipa":"/ˈpaʊə ˌendʒɪˈnɪərɪŋ/","tag":"noun","definition":"The part of the field that deals with large-scale generation and grids; narrower than the target.","definitionCN":"该领域中处理大规模发电与电网的部分；比目标词窄。"},{"word":"electronic engineering","ipa":"/ɪˌlekˈtrɒnɪk ˌendʒɪˈnɪərɪŋ/","tag":"noun","definition":"The branch built on small signals and semiconductor devices rather than heavy current.","definitionCN":"以弱信号与半导体器件而非大电流为基础的分支。"},{"word":"electrification","ipa":"/ˌelektrɪfɪˈkeɪʃən/","tag":"noun","definition":"The act of bringing electricity to a place or process, not the discipline that plans it.","definitionCN":"把电引入某地或某过程的行为，而非规划它的学科。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The first half goes back to amber rubbed with cloth, the first known electric effect.","cn":"前半可追到用布摩擦琥珀，那是已知最早的电现象。"},{"en":"The second half goes back to ingenium, cleverness, the root of engineer.","cn":"后半可追到表示巧思的拉丁词，它是「工程师」的词根。"},{"en":"The family runs electric, electricity, electrician, electrify, electronic.","cn":"同族词包括电的、电、电工、使带电、电子的。"},{"en":"Fixed phrases mark it: electrical engineering department, electrical engineering practice.","cn":"固定搭配可标记它：电气工程系、电气工程实务。"},{"en":"Power stations, substations and wiring codes are its three familiar homes.","cn":"电站、变电站与布线规范是它三个熟悉的场所。"}],"abstract":[{"en":"Picture a river of charge that must be dammed, channelled and switched.","cn":"想象一条电荷之河，必须被筑坝、引流与开关。"},{"en":"Picture a city whose nerves are copper cables running under every street.","cn":"想象一座城市，神经是每条街下的铜缆。"},{"en":"Picture a hand that never touches the wire yet decides where it goes.","cn":"想象一只手从不碰电线，却决定电线的走向。"}]},"examples":[{"en":"Electrical engineering turned the waterfall into a steady supply for the town.","cn":"电气工程把瀑布变成了小镇的稳定电源。"},{"en":"The electrical engineering course begins with circuits and ends with grid control.","cn":"这门电气工程课程从电路开始，到电网控制结束。"},{"en":"She works in electrical engineering, checking relays before every storm season.","cn":"她从事电气工程，在每个风暴季前检查继电器。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「琥珀」引来电流，「巧思」造出工程——电与匠心的组合","word":"electrical engineering"},"root":"形容词一半源自希腊语「琥珀」，名词一半源自拉丁语「巧思」并经法语成为「工程师」；琥珀一词更早的来源存疑。","sensesIntro":{"en":"Eight senses follow one path: charge is generated, moved, protected and finally written into rules. The same phrase covers the theory, the grid, the building, the machine and the code book.","cn":"八个义项沿一条路径展开：电被发出、被输送、被保护，最后被写成规则。同一个词组覆盖理论、电网、建筑、机器与规范手册。"},"semanticMap":{"core":{"en":"CORE IMAGE: a current entering at one end of a network and leaving at the other, with every joint designed and every fault guarded.","cn":"核心意象：电流从网络一端进入、从另一端输出，每个接点都经过设计，每处故障都有防护。"},"chain":["CHARGE AND CURRENT","POWER GRID","MACHINES","PROTECTION","BUILDING WIRING","SAFE PRACTICE"],"branches":[{"senses":"01 · 02","en":"THE DISCIPLINE AND ITS LARGEST OBJECT: the study of charge, and the generation and delivery network.","cn":"学科与其最大对象：对电荷的研究，以及发电与输送网络。"},{"senses":"03","en":"THE BUILDING VERSION: wiring, lighting and sockets inside a structure.","cn":"建筑版本：建筑物内的布线、照明与插座。"},{"senses":"04","en":"THE MACHINE VERSION: motors and generators converting between current and motion.","cn":"机器版本：在电流与运动之间转换的电动机与发电机。"},{"senses":"05","en":"THE GUARD VERSION: relays, breakers and earthing that stop a fault spreading.","cn":"防护版本：阻止故障扩散的继电器、断路器与接地。"},{"senses":"06 · 07 · 08","en":"THE PROFESSIONAL WRAPPER: the degree, the site work and the written standards.","cn":"职业外壳：学位、现场工作与成文规范。"}]},"affixes":{"intro":{"en":"The phrase is half Greek and half Latin: amber for the force, cleverness for the profession.","cn":"这个词组一半希腊、一半拉丁：用「琥珀」指电，用「巧思」指专业。"},"latinIntro":{"en":"Latin supplies electrum and electricus for the first half, and ingenium for the second.","cn":"拉丁语为前半提供「琥珀」与「电的」，为后半提供「巧思」。"},"items":[{"word":"elektron","structure":"Greek noun","meaning":"amber","meaningCN":"琥珀","example":"The stone that first showed the electric effect.","exampleCN":"最早显露电效应的石头。"},{"word":"electrum","structure":"Latin noun","meaning":"amber; pale gold alloy","meaningCN":"琥珀；淡金色合金","example":"Latin kept the Greek word in learned use.","exampleCN":"拉丁语在学术用语中保留了这个希腊词。"},{"word":"electricus","structure":"New Latin adjective","meaning":"produced by amber","meaningCN":"由琥珀产生的","example":"Scholars coined it for the attraction effect.","exampleCN":"学者为吸引现象造出这个词。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It expanded electric into electrical.","exampleCN":"它把「电的」扩展为「电气的」。"},{"word":"ingenium","structure":"Latin noun","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思","example":"It is the root of engineer.","exampleCN":"它是「工程师」的词根。"},{"word":"in-","structure":"Latin prefix","meaning":"in, within","meaningCN":"在内","example":"It forms the first part of ingenium.","exampleCN":"它构成「巧思」一词的前半。"},{"word":"gignere","structure":"Latin verb","meaning":"to beget, to produce","meaningCN":"生育、产生","example":"It supplies the second part of ingenium.","exampleCN":"它提供「巧思」一词的后半。"},{"word":"engin","structure":"Old French noun","meaning":"a clever device","meaningCN":"精巧装置","example":"French carried the root toward English.","exampleCN":"法语把这个词根带向英语。"},{"word":"engineer","structure":"English noun","meaning":"a person who designs works","meaningCN":"设计工程的人","example":"The person noun precedes the activity noun.","exampleCN":"人称名词先于活动名词出现。"},{"word":"engineering","structure":"English noun","meaning":"the profession of designing works","meaningCN":"设计工程的专业","example":"The ending -ing names the organised activity.","exampleCN":"词尾把有组织的活动命名为「工程」。"}],"latinEntries":[{"word":"electrum","structure":"electrum, electri (n., second declension, from Greek)","meaning":"amber; electrum alloy","meaningCN":"琥珀；琥珀金"},{"word":"electricus","structure":"electricus (adj., first-second declension, New Latin)","meaning":"of amber; producing electricity","meaningCN":"琥珀的；产生电的"},{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思"}],"derivatives":[{"word":"electric","pos":"adj.","zh":"由「电的」短形容词构成，义为「电的」"},{"word":"electricity","pos":"n.","zh":"由「电的」加性质名词词尾构成，义为「电」"},{"word":"electrician","pos":"n.","zh":"由「电的」加从业者词尾构成，义为「电工」"},{"word":"electrify","pos":"v.","zh":"由「电的」加使动词尾构成，义为「使带电、电气化」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加活动词尾构成，义为「工程、工程学」"}]}},{"word":"electronic engineering","ipa_uk":"/ɪˌlekˈtrɒnɪk ˌendʒɪˈnɪərɪŋ/","ipa_us":"/ɪˌlekˈtrɑːnɪk ˌendʒɪˈnɪrɪŋ/","definition_zh":"研究电子器件、电子电路与信号处理，并据此设计电子系统的工程学科","definition_en":"the branch of engineering that deals with electronic devices, circuits and signal processing, and designs electronic systems","core_image":"示波器屏幕上，一条细小的电压波形被放大、整形、再送入下一级电路，信号逐级变得清晰","scene":"实验室里，学生把示波器探头接到电路板上，观察放大后的信号波形。The electronic engineering lab built a low-noise amplifier.","sceneCN":"这里指研究电子器件与电路并设计电子系统的学科（第 1 个义项：研究电子器件、电子电路与信号处理并设计电子系统的工程学科）；句意：电子工程实验室造出了一台低噪声放大器。","pos":[{"tag":"n.","zh":"电子工程；电子工程学"}],"collocations":[{"phrase":"electronic engineering department","zh":"电子工程系"},{"phrase":"electronic engineering student","zh":"电子工程专业学生"},{"phrase":"electronic engineering design","zh":"电子工程设计"},{"phrase":"electronic engineering practice","zh":"电子工程实务"},{"phrase":"electronic engineering textbook","zh":"电子工程教材"}],"forms":[{"label":"学科名称（不可数）","form":"electronic engineering"},{"label":"从业者","form":"electronic engineer"},{"label":"形容词形式","form":"electronic"},{"label":"名词形式","form":"electronics"},{"label":"名词形式（单数）","form":"electron"},{"label":"相关形容词","form":"electrical"}],"derivatives":[{"word":"electron","pos":"n.","zh":"由希腊语「琥珀」加表示粒子的词尾构成，义为「电子」"},{"word":"electronic","pos":"adj.","zh":"由「电子」加形容词词尾构成，义为「电子的」"},{"word":"electronics","pos":"n.","zh":"由「电子的」加表示学科的名词词尾构成，义为「电子学、电子器件」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加表示活动的词尾构成，义为「工程、工程学」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"},{"word":"amplifier","pos":"n.","zh":"由拉丁语「放大」加表示工具的词尾构成，义为「放大器」"},{"word":"circuit","pos":"n.","zh":"由拉丁语「绕行一圈」进入英语，义为「电路、回路」"}],"senses":[{"no":"01","title":"The discipline of small signals","titleCN":"弱信号学科","definition":"the branch of engineering that designs circuits and devices which process small electrical signals","definitionCN":"设计处理微弱电信号的电路与器件的工程分支","example":"He studied electronic engineering to work on medical sensors.","exampleCN":"他学电子工程，是为了从事医疗传感器的工作。","why":"Electronic marks work done by electrons in circuits, and engineering marks the profession, so the phrase names the discipline.","whyCN":"「电子的」标出由电路中的电子完成的工作，「工程」标出专业，因此这个词组就是学科名称。"},{"no":"02","title":"Circuits and signal processing","titleCN":"电路与信号处理","definition":"the design of amplifier, filter and conversion circuits that shape a signal","definitionCN":"设计放大、滤波与转换电路以整形信号","example":"Electronic engineering turns a noisy voltage into a clean digital reading.","exampleCN":"电子工程把带噪声的电压变成干净的数字读数。","why":"The discipline's daily work is to make a signal usable, and that work is done by circuits.","whyCN":"该学科的日常工作就是让信号变得可用，而这项工作由电路完成。"},{"no":"03","title":"Semiconductor devices","titleCN":"半导体器件","definition":"the study of transistors, diodes and integrated chips as physical components","definitionCN":"把晶体管、二极管与集成芯片作为实体器件来研究","example":"Electronic engineering depends on a steady supply of tested chips.","exampleCN":"电子工程依赖稳定供应经过测试的芯片。","why":"Every circuit rests on devices, so the phrase also covers the physics and manufacture of those parts.","whyCN":"每个电路都建立在器件上，因此这个词组也覆盖这些部件的物理与制造。"},{"no":"04","title":"Embedded systems","titleCN":"嵌入式系统","definition":"the design of small computers built into machines to sense and control them","definitionCN":"设计嵌入机器内部、用于感知与控制的微型计算机系统","example":"Electronic engineering put a tiny controller inside the washing machine.","exampleCN":"电子工程把一枚微型控制器装进了洗衣机。","why":"When a circuit carries its own processor, the discipline moves from signal shaping to machine control.","whyCN":"当电路自带处理器时，该学科便从信号整形走向机器控制。"},{"no":"05","title":"Communication electronics","titleCN":"通信电子","definition":"the design of circuits that send and receive information by radio, light or cable","definitionCN":"设计通过无线电、光或电缆收发信息的电路","example":"Electronic engineering keeps the radio link stable in heavy rain.","exampleCN":"电子工程让无线电链路在大雨中保持稳定。","why":"Communication is the oldest large market for small-signal circuits, so the phrase often points there.","whyCN":"通信是弱信号电路最古老的大市场，因此这个词组常指向那里。"},{"no":"06","title":"Consumer product electronics","titleCN":"消费电子产品","definition":"the design of the circuits inside phones, audio gear and household appliances","definitionCN":"设计手机、音响与家用电器内部的电路","example":"Electronic engineering made the speaker smaller without losing bass.","exampleCN":"电子工程让音箱变小却没有损失低音。","why":"Mass-market products carry the discipline's results into daily life, and the phrase follows them there.","whyCN":"大众产品把该学科的成果带进日常生活，这个词组也随之进入那里。"},{"no":"07","title":"A degree programme","titleCN":"学位课程","definition":"the university course that trains students in devices, circuits and systems","definitionCN":"培养学生在器件、电路与系统方面能力的大学课程","example":"The electronic engineering programme requires a lab project every term.","exampleCN":"电子工程专业每学期都要求做一个实验项目。","why":"A discipline becomes a named course of study, so the phrase also labels the degree.","whyCN":"学科会成为命名的课程，因此这个词组也指学位。"},{"no":"08","title":"System integration","titleCN":"系统集成","definition":"the work of joining sensors, circuits, power and software into one working product","definitionCN":"把传感器、电路、电源与软件组合成一个可用产品的工作","example":"Electronic engineering joins the parts, but the casing team joins the box.","exampleCN":"电子工程负责连接内部部件，外壳团队负责拼装外壳。","why":"No product is only a circuit, so the discipline's last step is to make everything work together.","whyCN":"没有产品只是电路，因此该学科的最后一步是让所有部分协同工作。"}],"etymology":{"intro":{"en":"Electronic engineering combines a nineteenth-century scientific coinage for the electron with the older word for the engineering profession.","cn":"「电子工程」把一个十九世纪为电子造出的科学新词，与更古老的「工程专业」一词组合起来。"},"items":[{"era":"GREEK ELEKTRON","en":"Elektron meant amber, whose rubbed surface first revealed electric attraction; this Greek word is the direct source, while its deeper origin is uncertain and the link to a word for the beaming sun remains a suggested reconstruction.","cn":"这个希腊语名词指琥珀，摩擦后的表面最早显露电吸引现象；它是本词的直接来源，其更早词根存疑，与表示「闪耀太阳」之词的关联只是重构性推测。"},{"era":"NEW LATIN ELECTRICUS","en":"Sixteenth-century scholars coined electricus for the amber effect, and English electric followed in the seventeenth century.","cn":"十六世纪学者为琥珀效应造出「电的」这一新拉丁语形容词，英语随后在十七世纪出现「电的」。"},{"era":"ELECTRON COINED","en":"In 1891 the Irish physicist Stoney proposed electron, adding a Greek neuter ending to the amber root, for the unit of charge; the particle later took the name.","cn":"一八九一年，爱尔兰物理学家为电荷单位提出「电子」一词，在「琥珀」词根后加上希腊语中性词尾；该粒子后来采用了这个名称。"},{"era":"ENGLISH ELECTRONIC","en":"The adjective electronic appeared around the turn of the twentieth century, once devices used electrons rather than bulk current.","cn":"「电子的」这一形容词在二十世纪之交出现，当时器件开始使用电子而非整块电流。"},{"era":"LATIN INGENIUM","en":"Ingenium meant natural ability; through French engin it produced English engineer, the person who designs works.","cn":"这个拉丁语名词指天赋，经法语指精巧装置的一词，产生了英语「工程师」，即设计工程的人。"},{"era":"TWENTIETH CENTURY PAIRING · FIRST RECORD DATE UNCERTAIN","en":"As radio, radar and computers grew, the two words were fixed together for the branch that designs circuits rather than power networks; the exact year of first record is uncertain.","cn":"随着无线电、雷达与计算机的发展，这两个词被固定组合，指设计电路而非电力网络的分支；具体首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the electron root; the second group names adjacent branches and products.","cn":"第一组共享「电子」词根；第二组是相邻分支与产品。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"electron","ipa":"/ɪˈlektrɒn/","tag":"noun","definition":"The charged particle itself; the discipline is named after it.","definitionCN":"带电粒子本身；学科以它命名。"},{"word":"electronics","ipa":"/ɪˌlekˈtrɒnɪks/","tag":"noun","definition":"The field or its devices collectively; it can mean the gadgets as well as the study.","definitionCN":"该领域或其器件的总称；既可指学问，也可指电子产品。"},{"word":"electronic","ipa":"/ɪˌlekˈtrɒnɪk/","tag":"adjective","definition":"Worked by electrons in circuits; the adjective inside the target phrase.","definitionCN":"靠电路中电子运作的；目标词组内的形容词。"},{"word":"electrical","ipa":"/ɪˈlektrɪkəl/","tag":"adjective","definition":"Of electricity in bulk; it contrasts with the small-signal world of the target.","definitionCN":"大电流意义上的电的；与目标词组的弱信号世界相对。"}]},{"heading":"NEAR MEANING","entries":[{"word":"electrical engineering","ipa":"/ɪˈlektrɪkəl ˌendʒɪˈnɪərɪŋ/","tag":"noun","definition":"The branch of grids, motors and heavy plant; the target works at low power and high precision.","definitionCN":"电网、电机与重型设备的分支；目标词则工作在低功率与高精度上。"},{"word":"microelectronics","ipa":"/ˌmaɪkrəʊɪˌlekˈtrɒnɪks/","tag":"noun","definition":"The part of the field that builds tiny integrated circuits; narrower than the whole discipline.","definitionCN":"该领域中制造微型集成电路的部分；比整个学科窄。"},{"word":"circuit design","ipa":"/ˈsɜːkɪt dɪˈzaɪn/","tag":"noun","definition":"The activity of drawing and testing a circuit; it is one task within the discipline.","definitionCN":"绘制并测试电路的活动；只是该学科中的一项任务。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The stem is the amber word again, here narrowed to the particle that carries charge.","cn":"词干仍是「琥珀」一词，这里缩小为携带电荷的粒子。"},{"en":"The family runs electron, electronic, electronics and electronic engineering.","cn":"同族词包括电子、电子的、电子学与电子工程。"},{"en":"Fixed phrases mark it: electronic engineering lab, electronic engineering design.","cn":"固定搭配可标记它：电子工程实验室、电子工程设计。"},{"en":"Its tools are the oscilloscope, the soldering iron and the chip tester.","cn":"它的工具是示波器、烙铁与芯片测试仪。"},{"en":"Its products are phones, radios, sensors and controllers.","cn":"它的产品是手机、无线电、传感器与控制器。"}],"abstract":[{"en":"Picture a whisper made loud enough for a hall to hear, without changing the words.","cn":"想象一声耳语被放大到全场都听得见，却没有改变字句。"},{"en":"Picture a traffic signal that lets only the useful cars through.","cn":"想象一个交通信号，只放有用的车辆通过。"},{"en":"Picture a fingernail-sized city where every street is a wire.","cn":"想象一座指甲盖大的城市，每条街道都是一根导线。"}]},"examples":[{"en":"Electronic engineering explains why the microphone picks up a hum.","cn":"电子工程能解释麦克风为何会拾到嗡嗡声。"},{"en":"The electronic engineering lab has benches for soldering and for testing chips.","cn":"电子工程实验室有焊接台与芯片测试台。"},{"en":"She moved from electronic engineering into medical device design.","cn":"她从电子工程转向了医疗器件设计。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「琥珀」引出电子，电子走进电路——小信号做成大系统","word":"electronic engineering"},"root":"前半由希腊语「琥珀」经新拉丁语「电的」再在十九世纪加词尾造出「电子」，后半源自拉丁语「巧思」经法语的「工程师」；琥珀词源存疑。","sensesIntro":{"en":"Eight senses follow one direction: a weak signal is captured, shaped, converted and finally joined to a product. The phrase covers the discipline, the circuit, the device, the embedded controller, the radio, the consumer product, the degree and the integration.","cn":"八个义项沿一个方向展开：微弱信号被拾取、整形、转换，最后并入产品。这个词组覆盖学科、电路、器件、嵌入式控制器、无线电、消费产品、学位与系统集成。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tiny voltage entering a chain of circuits and leaving as a clean, usable signal.","cn":"核心意象：一个微小电压进入一串电路，出来时已成为干净可用的信号。"},"chain":["ELECTRON FLOW","CIRCUIT","DEVICE","SIGNAL","EMBEDDED CONTROL","INTEGRATED PRODUCT"],"branches":[{"senses":"01 · 02","en":"THE DISCIPLINE AND ITS DAILY TASK: small-signal engineering and the circuits that shape signals.","cn":"学科与其日常任务：弱信号工程与整形信号的电路。"},{"senses":"03","en":"THE PHYSICAL BASE: transistors, diodes and chips as real parts.","cn":"物理基础：作为实体零件的晶体管、二极管与芯片。"},{"senses":"04","en":"THE CONTROL VERSION: a processor built into a machine.","cn":"控制版本：装进机器内部的处理器。"},{"senses":"05 · 06","en":"THE TWO MARKETS: radio links and mass-market products.","cn":"两个市场：无线电链路与大众产品。"},{"senses":"07 · 08","en":"THE PROFESSIONAL WRAPPER: the degree and the final integration work.","cn":"职业外壳：学位与最后的集成工作。"}]},"affixes":{"intro":{"en":"One half is a modern scientific coinage from Greek amber; the other half is the Latin-rooted word for the profession.","cn":"一半是由希腊语「琥珀」造出的现代科学新词，另一半是拉丁语词根的「工程专业」。"},"latinIntro":{"en":"Latin supplies the amber adjective and the word for cleverness behind engineer.","cn":"拉丁语提供了「琥珀」的形容词，以及「工程师」背后的「巧思」一词。"},"items":[{"word":"elektron","structure":"Greek noun","meaning":"amber","meaningCN":"琥珀","example":"The root of every electric word.","exampleCN":"所有含电义词的根。"},{"word":"-on","structure":"Greek neuter ending","meaning":"a unit or particle","meaningCN":"单位或粒子","example":"The ending turned the root into a particle name.","exampleCN":"这个词尾把词根变成粒子名。"},{"word":"electricus","structure":"New Latin adjective","meaning":"of amber; electric","meaningCN":"琥珀的；电的","example":"The adjective reached English as electric.","exampleCN":"这个形容词以「电的」进入英语。"},{"word":"electronic","structure":"English adjective","meaning":"of electrons or electron devices","meaningCN":"电子的；电子器件的","example":"The adjective is the first half of the target.","exampleCN":"这个形容词是目标词组的前半。"},{"word":"ingenium","structure":"Latin noun","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思","example":"The root behind engineer.","exampleCN":"「工程师」背后的词根。"},{"word":"in-","structure":"Latin prefix","meaning":"in, within","meaningCN":"在内","example":"It forms the first part of ingenium.","exampleCN":"它构成「巧思」的前半。"},{"word":"gignere","structure":"Latin verb","meaning":"to beget, produce","meaningCN":"生育、产生","example":"It forms the second part of ingenium.","exampleCN":"它构成「巧思」的后半。"},{"word":"engin","structure":"Old French noun","meaning":"a clever device","meaningCN":"精巧装置","example":"French carried the root to English.","exampleCN":"法语把词根带到英语。"},{"word":"engineer","structure":"English noun","meaning":"designer of works","meaningCN":"工程设计者","example":"The profession noun.","exampleCN":"专业人员的名词。"},{"word":"-ing","structure":"English noun ending","meaning":"the activity of","meaningCN":"……的活动","example":"It names the organised profession.","exampleCN":"它命名有组织的专业活动。"}],"latinEntries":[{"word":"electricus","structure":"electricus (adj., first-second declension, New Latin)","meaning":"of amber; electric","meaningCN":"琥珀的；电的"},{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思"}],"derivatives":[{"word":"electron","pos":"n.","zh":"由「琥珀」词根加中性词尾构成，义为「电子」"},{"word":"electronic","pos":"adj.","zh":"由「电子」加形容词词尾构成，义为「电子的」"},{"word":"electronics","pos":"n.","zh":"由「电子的」加学科名词词尾构成，义为「电子学」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加活动词尾构成，义为「工程学」"},{"word":"electrical","pos":"adj.","zh":"由「电的」加完整形容词词尾构成，义为「电气的」"}]}},{"word":"civil engineering","ipa_uk":"/ˈsɪvəl ˌendʒɪˈnɪərɪŋ/","ipa_us":"/ˈsɪvəl ˌendʒɪˈnɪrɪŋ/","definition_zh":"设计并建造道路、桥梁、水坝、建筑基础与市政设施等公共工程的学科","definition_en":"the branch of engineering that designs and builds public works such as roads, bridges, dams, foundations and water systems","core_image":"河谷两岸，桥墩从河床立起，钢梁横跨水面，路面把两侧的村镇连成一条通路","scene":"河岸工地上，测量员架起水准仪，工程师核对桥墩的标高与跨度。Civil engineering gave the valley its first all-weather bridge.","sceneCN":"这里指负责桥梁、道路等公共工程的土木工程学科（第 1 个义项：设计并建造道路、桥梁、水坝、建筑基础与市政设施等公共工程的学科）；句意：土木工程为这条河谷造出了第一座全天候桥梁。","pos":[{"tag":"n.","zh":"土木工程；土木工程学"}],"collocations":[{"phrase":"civil engineering project","zh":"土木工程项目"},{"phrase":"civil engineering firm","zh":"土木工程公司"},{"phrase":"civil engineering works","zh":"土木工程设施"},{"phrase":"civil engineering contract","zh":"土木工程合同"},{"phrase":"civil engineering degree","zh":"土木工程学位"}],"forms":[{"label":"学科名称（不可数）","form":"civil engineering"},{"label":"从业者","form":"civil engineer"},{"label":"形容词形式","form":"civil"},{"label":"名词形式","form":"civilian"},{"label":"名词形式（工程）","form":"engineer"},{"label":"相关名词","form":"engineering"}],"derivatives":[{"word":"civil","pos":"adj.","zh":"由拉丁语「公民」加形容词词尾构成，义为「公民的、民用的」"},{"word":"civilian","pos":"n.","zh":"由「公民的」加表示人的词尾构成，义为「平民」"},{"word":"civic","pos":"adj.","zh":"由拉丁语「城市、公民」词干加形容词词尾构成，义为「城市的、公民的」"},{"word":"civilize","pos":"v.","zh":"由「公民的」加使动词尾构成，义为「使文明化」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加活动词尾构成，义为「工程、工程学」"},{"word":"infrastructure","pos":"n.","zh":"由拉丁语「在下」与「结构」组合，义为「基础设施」"}],"senses":[{"no":"01","title":"The discipline of public works","titleCN":"公共工程学科","definition":"the branch of engineering concerned with the design and construction of public works","definitionCN":"负责公共工程设计与施工的工程分支","example":"Civil engineering built the road that connects the two towns.","exampleCN":"土木工程建起了连接两镇的公路。","why":"Civil here means civilian rather than military, and engineering means the profession, so the phrase names the non-military branch.","whyCN":"这里的「民用」与「军用」相对，「工程」指专业，因此这个词组命名非军用的工程分支。"},{"no":"02","title":"Structures and buildings","titleCN":"结构与建筑","definition":"the analysis and construction of load-bearing frames, foundations and building shells","definitionCN":"承重框架、基础与建筑外壳的分析与施工","example":"Civil engineering checked the foundation before the columns rose.","exampleCN":"土木工程在立柱之前检查了基础。","why":"Buildings stand on works that the discipline designs, so the phrase covers the supporting structure.","whyCN":"建筑立在专业所设计的工作之上，因此这个词组涵盖承重结构。"},{"no":"03","title":"Roads and transport works","titleCN":"道路与交通工程","definition":"the design of highways, pavements, junctions and railway earthworks","definitionCN":"公路、路面、交叉口与铁路土方的设计","example":"Civil engineering straightened the bend that caused so many crashes.","exampleCN":"土木工程把那个事故频发的弯道改直了。","why":"Movement between places needs prepared ground, and preparing that ground is a core civil task.","whyCN":"地点之间的移动需要整备过的地面，而整备地面正是土木的核心任务。"},{"no":"04","title":"Bridges and tunnels","titleCN":"桥梁与隧道","definition":"the design of spans, piers and underground passages that cross water, valleys or hills","definitionCN":"设计跨越水域、河谷或山体的桥跨、桥墩与地下通道","example":"Civil engineering carried the railway through the mountain in a tunnel.","exampleCN":"土木工程用一条隧道让铁路穿过了这座山。","why":"Crossing an obstacle is the most visible civil work, so the phrase often points to bridges and tunnels.","whyCN":"跨越障碍是最显眼的土木工程，因此这个词组常指桥梁与隧道。"},{"no":"05","title":"Water and drainage","titleCN":"水利与给排水","definition":"the design of dams, canals, water supply and sewage systems","definitionCN":"设计水坝、渠道、供水与污水系统","example":"Civil engineering brought clean water to every street in the district.","exampleCN":"土木工程把干净的水送到了该区每条街道。","why":"Water must be stored, moved and removed, and all three are civil works.","whyCN":"水需要被蓄存、输送与排出，这三件事都是土木工程。"},{"no":"06","title":"Ground and foundations","titleCN":"岩土与地基","definition":"the study of soil and rock and the design of foundations and retaining walls","definitionCN":"研究土与岩石，并设计基础与挡土墙","example":"Civil engineering tested the clay before choosing the pile length.","exampleCN":"土木工程在选择桩长之前测试了黏土。","why":"Every structure meets the ground, and the discipline owns that meeting.","whyCN":"每座结构都要与地面相接，而这一交接由该学科负责。"},{"no":"07","title":"The degree and the profession","titleCN":"学位与职业","definition":"the university programme and the licensed profession that train and regulate civil engineers","definitionCN":"培养与规范土木工程师的大学课程及执业制度","example":"She took a civil engineering degree and then joined a bridge team.","exampleCN":"她取得土木工程学位后加入了一个桥梁团队。","why":"The discipline is also a course and a licence, so the phrase names the career as well as the knowledge.","whyCN":"学科同时是课程与执照，因此这个词组既指知识，也指职业。"},{"no":"08","title":"Municipal and urban works","titleCN":"市政与城市工程","definition":"the public works of a city, including streets, drains, parks and public buildings","definitionCN":"城市的公共工程，包括街道、排水、公园与公共建筑","example":"Civil engineering rebuilt the square without closing the shops.","exampleCN":"土木工程在不关店铺的情况下重建了广场。","why":"Cities are built from many small civil works, so the phrase extends from single bridges to whole streets.","whyCN":"城市由许多小型土木工程组成，因此这个词组从单座桥扩展到整条街。"}],"etymology":{"intro":{"en":"Civil engineering pairs the Latin adjective for citizen with the profession word from ingenium; the term once separated civilian works from military ones.","cn":"「土木工程」把拉丁语中表示「公民」的形容词，与源自「巧思」的专业词配对；这个术语最初用来把民用工程与军事工程分开。"},"items":[{"era":"LATIN CIVIS","en":"Civis meant citizen, and it is the direct Latin source of the first half; its deeper root is uncertain, and a link to a root for lying or settling is only a suggestion.","cn":"这个拉丁语名词指公民，是前半的直接拉丁语来源；它更早的词根存疑，与表示「躺卧、定居」之词根的关联仅为推测。"},{"era":"LATIN CIVILIS","en":"Civilis meant of a citizen or of citizens as a body, and it became the English adjective civil.","cn":"这个拉丁语形容词指公民的、属于公民整体的，后来成为英语的「民用的、公民的」。"},{"era":"LATIN INGENIUM","en":"Ingenium meant natural ability or cleverness; French engin, a clever device, produced English engineer.","cn":"这个拉丁语名词指天赋或巧思；法语中指精巧装置的一词产生了英语「工程师」。"},{"era":"MILITARY CONTRAST · FIRST RECORD DATE UNCERTAIN","en":"In the eighteenth century the growing body of non-military works needed a name, and civil engineering was chosen to contrast with military engineering; the exact year when the term was first used is uncertain.","cn":"十八世纪，日益增多的非军事工程需要名称，人们选用「土木工程」来与军事工程相对；该术语具体首见年代不确定。"},{"era":"NINETEENTH CENTURY PROFESSION","en":"Roads, railways, canals and water works made the term the name of a recognised profession with its own schools.","cn":"道路、铁路、运河与水利工程使这个术语成为一个有专门学校的公认专业之名。"},{"era":"MODERN SCOPE","en":"The phrase now covers structures, transport, water, ground and whole municipal systems, while military works keep their separate name.","cn":"这个词组如今涵盖结构、交通、水利、岩土与整个市政系统，军事工程则保留自己的名称。"}]},"similar":{"note":{"en":"The first group shares the citizen root; the second group names neighbouring built-environment fields.","cn":"第一组共享「公民」词根；第二组是相邻的建成环境领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"civil","ipa":"/ˈsɪvəl/","tag":"adjective","definition":"Of citizens or of civilian life; inside the phrase it contrasts with military.","definitionCN":"公民的、平民生活的；在词组内与军事相对。"},{"word":"civic","ipa":"/ˈsɪvɪk/","tag":"adjective","definition":"Of a city and its public life; it describes the city, not the profession.","definitionCN":"城市的、市民公共生活的；描述城市，而非专业。"},{"word":"civilian","ipa":"/sɪˈvɪljən/","tag":"noun","definition":"A person who is not in the armed forces; a person word, not a field.","definitionCN":"不在军队中的人；是人称名词，不是领域。"},{"word":"civilize","ipa":"/ˈsɪvəlaɪz/","tag":"verb","definition":"To bring order and manners; it shares the root but not the engineering sense.","definitionCN":"使有秩序与教养；共享词根但无工程含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"structural engineering","ipa":"/ˈstrʌktʃərəl ˌendʒɪˈnɪərɪŋ/","tag":"noun","definition":"The part of civil work that analyses load-bearing frames; narrower than the whole field.","definitionCN":"土木工作中分析承重框架的部分；比整个领域窄。"},{"word":"public works","ipa":"/ˈpʌblɪk wɜːks/","tag":"noun","definition":"The built facilities themselves, not the discipline that designs them.","definitionCN":"建成的公共设施本身，而非设计它们的学科。"},{"word":"infrastructure","ipa":"/ˌɪnfrəˈstrʌktʃə/","tag":"noun","definition":"The networks and facilities a society needs; the target is the profession that builds them.","definitionCN":"社会所需的网络与设施；目标词是建造它们的专业。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Civil points to citizens and civilian life, not to soldiers.","cn":"「民用」指向公民与平民生活，而不是军人。"},{"en":"Engineering points to the profession that designs works.","cn":"「工程」指向设计工程的专业。"},{"en":"The family runs civil, civic, civilian, civilize and civil engineering.","cn":"同族词包括民用的、城市的、平民、使文明化与土木工程。"},{"en":"Fixed phrases mark it: civil engineering project, civil engineering firm, civil engineering works.","cn":"固定搭配可标记它：土木工程项目、土木工程公司、土木工程设施。"},{"en":"Its landmarks are bridges, roads, dams, tunnels and foundations.","cn":"它的地标是桥、路、坝、隧道与基础。"}],"abstract":[{"en":"Picture a skeleton of concrete laid under a whole city so that daily life can walk on it.","cn":"想象一副铺在整座城市下的混凝土骨架，让日常生活能在上面行走。"},{"en":"Picture a river taught to run where people need it, not where it used to.","cn":"想象一条河被教会在人需要的地方流，而不是原来流的地方。"},{"en":"Picture a bridge that joins two villages which had never met.","cn":"想象一座桥把两个从未相遇的村庄连起来。"}]},"examples":[{"en":"Civil engineering kept the new road above the flood line.","cn":"土木工程让新公路建在洪水线之上。"},{"en":"The civil engineering team spent a year testing the river bed.","cn":"土木工程团队花了一年测试河床。"},{"en":"Without civil engineering the harbour would silt up within a decade.","cn":"没有土木工程，这个港口十年内就会淤塞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「公民」+「巧思」——为公众造桥修路的手艺","word":"civil engineering"},"root":"前半源自拉丁语「公民」，后半源自拉丁语「巧思」经法语的「工程师」；公民一词更早的来源存疑。","sensesIntro":{"en":"Eight senses follow one line: a public work is planned, founded, spanned, drained and handed to a city. The phrase covers the discipline, structures, roads, crossings, water, ground, the profession and municipal works.","cn":"八个义项沿一条线展开：公共工程被规划、打基础、跨越、排水，最后交给城市使用。这个词组覆盖学科、结构、道路、跨越、水利、岩土、职业与市政工程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line of built works joining land, water and people, each part resting on prepared ground.","cn":"核心意象：一串建成的工程把土地、水与人连接起来，每一部分都立在整备过的地面上。"},"chain":["BUILT ENVIRONMENT","LOAD-BEARING STRUCTURE","TRANSPORT ROUTE","WATER WORKS","GROUND SUPPORT","PUBLIC WORKS"],"branches":[{"senses":"01 · 02","en":"THE DISCIPLINE AND ITS STRUCTURES: public works and the frames that carry them.","cn":"学科与其结构：公共工程以及承载它们的框架。"},{"senses":"03","en":"THE ROUTE VERSION: roads, pavements and railway earthworks.","cn":"路线版本：公路、路面与铁路土方。"},{"senses":"04","en":"THE CROSSING VERSION: bridges and tunnels through water, valley or hill.","cn":"跨越版本：跨越水域、河谷或山体的桥与隧道。"},{"senses":"05 · 06","en":"THE WATER AND GROUND VERSION: supply, drainage, soil and foundations.","cn":"水土版本：供水、排水、土与基础。"},{"senses":"07 · 08","en":"THE PROFESSIONAL AND URBAN VERSION: the degree, the licence and whole municipal systems.","cn":"职业与城市版本：学位、执照与整个市政系统。"}]},"affixes":{"intro":{"en":"The citizen adjective and the cleverness noun are both Latin; the pairing marked a civilian branch beside military engineering.","cn":"「公民」形容词与「巧思」名词都来自拉丁语；这个配对标出了与军事工程并列的民用分支。"},"latinIntro":{"en":"Latin civis and civilis name the citizen half; ingenium names the profession half.","cn":"拉丁语的「公民」与「公民的」构成前半，「巧思」构成后半。"},"items":[{"word":"civis","structure":"Latin noun","meaning":"citizen","meaningCN":"公民","example":"The root of the civil half.","exampleCN":"「民用」一半的词根。"},{"word":"civilis","structure":"Latin adjective","meaning":"of citizens","meaningCN":"公民的","example":"It became the English adjective civil.","exampleCN":"它成为英语的「民用的」。"},{"word":"-ian","structure":"adjective and noun ending","meaning":"belonging to","meaningCN":"属于……的","example":"It forms civilian from the same root.","exampleCN":"它用同一词根构成「平民」。"},{"word":"civitas","structure":"Latin noun","meaning":"citizenship, city","meaningCN":"公民身份、城市","example":"It stands behind civic and city words.","exampleCN":"它支撑「城市的」等词。"},{"word":"ingenium","structure":"Latin noun","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思","example":"The root of engineer.","exampleCN":"「工程师」的词根。"},{"word":"in-","structure":"Latin prefix","meaning":"in, within","meaningCN":"在内","example":"It begins ingenium.","exampleCN":"它构成「巧思」的前半。"},{"word":"gignere","structure":"Latin verb","meaning":"to beget, produce","meaningCN":"生育、产生","example":"It ends ingenium.","exampleCN":"它构成「巧思」的后半。"},{"word":"engin","structure":"Old French noun","meaning":"clever device","meaningCN":"精巧装置","example":"It carried the root to English.","exampleCN":"它把词根带到英语。"},{"word":"engineer","structure":"English noun","meaning":"designer of works","meaningCN":"工程设计者","example":"The profession noun.","exampleCN":"专业人员名词。"},{"word":"-ing","structure":"English noun ending","meaning":"the activity of","meaningCN":"……的活动","example":"It names the organised profession.","exampleCN":"它命名有组织的专业活动。"}],"latinEntries":[{"word":"civis","structure":"civis, civis (n., third declension)","meaning":"citizen","meaningCN":"公民"},{"word":"civilis","structure":"civilis, civile (adj., third declension)","meaning":"of a citizen; civil","meaningCN":"公民的；民用的"},{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思"}],"derivatives":[{"word":"civil","pos":"adj.","zh":"由拉丁语「公民」加形容词词尾构成，义为「民用的」"},{"word":"civilian","pos":"n.","zh":"由「民用的」加人称词尾构成，义为「平民」"},{"word":"civic","pos":"adj.","zh":"由拉丁语「城市、公民」词干构成，义为「城市的」"},{"word":"civilize","pos":"v.","zh":"由「民用的」加使动词尾构成，义为「使文明化」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"},{"word":"engineering","pos":"n.","zh":"由「工程师」加活动词尾构成，义为「工程学」"}]}},{"word":"structural engineering","ipa_uk":"/ˈstrʌktʃərəl ˌendʒɪˈnɪərɪŋ/","ipa_us":"/ˈstrʌktʃərəl ˌendʒɪˈnɪrɪŋ/","definition_zh":"研究结构如何安全承受荷载、并把力从一点传到另一点的工程分支","definition_en":"the branch of engineering that studies how structures carry loads safely and pass force from one point to another","core_image":"钢梁上的砝码一级级加重，梁身微微下弯，力沿着梁腹传到两端支座，支座再把力压进地面","scene":"台风过后，塔身轻微倾斜却没有倒塌，检查人员沿基座查看支撑构件。Good structural engineering kept the tower standing through the typhoon.","sceneCN":"这里指研究结构承重与传力的工程分支（第 1 个义项：研究结构如何安全承受荷载并把力从一点传到另一点的工程分支）；句意：良好的结构工程让这座塔在台风中屹立不倒。","pos":[{"tag":"n.","zh":"结构工程；结构工程学"}],"collocations":[{"phrase":"structural engineering design","zh":"结构工程设计"},{"phrase":"structural engineering firm","zh":"结构工程公司"},{"phrase":"structural engineering analysis","zh":"结构工程分析"},{"phrase":"structural engineering software","zh":"结构工程软件"},{"phrase":"structural engineering consultant","zh":"结构工程顾问"}],"forms":[{"label":"学科名称（不可数）","form":"structural engineering"},{"label":"从业者","form":"structural engineer"},{"label":"形容词形式","form":"structural"},{"label":"名词形式","form":"structure"},{"label":"动词形式","form":"structure"},{"label":"副词形式","form":"structurally"}],"derivatives":[{"word":"structure","pos":"n.","zh":"由拉丁语「建造」加表示结果的名词词尾构成，义为「结构」"},{"word":"structural","pos":"adj.","zh":"由「结构」加形容词词尾构成，义为「结构的」"},{"word":"structurally","pos":"adv.","zh":"由「结构的」加副词词尾构成，义为「结构上」"},{"word":"construct","pos":"v.","zh":"由拉丁语「一起建造」构成，义为「建造」"},{"word":"construction","pos":"n.","zh":"由「建造」加表示结果的名词词尾构成，义为「建造、施工」"},{"word":"instruct","pos":"v.","zh":"由拉丁语「在内建造」构成，义为「指导、教导」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"}],"senses":[{"no":"01","title":"The branch that checks load paths","titleCN":"校核传力路径的分支","definition":"the branch of engineering that analyses how loads travel through a structure and whether every member can carry them","definitionCN":"分析荷载如何在结构中传递、每个构件能否承担的分析分支","example":"Structural engineering decides which member carries which load.","exampleCN":"结构工程决定哪个构件承担哪一份荷载。","why":"Structural marks the frame, engineering marks the profession, so the phrase names the branch that reads the frame.","whyCN":"「结构的」标出框架，「工程」标出专业，因此这个词组指解读框架的分支。"},{"no":"02","title":"Loads and forces","titleCN":"荷载与受力","definition":"the calculation of dead, live, wind and seismic loads and the forces they produce","definitionCN":"计算恒载、活载、风载与地震荷载及其产生的内力","example":"Structural engineering added the wind load that the first design ignored.","exampleCN":"结构工程补上了初版设计忽略的风荷载。","why":"Before a member can be sized, its loads must be known, so load study is the branch's first task.","whyCN":"构件定尺寸之前必须先知道荷载，因此荷载研究是该分支的首要任务。"},{"no":"03","title":"Steel design","titleCN":"钢结构设计","definition":"the sizing and connection of steel beams, columns and frames","definitionCN":"钢梁、钢柱与钢框架的选型与连接设计","example":"Structural engineering chose a steel frame for the long span.","exampleCN":"结构工程为这一大跨度选择了钢框架。","why":"Steel carries tension well, so the branch uses it where spans must be light and long.","whyCN":"钢材抗拉性能好，该分支便把它用在需要轻而长的跨度处。"},{"no":"04","title":"Concrete structures","titleCN":"混凝土结构","definition":"the design of reinforced concrete beams, slabs and columns","definitionCN":"钢筋混凝土梁、板与柱的设计","example":"Structural engineering placed the reinforcement where tension appears.","exampleCN":"结构工程把钢筋放在出现拉力的位置。","why":"Concrete is strong in compression but weak in tension, so the branch adds steel where it is pulled.","whyCN":"混凝土抗压好而抗拉弱，该分支便在受拉处加钢筋。"},{"no":"05","title":"Seismic design","titleCN":"抗震设计","definition":"the detailing of structures so that they bend without collapsing during an earthquake","definitionCN":"细部设计使结构在地震中变形而不倒塌","example":"Structural engineering let the frame sway rather than break.","exampleCN":"结构工程让框架摇摆而不是断裂。","why":"A structure can survive a quake by yielding in planned places, and that planning is the branch's job.","whyCN":"结构可在地震中通过有计划的部位屈服而存活，这种规划正是该分支的工作。"},{"no":"06","title":"Strengthening existing structures","titleCN":"既有结构加固","definition":"the assessment and retrofit of old buildings that must carry new loads","definitionCN":"评估并改造需要承担新荷载的旧建筑","example":"Structural engineering strengthened the floor before the new machines arrived.","exampleCN":"结构工程在新机器运来之前加固了楼板。","why":"Old frames often outlive their original use, so the branch also works backwards on what already stands.","whyCN":"旧框架常比原用途活得更久，因此该分支也反过来处理已建成的东西。"},{"no":"07","title":"Bridge structures","titleCN":"桥梁结构","definition":"the design of bridge decks, girders, arches and cables","definitionCN":"桥面、主梁、拱与索的设计","example":"Structural engineering tuned the cable forces of the new footbridge.","exampleCN":"结构工程调校了新人行桥的索力。","why":"A bridge is a frame whose whole purpose is to span, so it is a favourite object of the branch.","whyCN":"桥梁是专为跨越而设的框架，因此是该分支最常处理的对象。"},{"no":"08","title":"The degree and the consultant","titleCN":"学位与顾问职业","definition":"the university training and the professional practice that certify structural engineers","definitionCN":"培养并认证结构工程师的大学训练与专业实务","example":"He took structural engineering after his first degree in civil works.","exampleCN":"他在取得土木工程本科学位后攻读结构工程。","why":"The branch has its own advanced training and its own consultants, so the phrase also names a career.","whyCN":"该分支有自己的进阶训练与顾问，因此这个词组也指一种职业。"}],"etymology":{"intro":{"en":"Structural engineering joins a Latin noun for building with the profession word from ingenium; it names the branch that asks whether a frame can stand.","cn":"「结构工程」把拉丁语中表示「建造」的名词，与源自「巧思」的专业词组合；它命名的是追问框架能否站住的分支。"},"items":[{"era":"LATIN STRUERE","en":"Struere meant to build, to pile up or to arrange in layers; it is the direct Latin source, while its own earlier root is a reconstruction often, but not certainly, linked to a spreading root.","cn":"这个拉丁语动词指建造、堆叠或分层排列；它是本词的直接拉丁语来源，其更早词根属重构性质，常被联结到表示「铺展」的词根，但并无确证。"},{"era":"LATIN STRUCTURA","en":"Structura named the act and result of building, and English took it as structure for both the frame and its arrangement.","cn":"这个拉丁语名词指建造的行为与结果，英语以「结构」接收它，既指框架也指其安排方式。"},{"era":"ENGLISH STRUCTURAL","en":"The adjective structural appeared in the nineteenth century for what belongs to a frame or to the arrangement of parts.","cn":"「结构的」这一形容词在十九世纪出现，指属于框架或部件安排方式的。"},{"era":"LATIN INGENIUM","en":"Ingenium meant natural ability; French engin, a clever device, produced English engineer.","cn":"这个拉丁语名词指天赋；法语中指精巧装置的一词产生了英语「工程师」。"},{"era":"NINETEENTH CENTURY SPLIT · FIRST RECORD DATE UNCERTAIN","en":"As iron, steel and reinforced concrete made frames calculable, structural work separated from general civil engineering as its own branch; the exact year of first record is uncertain.","cn":"随着铁、钢与钢筋混凝土使框架可计算，结构工作从普通土木工程中分离出来，成为独立分支；具体首见年代不确定。"},{"era":"MODERN PRACTICE","en":"The phrase now covers load analysis, member design, seismic detailing and the assessment of existing buildings and bridges.","cn":"这个词组如今涵盖荷载分析、构件设计、抗震细部与既有建筑及桥梁的评估。"}]},"similar":{"note":{"en":"The first group shares the build root; the second group names nearby design fields and ideas.","cn":"第一组共享「建造」词根；第二组是相邻的设计领域与概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"noun","definition":"The frame or arrangement itself; the phrase names the branch that designs it.","definitionCN":"框架或安排本身；词组指设计它的分支。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"adjective","definition":"Of a frame or of parts arranged together; it is the first half of the target.","definitionCN":"框架的、部件安排的；是目标词组的前半。"},{"word":"construct","ipa":"/kənˈstrʌkt/","tag":"verb","definition":"To build by putting parts together; it shares the root but names the act.","definitionCN":"把部件组合起来建造；共享词根，但指动作。"},{"word":"instruct","ipa":"/ɪnˈstrʌkt/","tag":"verb","definition":"To build knowledge into someone; the same root with a different prefix.","definitionCN":"把知识建进某人心中；同词根不同前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"civil engineering","ipa":"/ˈsɪvəl ˌendʒɪˈnɪərɪŋ/","tag":"noun","definition":"The wider field that includes structures among roads, water and ground works.","definitionCN":"更宽的领域，结构只是道路、水利与岩土工作之一。"},{"word":"load-bearing","ipa":"/ˈləʊd ˌbeərɪŋ/","tag":"adjective","definition":"Describing a part that carries weight; an idea inside the branch, not the branch itself.","definitionCN":"描述承担重量的部件；是分支内的概念，而非分支。"},{"word":"mechanics of materials","ipa":"/mɪˈkænɪks əv məˈtɪəriəlz/","tag":"noun","definition":"The physical study of stress and strain; it supplies the branch's theory.","definitionCN":"研究应力与应变的物理学；为该分支提供理论。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Structure comes from a Latin verb meaning to build in layers.","cn":"「结构」来自一个表示分层建造的拉丁语动词。"},{"en":"The family runs structure, structural, construct, construction, instruct.","cn":"同族词包括结构、结构的、建造、施工、指导。"},{"en":"Fixed phrases mark it: structural engineering analysis, structural engineering software.","cn":"固定搭配可标记它：结构工程分析、结构工程软件。"},{"en":"Its daily question is simple: can this frame carry that load?","cn":"它的日常问题很简单：这个框架能承担那份荷载吗？"},{"en":"Its answers are written in steel, concrete, timber and cable.","cn":"它的答案写在钢、混凝土、木材与索上。"}],"abstract":[{"en":"Picture a chain of hands where every hand must hold the weight passed to it.","cn":"想象一串手，每只手都必须接住传过来的重量。"},{"en":"Picture a tree that bends in a storm rather than snapping at the trunk.","cn":"想象一棵树在风暴中弯曲，而不是在树干处折断。"},{"en":"Picture a bridge that tells the river below exactly where its weight goes.","cn":"想象一座桥清楚地告诉下方的河，它的重量去了哪里。"}]},"examples":[{"en":"Structural engineering explains why the balcony needed a second beam.","cn":"结构工程解释了这座阳台为何需要第二根梁。"},{"en":"The structural engineering report listed every overloaded joint.","cn":"结构工程报告列出了每个超载节点。"},{"en":"She teaches structural engineering to third-year civil students.","cn":"她给三年级土木学生教授结构工程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「结构」+「工程」——把每一份重量沿框架送到地面","word":"structural engineering"},"root":"前半源自拉丁语「分层建造」的结果名词，后半源自拉丁语「巧思」经法语的「工程师」；建造一词更早的来源存疑。","sensesIntro":{"en":"Eight senses follow one question: where does the weight go? The phrase covers load paths, loads, steel, concrete, earthquakes, repair, bridges and the profession.","cn":"八个义项围绕一个问题：重量去哪里？这个词组覆盖传力路径、荷载、钢材、混凝土、地震、加固、桥梁与职业。"},"semanticMap":{"core":{"en":"CORE IMAGE: a frame bending slightly under a load and passing it along members until the ground takes it.","cn":"核心意象：框架在荷载下微微弯曲，把力沿构件逐段传递，直到地面接住它。"},"chain":["LOAD PATH","MEMBER","MATERIAL","CONNECTION","RESISTANCE","SAFETY MARGIN"],"branches":[{"senses":"01 · 02","en":"THE METHOD: finding the load path and calculating the loads that travel along it.","cn":"方法：找出传力路径并计算沿路径传递的荷载。"},{"senses":"03","en":"THE STEEL VERSION: light frames for long spans.","cn":"钢材版本：用于大跨度的轻质框架。"},{"senses":"04","en":"THE CONCRETE VERSION: mass in compression with steel where tension appears.","cn":"混凝土版本：受压的实体，在受拉处配钢筋。"},{"senses":"05 · 06","en":"THE RESISTANCE VERSION: planned yielding in earthquakes and strengthening of old frames.","cn":"抗力版本：地震中有计划的屈服，以及旧框架的加固。"},{"senses":"07 · 08","en":"THE SPANNING AND PROFESSIONAL VERSION: bridges and the certified consultant.","cn":"跨越与职业版本：桥梁与持证顾问。"}]},"affixes":{"intro":{"en":"Both halves are Latin-rooted: one from a verb of layered building, one from the word for cleverness behind engineer.","cn":"两半都是拉丁语词根：一半来自分层建造的动词，一半来自「工程师」背后的「巧思」。"},"latinIntro":{"en":"Latin struere and structura supply the frame half; ingenium supplies the profession half.","cn":"拉丁语的「建造」与「结构」提供框架一半，「巧思」提供专业一半。"},"items":[{"word":"struere","structure":"Latin verb","meaning":"to build, pile up, arrange","meaningCN":"建造、堆叠、排列","example":"The verb behind structure.","exampleCN":"「结构」背后的动词。"},{"word":"structura","structure":"Latin noun","meaning":"a building; an arrangement","meaningCN":"建筑物；安排","example":"It became English structure.","exampleCN":"它成为英语的「结构」。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It makes structural from structure.","exampleCN":"它把「结构」变成「结构的」。"},{"word":"con-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It forms construct, to build together.","exampleCN":"它构成「一起建造」。"},{"word":"in-","structure":"Latin prefix","meaning":"in, into","meaningCN":"在内","example":"It forms instruct, to build in.","exampleCN":"它构成「在内建造」。"},{"word":"ingenium","structure":"Latin noun","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思","example":"The root of engineer.","exampleCN":"「工程师」的词根。"},{"word":"gignere","structure":"Latin verb","meaning":"to beget, produce","meaningCN":"生育、产生","example":"It ends ingenium.","exampleCN":"它构成「巧思」的后半。"},{"word":"engin","structure":"Old French noun","meaning":"clever device","meaningCN":"精巧装置","example":"It carried the root to English.","exampleCN":"它把词根带到英语。"},{"word":"engineer","structure":"English noun","meaning":"designer of works","meaningCN":"工程设计者","example":"The profession noun.","exampleCN":"专业人员名词。"},{"word":"-ing","structure":"English noun ending","meaning":"the activity of","meaningCN":"……的活动","example":"It names the profession.","exampleCN":"它命名专业活动。"}],"latinEntries":[{"word":"struere","structure":"struere, struxi, structum (v., third conjugation)","meaning":"to build, pile up, arrange","meaningCN":"建造、堆叠、排列"},{"word":"structura","structure":"structura, structurae (n., first declension)","meaning":"a building; an arrangement","meaningCN":"建筑物；安排"},{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"natural ability, cleverness","meaningCN":"天赋、巧思"}],"derivatives":[{"word":"structure","pos":"n.","zh":"由「建造」加结果名词词尾构成，义为「结构」"},{"word":"structural","pos":"adj.","zh":"由「结构」加形容词词尾构成，义为「结构的」"},{"word":"construct","pos":"v.","zh":"由「一起」加「建造」构成，义为「建造」"},{"word":"construction","pos":"n.","zh":"由「建造」加结果名词词尾构成，义为「施工」"},{"word":"instruct","pos":"v.","zh":"由「在内」加「建造」构成，义为「指导」"},{"word":"engineer","pos":"n.","zh":"由拉丁语「巧思」经法语进入英语，义为「工程师」"}]}},{"word":"construction material","ipa_uk":"/kənˈstrʌkʃən məˈtɪəriəl/","ipa_us":"/kənˈstrʌkʃən məˈtɪriəl/","definition_zh":"用于建造建筑物与工程的物质材料，如混凝土、钢材、木材、砖与保温防水材料","definition_en":"any substance used to build structures, such as concrete, steel, timber, brick, insulation or waterproofing","core_image":"仓库里堆着成捆钢筋、成摞砖块与一袋袋水泥，每一批都挂着标明强度与产地的标签","scene":"材料仓库里，质检员用回弹仪敲击刚到的混凝土试块，记录强度读数。The inspector rejected the construction material because it cracked.","sceneCN":"这里指用于建造的实体材料（第 1 个义项：用于建造建筑物与工程的物质材料）；句意：质检员拒收了这批建材，因为它出现了裂缝。","pos":[{"tag":"n.","zh":"建筑材料；建造材料"}],"collocations":[{"phrase":"construction material cost","zh":"建材成本"},{"phrase":"construction material supplier","zh":"建材供应商"},{"phrase":"construction material testing","zh":"建材检测"},{"phrase":"construction material waste","zh":"建材废料"},{"phrase":"recycled construction material","zh":"再生建材"}],"forms":[{"label":"单数形式","form":"construction material"},{"label":"复数形式","form":"construction materials"},{"label":"形容词形式","form":"constructional"},{"label":"名词形式","form":"construction"},{"label":"动词形式","form":"construct"},{"label":"相关名词","form":"material"}],"derivatives":[{"word":"construct","pos":"v.","zh":"由拉丁语「一起建造」构成，义为「建造」"},{"word":"construction","pos":"n.","zh":"由「建造」加结果名词词尾构成，义为「建造、施工」"},{"word":"constructional","pos":"adj.","zh":"由「施工」加形容词词尾构成，义为「施工的、构造的」"},{"word":"material","pos":"n.","zh":"由拉丁语「物质」进入英语，义为「材料」"},{"word":"materialize","pos":"v.","zh":"由「材料」加使动词尾构成，义为「实现、具体化」"},{"word":"immaterial","pos":"adj.","zh":"由否定前缀加「材料的」构成，义为「非物质的、不重要的」"}],"senses":[{"no":"01","title":"Substances used to build","titleCN":"用于建造的物质","definition":"the physical substances chosen to form part of a building or civil work","definitionCN":"被选来构成建筑物或土木工程一部分的实体物质","example":"The construction material arrived on site in three separate loads.","exampleCN":"这批建材分三车运到工地。","why":"Construction names the building activity and material names the substance, so the phrase is the stuff the activity consumes.","whyCN":"「施工」指建造活动，「材料」指物质，因此这个词组就是该活动所消耗的东西。"},{"no":"02","title":"Specification and properties","titleCN":"规格与性能","definition":"the declared strength, density, durability and fire rating that a material must meet","definitionCN":"材料必须达到的强度、密度、耐久性与防火等级等规定指标","example":"The construction material must meet the strength class named in the drawings.","exampleCN":"建材必须达到图纸注明的强度等级。","why":"A material is bought against numbers, so the phrase often means the specification rather than the stuff.","whyCN":"材料是照着数字采购的，因此这个词组常指规格而不是实物。"},{"no":"03","title":"Concrete and aggregate","titleCN":"混凝土与骨料","definition":"cement, sand, gravel and the mixed concrete made from them","definitionCN":"水泥、砂、砾石以及由它们拌成的混凝土","example":"The construction material for the raft was poured in one continuous shift.","exampleCN":"筏板用的建材在一个连续班次内浇筑完成。","why":"Concrete is the most used building substance, so it stands for the whole class in daily speech.","whyCN":"混凝土是最常用的建筑材料，在日常说法中便代表整个类别。"},{"no":"04","title":"Steel and metals","titleCN":"钢材与金属","definition":"reinforcing bar, structural sections, cladding and metal fixings","definitionCN":"钢筋、结构型材、围护板与金属连接件","example":"The construction material for the frame was cut and welded off site.","exampleCN":"框架用的钢材在场外切割并焊接。","why":"Metal carries tension and can be joined, so it is the material of frames and fixings.","whyCN":"金属能受拉且可连接，因此是框架与连接件的材料。"},{"no":"05","title":"Timber and masonry","titleCN":"木材与砌体","definition":"sawn timber, bricks, blocks and mortar used for walls and roofs","definitionCN":"用于墙体与屋面的锯材、砖、砌块与砂浆","example":"The construction material for the inner walls was chosen for its weight.","exampleCN":"内墙建材是按重量来选的。","why":"Older building traditions rest on wood and fired clay, and those materials remain in the class.","whyCN":"更古老的建造传统依赖木材与烧制的黏土，这些材料仍属于这一类。"},{"no":"06","title":"Insulation and waterproofing","titleCN":"保温与防水材料","definition":"boards, foams, membranes and coatings that control heat, air and water","definitionCN":"控制热量、空气与水的板材、泡沫、卷材与涂料","example":"The construction material for the roof had to resist standing water.","exampleCN":"屋面建材必须耐积水。","why":"A building must also keep heat in and water out, so the phrase includes the protective layers.","whyCN":"建筑还必须保温挡水，因此这个词组包含各层防护材料。"},{"no":"07","title":"Testing and approval","titleCN":"检测与验收","definition":"the sampling and testing that decides whether a delivered material may be used","definitionCN":"决定进场材料能否使用的取样与试验","example":"Every construction material is sampled before it is lifted to the floor.","exampleCN":"每种建材在吊上楼之前都要取样。","why":"Bad material ruins a whole structure, so the phrase also names the testing regime around it.","whyCN":"劣质材料会毁掉整座结构，因此这个词组也指围绕它的检测制度。"},{"no":"08","title":"Procurement and delivery","titleCN":"采购与进场","definition":"the ordering, transport, storage and handling of materials on a project","definitionCN":"项目上材料的订购、运输、堆放与搬运","example":"Late construction material delayed the roof by two weeks.","exampleCN":"建材到货晚了，屋面工程拖了两周。","why":"Materials must be bought and moved before they can be built in, so the phrase also covers the supply chain.","whyCN":"材料必须先买来、运到，才能被砌进建筑，因此这个词组也覆盖供应链。"}],"etymology":{"intro":{"en":"Construction material joins a Latin noun for building with a Latin word for stuff, materia; the phrase names what a site consumes rather than what it designs.","cn":"「建筑材料」把拉丁语中表示「建造」的名词，与拉丁语表示「物质」的词组合；它命名的是工地消耗的东西，而不是设计的东西。"},"items":[{"era":"LATIN STRUERE","en":"Struere meant to build or pile up; it is the direct Latin source, while its deeper origin is a reconstruction often linked to a spreading root without proof.","cn":"这个拉丁语动词指建造或堆叠；它是前半的直接拉丁语来源，其更早词根属重构性质，常被联结到表示「铺展」的词根，但无确证。"},{"era":"LATIN CONSTRUERE","en":"The prefix con-, meaning together, produced construere, to build by putting parts together, and English construct came from it.","cn":"表示「一起」的前缀构成了「把部件组合起来建造」的动词，英语的「建造」由此而来。"},{"era":"LATIN CONSTRUCTIO","en":"Constructio named the act and result of building, and English construction kept both the activity and the finished work.","cn":"这个拉丁语名词指建造的行为与结果，英语的「施工」保留了活动与成品两方面。"},{"era":"LATIN MATERIA","en":"Materia meant timber, stuff or matter, and it is the direct Latin source of the second half; its own origin is uncertain, and a link to the word for mother is only a suggestion.","cn":"这个拉丁语名词指木料、材料或物质，是后半的直接拉丁语来源；它自身的来源存疑，与表示「母亲」之词的关联仅为推测。"},{"era":"ENGLISH MATERIAL","en":"English material kept the sense of the substance something is made from, and later added the sense of importance.","cn":"英语的「材料」保留了「某物由之制成的物质」之意，后来又增添了「重要性」之意。"},{"era":"MODERN SITE PHRASE · FIRST RECORD DATE UNCERTAIN","en":"As building became an industry with standards and supply chains, the two words were fixed together for everything a project buys and tests; the exact year of first record is uncertain.","cn":"随着建筑成为有标准与供应链的产业，这两个词被固定组合，指项目所采购与检测的一切物料；具体首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the build root; the second group names other stuff words and near classes.","cn":"第一组共享「建造」词根；第二组是其他物质词与相邻类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"construction","ipa":"/kənˈstrʌkʃən/","tag":"noun","definition":"The activity or the finished building; not the stuff itself.","definitionCN":"建造活动或建成的建筑；不是材料本身。"},{"word":"construct","ipa":"/kənˈstrʌkt/","tag":"verb","definition":"To build by putting parts together.","definitionCN":"把部件组合起来建造。"},{"word":"material","ipa":"/məˈtɪəriəl/","tag":"noun","definition":"Any stuff something is made from; the second half of the target.","definitionCN":"任何制成某物的物质；目标词后半。"},{"word":"matter","ipa":"/ˈmætə/","tag":"noun","definition":"Physical substance in general; it is broader and less specific than a building material.","definitionCN":"一般意义上的物质；比建材更宽泛。"}]},{"heading":"NEAR MEANING","entries":[{"word":"building material","ipa":"/ˈbɪldɪŋ məˈtɪəriəl/","tag":"noun","definition":"A close synonym, more common for domestic and commercial building.","definitionCN":"近义词，多用于住宅与商业建筑。"},{"word":"raw material","ipa":"/rɔː məˈtɪəriəl/","tag":"noun","definition":"Material before processing; a brick is already processed and is not raw.","definitionCN":"加工前的材料；砖已经加工过，不属于原料。"},{"word":"component","ipa":"/kəmˈpəʊnənt/","tag":"noun","definition":"A finished part of an assembly; it stresses function rather than substance.","definitionCN":"组件的成品零件；强调功能而非物质。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Construction means building together; material means the stuff used.","cn":"「施工」指一起建造，「材料」指所用的物质。"},{"en":"The family runs construct, construction, constructional, material, materialize.","cn":"同族词包括建造、施工、构造的、材料、实现。"},{"en":"Fixed phrases mark it: construction material supplier, construction material testing.","cn":"固定搭配可标记它：建材供应商、建材检测。"},{"en":"Concrete, steel, timber, brick, insulation and membrane are the six familiar classes.","cn":"混凝土、钢、木材、砖、保温层与防水卷材是六个熟悉的类别。"},{"en":"A site tests every load before it lifts anything to the floor.","cn":"工地把每批材料检测之后才吊上楼。"}],"abstract":[{"en":"Picture a cook who refuses to taste the flour before baking the bread.","cn":"想象一位厨师在烤面包前拒绝尝一尝面粉。"},{"en":"Picture a coat that must keep heat in and rain out at the same time.","cn":"想象一件既要保温又要挡雨的外套。"},{"en":"Picture a warehouse where every sack carries a number that decides its fate.","cn":"想象一间仓库，每袋材料都带着一个决定其命运的数字。"}]},"examples":[{"en":"The construction material for the sea wall had to resist salt water.","cn":"海堤所用建材必须耐盐水。"},{"en":"Cheap construction material is the most expensive mistake on a site.","cn":"便宜的建材是工地上最贵的错误。"},{"en":"They stored the construction material under cover before the rainy season.","cn":"他们在雨季前把建材存放在遮蔽处。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「建造」+「物质」——砌进墙里的每一袋、每一块","word":"construction material"},"root":"前半源自拉丁语「一起建造」，后半源自拉丁语「物质」；两词更早的来源均存疑。","sensesIntro":{"en":"Eight senses follow one supply chain: a substance is specified, delivered, tested and built in. The phrase covers the stuff, its specification, concrete, steel, timber, insulation, testing and procurement.","cn":"八个义项沿一条供应链展开：材料被规定、送达、检测，最后砌进建筑。这个词组覆盖材料本身、规格、混凝土、钢材、木材、保温、检测与采购。"},"semanticMap":{"core":{"en":"CORE IMAGE: piles of stuff on a site, each lot tagged with a number that says what it can carry.","cn":"核心意象：工地上堆着各种材料，每一批都挂着标明它能承受什么的数字。"},"chain":["RAW STUFF","SPECIFIED","MIXED OR SHAPED","TESTED","DELIVERED","BUILT IN"],"branches":[{"senses":"01 · 02","en":"THE SUBSTANCE AND ITS NUMBERS: the stuff itself and the strength it must reach.","cn":"物质及其数字：材料本身与它必须达到的强度。"},{"senses":"03","en":"THE CONCRETE VERSION: cement, aggregate and poured concrete.","cn":"混凝土版本：水泥、骨料与浇筑的混凝土。"},{"senses":"04","en":"THE METAL VERSION: bar, sections and fixings.","cn":"金属版本：钢筋、型材与连接件。"},{"senses":"05 · 06","en":"THE OLDER AND PROTECTIVE VERSION: timber, brick, insulation and waterproofing.","cn":"古老与防护版本：木材、砖、保温与防水。"},{"senses":"07 · 08","en":"THE SITE VERSION: testing, ordering, delivery and storage.","cn":"工地版本：检测、订购、运输与堆放。"}]},"affixes":{"intro":{"en":"One half comes from a Latin verb of building together, the other from the Latin word for stuff.","cn":"一半来自拉丁语「一起建造」的动词，另一半来自拉丁语表示「物质」的词。"},"latinIntro":{"en":"Latin construere and constructio supply the first half; materia supplies the second.","cn":"拉丁语的「一起建造」与「建造结果」提供前半，「物质」提供后半。"},"items":[{"word":"struere","structure":"Latin verb","meaning":"to build, pile up","meaningCN":"建造、堆叠","example":"The base verb of the build family.","exampleCN":"建造词族的基动词。"},{"word":"con-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It makes construere, build together.","exampleCN":"它构成「一起建造」。"},{"word":"construere","structure":"Latin verb","meaning":"to build by joining parts","meaningCN":"把部件连接建造","example":"English construct came from it.","exampleCN":"英语的「建造」由此而来。"},{"word":"constructio","structure":"Latin noun","meaning":"a building; the act of building","meaningCN":"建筑物；建造行为","example":"It became English construction.","exampleCN":"它成为英语的「施工」。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It forms constructional.","exampleCN":"它构成「构造的」。"},{"word":"materia","structure":"Latin noun","meaning":"timber, stuff, matter","meaningCN":"木料、材料、物质","example":"The root of material.","exampleCN":"「材料」的词根。"},{"word":"-al","structure":"adjective and noun ending","meaning":"belonging to; thing of","meaningCN":"属于……的；……之物","example":"It forms material from materia.","exampleCN":"它把「物质」变成「材料」。"},{"word":"material","structure":"English noun","meaning":"stuff something is made from","meaningCN":"制成某物的物质","example":"The second half of the target.","exampleCN":"目标词的后半。"},{"word":"construct","structure":"English verb","meaning":"to build","meaningCN":"建造","example":"The verb behind the first half.","exampleCN":"前半背后的动词。"},{"word":"-tion","structure":"noun ending","meaning":"the act or result of","meaningCN":"……的行为或结果","example":"It forms construction.","exampleCN":"它构成「施工」。"}],"latinEntries":[{"word":"struere","structure":"struere, struxi, structum (v., third conjugation)","meaning":"to build, pile up","meaningCN":"建造、堆叠"},{"word":"construere","structure":"construere, construxi, constructum (v., third conjugation)","meaning":"to build together","meaningCN":"一起建造"},{"word":"materia","structure":"materia, materiae (n., first declension)","meaning":"timber, stuff, matter","meaningCN":"木料、材料、物质"}],"derivatives":[{"word":"construct","pos":"v.","zh":"由「一起」加「建造」构成，义为「建造」"},{"word":"construction","pos":"n.","zh":"由「建造」加结果名词词尾构成，义为「施工」"},{"word":"constructional","pos":"adj.","zh":"由「施工」加形容词词尾构成，义为「构造的」"},{"word":"material","pos":"n.","zh":"由拉丁语「物质」加形容词与名词词尾构成，义为「材料」"},{"word":"materialize","pos":"v.","zh":"由「材料」加使动词尾构成，义为「实现」"},{"word":"immaterial","pos":"adj.","zh":"由否定前缀加「材料的」构成，义为「非物质的」"}]}},{"word":"component design","ipa_uk":"/kəmˈpəʊnənt dɪˈzaɪn/","ipa_us":"/kəmˈpoʊnənt dɪˈzaɪn/","definition_zh":"对整机或系统中的单个零件、元件进行形状、尺寸、材料与公差设计的工作","definition_en":"the work of specifying the shape, size, material and tolerances of a single part or element within a machine or system","core_image":"屏幕上放大一个轴承座，孔径、壁厚与配合公差层层标注，零件在整台机器中的位置被虚线框出","scene":"设计室里，工程师在屏幕上放大一个轴承座，标注孔径与公差。Good component design keeps repair costs low.","sceneCN":"这里指对单个零件做尺寸、材料与公差设计的工作（第 1 个义项：对整机或系统中的单个零件、元件进行形状、尺寸、材料与公差设计的工作）；句意：良好的零部件设计能压低维修成本。","pos":[{"tag":"n.","zh":"零部件设计；元件设计"}],"collocations":[{"phrase":"component design engineer","zh":"零部件设计工程师"},{"phrase":"component design review","zh":"零部件设计评审"},{"phrase":"component design software","zh":"零部件设计软件"},{"phrase":"component design change","zh":"零部件设计变更"},{"phrase":"modular component design","zh":"模块化零部件设计"}],"forms":[{"label":"单数形式","form":"component design"},{"label":"复数形式","form":"component designs"},{"label":"动词形式","form":"design"},{"label":"名词形式","form":"designer"},{"label":"形容词形式","form":"component"},{"label":"相关名词","form":"componentry"}],"derivatives":[{"word":"component","pos":"n.","zh":"由拉丁语「一起放置」的动词加表示成分的名词词尾构成，义为「部件、成分」"},{"word":"componential","pos":"adj.","zh":"由「成分」加形容词词尾构成，义为「成分的」"},{"word":"design","pos":"n./v.","zh":"由拉丁语「标出」进入英语，义为「设计」"},{"word":"designer","pos":"n.","zh":"由「设计」加表示人的词尾构成，义为「设计师」"},{"word":"designate","pos":"v.","zh":"由拉丁语「标出」构成，义为「指定、标明」"},{"word":"designation","pos":"n.","zh":"由「指定」加名词词尾构成，义为「指定、称号」"}],"senses":[{"no":"01","title":"Designing one part of a whole","titleCN":"为整体中的一个零件做设计","definition":"the work of defining a single part that will be assembled with others","definitionCN":"定义一个将与其他零件装配在一起的单个零件的工作","example":"Good component design begins with the loads the part must carry.","exampleCN":"良好的零部件设计从零件必须承担的荷载开始。","why":"Component names one element of a larger whole and design names the planning, so the phrase is planning a part in its context.","whyCN":"「部件」指更大整体中的一个元素，「设计」指规划，因此这个词组是在整体背景中规划一个零件。"},{"no":"02","title":"Shape and sizing","titleCN":"形状与尺寸","definition":"the choice of geometry, wall thickness and section that gives the part its strength","definitionCN":"选择使零件获得强度的几何形状、壁厚与截面","example":"Component design reduced the bracket's weight without weakening it.","exampleCN":"零部件设计减轻了支架重量而没有削弱它。","why":"A part carries load through its shape, so geometry is the first decision of the work.","whyCN":"零件靠形状承载，因此几何是这项工作的第一个决定。"},{"no":"03","title":"Material and process choice","titleCN":"材料与工艺选择","definition":"the selection of metal, plastic or composite and of casting, machining or moulding","definitionCN":"选择金属、塑料或复合材料，以及铸造、机加工或模压等工艺","example":"Component design chose cast aluminium because the shape was complex.","exampleCN":"零部件设计因形状复杂而选择了铸铝。","why":"Shape and material must be decided together, because some shapes can only be made by some processes.","whyCN":"形状与材料必须一起决定，因为某些形状只能由某些工艺做出。"},{"no":"04","title":"Tolerance and fit","titleCN":"公差与配合","definition":"the allowed variation in size and the clearance or interference between mating parts","definitionCN":"允许的尺寸偏差以及配合件之间的间隙或过盈","example":"Component design set a tight tolerance on the shaft bore.","exampleCN":"零部件设计给轴孔定了很紧的公差。","why":"Parts made separately must still meet, so the work states how much variation is acceptable.","whyCN":"分开制造的零件仍要能配合，因此这项工作要规定允许多大偏差。"},{"no":"05","title":"Electronic component design","titleCN":"电子元件设计","definition":"the design of a resistor, capacitor, chip or connector as a unit inside a circuit","definitionCN":"设计电路中的电阻、电容、芯片或连接器等单元","example":"Component design for the board had to fit a smaller case.","exampleCN":"这块电路板的元件设计必须装进更小的外壳。","why":"The word component also names circuit elements, so the phrase extends from machine parts to electronics.","whyCN":"「部件」一词也指电路元件，因此这个词组从机械零件扩展到电子。"},{"no":"06","title":"Design for manufacture","titleCN":"面向制造的设计","definition":"the adjustment of a part so that it can be made, assembled and inspected economically","definitionCN":"调整零件使其能被经济地制造、装配与检验","example":"Component design removed the deep pocket that slowed machining.","exampleCN":"零部件设计去掉了那个拖慢加工的深腔。","why":"A part that cannot be made cheaply is a failed design, so the work must respect the factory.","whyCN":"不能便宜制造的零件就是失败的设计，因此这项工作必须顾及工厂条件。"},{"no":"07","title":"Modularity and interfaces","titleCN":"模块化与接口","definition":"the definition of how a part connects to its neighbours, including dimensions, plugs and mounting points","definitionCN":"规定零件如何与相邻件连接，包括尺寸、插接件与安装点","example":"Component design fixed the mounting points before the frame was drawn.","exampleCN":"零部件设计在画框架之前就定下了安装点。","why":"Every part has neighbours, so the work also defines the interfaces it must honour.","whyCN":"每个零件都有邻居，因此这项工作还要定义它必须遵守的接口。"},{"no":"08","title":"Verification and revision","titleCN":"验证与改型","definition":"the testing, stress checking and redesign that follows a first part drawing","definitionCN":"首版零件图之后的试验、应力校核与重新设计","example":"Component design went through three revisions after the vibration test.","exampleCN":"振动试验之后，零部件设计经历了三次改版。","why":"A drawing is a proposal until it is tested, so the work ends in verification and revision.","whyCN":"图纸在被验证之前只是提案，因此这项工作以验证与改型收尾。"}],"etymology":{"intro":{"en":"Component design joins a Latin word for something placed together with a Latin word for marking out; the phrase is about planning one element of a larger machine.","cn":"「零部件设计」把拉丁语中表示「一起放置之物」的词，与拉丁语表示「标出」的词组合；这个词组讲的是规划一台大机器中的一个元素。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant to place or put; its perfect participle positum supplied many English words about placing and position.","cn":"这个拉丁语动词指放置、安置；它的完成分词为许多表示「放置」与「位置」的英语词提供了成分。"},{"era":"LATIN COMPONERE","en":"The prefix com-, meaning together, produced componere, to put together, and componens named the thing that is put in with others.","cn":"表示「一起」的前缀构成了「放在一起」的动词，其分词名词指被放进整体中的东西。"},{"era":"LATIN COMPONENTEM","en":"English took component from the participle, naming one element of a larger assembly rather than the whole.","cn":"英语从该分词取得「部件」一词，命名大装配体中的一个元素，而不是整体。"},{"era":"LATIN SIGNUM","en":"Signum meant a mark or sign, and designare meant to mark out or plan something by signs.","cn":"这个拉丁语名词指标记或符号，相应的动词表示用符号标出或规划。"},{"era":"ENGLISH DESIGN","en":"Design entered English through French and Italian uses meaning a plan or a drawing, then narrowed to the act of planning a product.","cn":"「设计」经法语与意大利语的用法进入英语，原指计划或图样，后来缩小为规划产品的行为。"},{"era":"MODERN ENGINEERING PAIRING","en":"Mass production made it necessary to plan each part against its neighbours, and the two words became a fixed phrase for that work.","cn":"批量生产使人们必须对照相邻件来规划每个零件，这两个词便固定成指这项工作的词组。"}]},"similar":{"note":{"en":"The first group shares the placing root; the second group names related planning words.","cn":"第一组共享「放置」词根；第二组是相关的规划用语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"component","ipa":"/kəmˈpəʊnənt/","tag":"noun","definition":"One element of a larger whole; the object of the design work.","definitionCN":"更大整体中的一个元素；设计工作的对象。"},{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"verb","definition":"To put together or to calm oneself; it shares the placing root.","definitionCN":"放在一起或使镇定；共享「放置」词根。"},{"word":"design","ipa":"/dɪˈzaɪn/","tag":"noun/verb","definition":"A plan or the act of planning; the second half of the target.","definitionCN":"计划或规划行为；目标词后半。"},{"word":"designate","ipa":"/ˈdesɪɡneɪt/","tag":"verb","definition":"To mark out or name officially; it shares the mark root.","definitionCN":"标出或正式指定；共享「标记」词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"part design","ipa":"/pɑːt dɪˈzaɪn/","tag":"noun","definition":"A common synonym in manufacturing; it stresses a piece rather than an element of a system.","definitionCN":"制造业常用近义词；强调一块零件而非系统元素。"},{"word":"detail design","ipa":"/dɪˈteɪl dɪˈzaɪn/","tag":"noun","definition":"The stage after concept design when every part is fixed; broader than one component.","definitionCN":"概念设计之后固定每个零件的阶段；比单个部件宽。"},{"word":"product design","ipa":"/ˈprɒdʌkt dɪˈzaɪn/","tag":"noun","definition":"The design of the whole sellable item, including form and user experience.","definitionCN":"整个可售物品的设计，包括外形与使用体验。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Component means something put in with others; design means marking out a plan.","cn":"「部件」指被放进整体中的东西，「设计」指标出计划。"},{"en":"The family runs component, compose, design, designate, designer.","cn":"同族词包括部件、组成、设计、指定、设计师。"},{"en":"Fixed phrases mark it: component design review, component design change.","cn":"固定搭配可标记它：零部件设计评审、零部件设计变更。"},{"en":"Its four decisions are shape, material, tolerance and interface.","cn":"它的四个决定是形状、材料、公差与接口。"},{"en":"Its proof is a drawing that survives testing and revision.","cn":"它的证明是一张经得起试验与改版的图纸。"}],"abstract":[{"en":"Picture one brick that must fit a wall it has never seen.","cn":"想象一块必须嵌进它从未见过的墙的砖。"},{"en":"Picture a key cut to a lock that another hand will make.","cn":"想象一把按别人将来制造的锁来切削的钥匙。"},{"en":"Picture a dancer who must know exactly where the next dancer stands.","cn":"想象一位舞者必须清楚下一位舞者站在哪里。"}]},"examples":[{"en":"Component design fixes the shaft size before the bearing is ordered.","cn":"零部件设计在订购轴承之前定下轴径。"},{"en":"The review found that component design ignored the assembly sequence.","cn":"评审发现零部件设计忽略了装配顺序。"},{"en":"Good component design makes a spare part cheap to replace.","cn":"良好的零部件设计让备件更换更便宜。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「部件」+「设计」——为整台机器中的一个零件画准尺寸","word":"component design"},"root":"「部件」经拉丁语进入英语，「设计」经法语与意大利语进入英语；放置与标记两个词根构成了这个词组。","sensesIntro":{"en":"Eight senses follow one part through its life: shaped, sized, made, fitted, connected, tested and revised. The phrase covers a single element, its geometry, its material, its tolerance, electronics, manufacture, interfaces and verification.","cn":"八个义项跟随一个零件走完它的生命：成形、定尺寸、选材、配合、连接、验证与改版。这个词组覆盖单个元素、其几何、材料、公差、电子应用、制造、接口与验证。"},"semanticMap":{"core":{"en":"CORE IMAGE: one small part drawn large on a screen while a dashed outline shows where it sits in the whole machine.","cn":"核心意象：一个小零件在屏幕上被放大，虚线框标出它在整台机器中的位置。"},"chain":["FUNCTION","SHAPE","MATERIAL","TOLERANCE","ASSEMBLY","REVISION"],"branches":[{"senses":"01 · 02","en":"THE OBJECT AND ITS GEOMETRY: a single element and the shape that gives it strength.","cn":"对象及其几何：单个元素与赋予它强度的形状。"},{"senses":"03","en":"THE MATERIAL VERSION: metal, plastic or composite and the process that forms it.","cn":"材料版本：金属、塑料或复合材料及其成形工艺。"},{"senses":"04","en":"THE FIT VERSION: allowed variation and clearance between mating parts.","cn":"配合版本：配合件之间允许的偏差与间隙。"},{"senses":"05 · 06","en":"THE ELECTRONIC AND FACTORY VERSION: circuit elements and design for manufacture.","cn":"电子与工厂版本：电路元件与面向制造的设计。"},{"senses":"07 · 08","en":"THE INTERFACE AND PROOF VERSION: mounting points, testing and revision.","cn":"接口与验证版本：安装点、试验与改版。"}]},"affixes":{"intro":{"en":"One half is the Latin participle for something placed together; the other is the Latin verb for marking out a plan.","cn":"一半是拉丁语中表示「被放在一起之物」的分词，另一半是拉丁语表示「标出计划」的动词。"},"latinIntro":{"en":"Latin componere supplies component; designare supplies design.","cn":"拉丁语的「放在一起」提供「部件」，「标出」提供「设计」。"},"items":[{"word":"ponere","structure":"Latin verb","meaning":"to place, put","meaningCN":"放置、安放","example":"The base of the placing family.","exampleCN":"放置词族的基动词。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"It makes componere, put together.","exampleCN":"它构成「放在一起」。"},{"word":"componere","structure":"Latin verb","meaning":"to put together","meaningCN":"放在一起、组成","example":"The verb behind component.","exampleCN":"「部件」背后的动词。"},{"word":"componentem","structure":"Latin participle","meaning":"the thing put in with others","meaningCN":"被放入整体中的东西","example":"English took it as component.","exampleCN":"英语以「部件」接收它。"},{"word":"-ent","structure":"adjective and noun ending","meaning":"being or doing","meaningCN":"处于……的；……者","example":"It shapes the participle ending.","exampleCN":"它构成该分词的词尾。"},{"word":"signum","structure":"Latin noun","meaning":"a mark, a sign","meaningCN":"标记、符号","example":"The root of design.","exampleCN":"「设计」的词根。"},{"word":"de-","structure":"Latin prefix","meaning":"down, fully","meaningCN":"向下、完全","example":"It begins designare.","exampleCN":"它构成「标出」的前半。"},{"word":"designare","structure":"Latin verb","meaning":"to mark out, to plan","meaningCN":"标出、规划","example":"It became English design.","exampleCN":"它成为英语的「设计」。"},{"word":"design","structure":"English noun and verb","meaning":"a plan; to plan","meaningCN":"计划；规划","example":"The second half of the target.","exampleCN":"目标词的后半。"},{"word":"-er","structure":"agent ending","meaning":"one who does","meaningCN":"做……的人","example":"It forms designer.","exampleCN":"它构成「设计师」。"}],"latinEntries":[{"word":"componere","structure":"componere, composui, compositum (v., third conjugation)","meaning":"to put together","meaningCN":"放在一起、组成"},{"word":"signum","structure":"signum, signi (n., second declension)","meaning":"a mark, a sign","meaningCN":"标记、符号"},{"word":"designare","structure":"designare, designavi, designatum (v., first conjugation)","meaning":"to mark out, to plan","meaningCN":"标出、规划"}],"derivatives":[{"word":"component","pos":"n.","zh":"由「一起放置」的分词构成，义为「部件」"},{"word":"compose","pos":"v.","zh":"由「一起放置」构成，义为「组成」"},{"word":"design","pos":"n./v.","zh":"由「标出」经法语进入英语，义为「设计」"},{"word":"designer","pos":"n.","zh":"由「设计」加人称词尾构成，义为「设计师」"},{"word":"designate","pos":"v.","zh":"由「标出」构成，义为「指定」"},{"word":"designation","pos":"n.","zh":"由「指定」加名词词尾构成，义为「称号」"}]}},{"word":"equipment","ipa_uk":"/ɪˈkwɪpmənt/","ipa_us":"/ɪˈkwɪpmənt/","definition_zh":"为某项工作、活动或场所配置的成套设备与器材（不可数名词）","definition_en":"the set of machines, tools and other items needed for a particular activity or place, used as an uncountable noun","core_image":"车间一角，工具箱、检测台与备用电机按工序排开，每件都贴着写有用途的标签","scene":"实验室库房里，新到的工具箱、检测台与备用电机按工序排好，标签写着各自的用途。The lab ordered new equipment for the clean room.","sceneCN":"这里指为某一场所配置的成套设备（第 1 个义项：为某项工作、活动或场所配置的成套设备与器材）；句意：实验室为洁净室订购了新设备。","pos":[{"tag":"n.","zh":"设备；装备；器材"}],"collocations":[{"phrase":"laboratory equipment","zh":"实验室设备"},{"phrase":"medical equipment","zh":"医疗设备"},{"phrase":"heavy equipment","zh":"重型设备"},{"phrase":"equipment failure","zh":"设备故障"},{"phrase":"equipment maintenance","zh":"设备维护"},{"phrase":"sports equipment","zh":"运动器材"}],"forms":[{"label":"不可数名词","form":"equipment"},{"label":"动词形式","form":"equip"},{"label":"过去式","form":"equipped"},{"label":"过去分词","form":"equipped"},{"label":"现在分词","form":"equipping"},{"label":"相关名词","form":"equipage"}],"derivatives":[{"word":"equip","pos":"v.","zh":"由法语「为船配备人员与物资」进入英语，义为「装备、配备」"},{"word":"equipped","pos":"adj.","zh":"由「装备」加已然词尾构成，义为「配备齐全的」"},{"word":"equipping","pos":"n.","zh":"由「装备」加动名词词尾构成，义为「装备工作」"},{"word":"equipage","pos":"n.","zh":"由「装备」加集合名词词尾构成，义为「成套装备、车马随从」"}],"senses":[{"no":"01","title":"A set of things for a purpose","titleCN":"为一项目的配置的一整套东西","definition":"the machines, tools and supplies that a task or place needs in order to work","definitionCN":"某项任务或场所为了运作所需要的机器、工具与用品","example":"The whole equipment for the field station fits in two lorries.","exampleCN":"野外站的全部设备两辆卡车就能装下。","why":"Equip means to fit out for a purpose, so the noun names the fitted-out set rather than any single thing.","whyCN":"「装备」指为某目的配齐，因此这个名词指配齐的那一整套，而不是任何单件。"},{"no":"02","title":"Industrial machinery","titleCN":"工业机械设备","definition":"the heavy powered machines of a factory, mine or construction site","definitionCN":"工厂、矿山或建筑工地上的重型动力机械","example":"The contractor moved the heavy equipment before the rain.","exampleCN":"承包商在下雨前转移了重型设备。","why":"On large sites the set is dominated by powered machines, so the general noun settles on that part.","whyCN":"在大工地上，这一套里主要是动力机械，于是泛称便落在这一部分上。"},{"no":"03","title":"Gear for outdoor activity","titleCN":"户外活动器材","definition":"the personal items needed for camping, climbing, diving or a sport","definitionCN":"露营、攀登、潜水或某项运动所需的个人用品","example":"Their camping equipment weighed more than the food.","exampleCN":"他们的露营装备比食物还重。","why":"A personal activity also requires a fitted-out set, and the noun follows the kit into the backpack.","whyCN":"个人活动同样需要配齐一套东西，这个名词便跟着装备进了背包。"},{"no":"04","title":"Laboratory and clinical kit","titleCN":"实验室与诊所器械","definition":"the instruments, benches, analysers and supplies of a lab or clinic","definitionCN":"实验室或诊所的仪器、台面、分析仪与耗材","example":"The clinic replaced its old equipment with quieter analysers.","exampleCN":"诊所把旧设备换成了更安静的分析仪。","why":"Work done at a bench needs a stable set of tools, so this is the most common academic use of the word.","whyCN":"在台面上做的工作需要稳定的一套工具，这是该词最常见的学术用法。"},{"no":"05","title":"The act of fitting out","titleCN":"配齐装备的过程","definition":"the process of supplying someone or something with what is needed","definitionCN":"为某人或某物提供所需之物的过程","example":"The equipment of the vessel took a week.","exampleCN":"给这艘船配齐装备用了一周。","why":"The noun can name the action as well as the result, because the ending marks both the doing and the thing done.","whyCN":"这个名词既能指动作也能指结果，因为词尾同时标记「做」与「所做之物」。"},{"no":"06","title":"Assets under management","titleCN":"作为资产管理的设备","definition":"the machines treated as recorded, maintained and depreciated property","definitionCN":"被视为需要登记、维护与折旧的财产之机器","example":"Every piece of equipment has an owner and a service date.","exampleCN":"每件设备都有责任人与保养日期。","why":"Once kit belongs to an organisation, it must be tracked, and the noun becomes an accounting category.","whyCN":"器材一旦属于组织，就必须被追踪，这个名词便成为会计类别。"},{"no":"07","title":"Personal capability, by metaphor","titleCN":"个人能力（比喻）","definition":"a person's mental or physical resources for a task, imagined as a kit","definitionCN":"把某人完成任务的心智或体力资源想象成一套装备","example":"Patience is part of a teacher's equipment.","exampleCN":"耐心是教师装备的一部分。","why":"People speak of mental kit as equipment because abilities, like tools, are what one brings to a job.","whyCN":"人们把心智装备说成设备，因为能力与工具一样，是带到工作中的东西。"},{"no":"08","title":"Military and expedition kit","titleCN":"军用与远征装备","definition":"the weapons, vehicles, radios and stores issued to a unit or expedition","definitionCN":"发给部队或远征队的武器、车辆、电台与补给","example":"The expedition checked its equipment twice before leaving base.","exampleCN":"远征队在离开基地前检查了两遍装备。","why":"Large organised ventures issue a standard set, so the word also names official kit.","whyCN":"有组织的大型行动会发放标准一套，因此这个词也指正式配发的装备。"}],"etymology":{"intro":{"en":"Equipment comes from a French verb for fitting out a ship, which was probably taken from an Old Norse verb for arranging a crew; the ending was added in English.","cn":"「设备」来自一个法语动词，意为给船配齐人员与物资，该词很可能取自一个表示安排船员的老诺斯语动词；表示结果的名词词尾是英语后加的。"},"items":[{"era":"OLD NORSE SKIPA","en":"Skipa meant to arrange, to put in order or to man a ship; the direct English source is Old French esquiper, which took this Norse verb, and the deeper origin of both remains a reconstruction.","cn":"这个老诺斯语动词指安排、整理或为船配人；英语的直接来源是古法语中表示「为船配齐」的动词，它借入了这个诺斯语词，两者的更早来源都属重构性质。"},{"era":"OLD FRENCH ESQUIPER","en":"French esquiper meant to fit out a ship with crew and stores, and it carried the Norse verb into English usage.","cn":"法语动词指为船配齐船员与物资，它把这个诺斯语动词带进了英语用法。"},{"era":"ENGLISH EQUIP","en":"English equip kept the sense of supplying what a person or place needs, and dropped the naval setting.","cn":"英语的「装备」保留了「为某人或某地提供所需之物」之意，并去掉了海上背景。"},{"era":"EIGHTEENTH CENTURY NOUN · FIRST RECORD DATE UNCERTAIN","en":"The noun equipment was formed with a result ending to name the set of things supplied, not the act of supply alone; the exact year of first record is uncertain.","cn":"这个名词在十八世纪以表示结果的词尾构成，用来指被配齐的那一套东西，而不只是配备的动作；具体首见年代不确定。"},{"era":"INDUSTRIAL EXTENSION","en":"As factories grew, the set of powered machines became the dominant sense, giving phrases such as heavy equipment.","cn":"随着工厂发展，成套动力机械成为主要含义，于是有了「重型设备」这类说法。"},{"era":"MODERN RANGE","en":"The word now covers lab kit, sports gear, military stores and even a person's mental resources, all through the idea of being fitted out.","cn":"这个词如今涵盖实验室器材、运动装备、军用物资，甚至个人的心智资源，全部经由「配齐」这一观念联系起来。"}]},"similar":{"note":{"en":"The first group shares the fitting-out root; the second group separates the four near synonyms of kit.","cn":"第一组共享「配齐」词根；第二组区分四个近义的「器械」词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equip","ipa":"/ɪˈkwɪp/","tag":"verb","definition":"To supply with what is needed; the action behind the noun.","definitionCN":"提供所需之物；名词背后的动作。"},{"word":"equipped","ipa":"/ɪˈkwɪpt/","tag":"adjective","definition":"Fitted out with what is needed; it describes a state.","definitionCN":"已配齐所需之物的；描述状态。"},{"word":"equipping","ipa":"/ɪˈkwɪpɪŋ/","tag":"noun","definition":"The work of fitting out; it stresses the process.","definitionCN":"配齐装备的工作；强调过程。"},{"word":"equipage","ipa":"/ˈekwɪpɪdʒ/","tag":"noun","definition":"A complete set of gear, once especially for a carriage or ship; it is older and narrower.","definitionCN":"完整的一套装备，旧时尤指车马或船用；更古旧也更窄。"}]},{"heading":"NEAR MEANING","entries":[{"word":"instrument","ipa":"/ˈɪnstrəmənt/","tag":"noun","definition":"A precision measuring or musical tool; equipment is the whole set and need not measure.","definitionCN":"精密测量或乐器工具；设备指整套，且不必用于测量。"},{"word":"instrumentation","ipa":"/ˌɪnstrəmenˈteɪʃən/","tag":"noun","definition":"The system of measuring and control instruments in a plant; equipment is broader and may be mechanical.","definitionCN":"工厂中测量与控制仪表的系统；设备更宽，也可以是机械的。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"noun","definition":"A lab setup built for one experiment; equipment is bought as a set, apparatus is arranged for a task.","definitionCN":"为某一实验搭起的一套装置；设备按套购买，装置按任务布置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The root picture is a ship being fitted out with crew and stores.","cn":"词根画面是一条船被配齐船员与物资。"},{"en":"The family runs equip, equipped, equipping, equipment, equipage.","cn":"同族词包括装备、配备的、配备工作、设备、成套装备。"},{"en":"Fixed phrases mark it: laboratory equipment, heavy equipment, equipment failure.","cn":"固定搭配可标记它：实验室设备、重型设备、设备故障。"},{"en":"It is uncountable, so one says a piece of equipment, not an equipment.","cn":"它不可数，所以说一件设备，而不是一个设备。"},{"en":"Its four near words are instrument, instrumentation, apparatus and gear.","cn":"它的四个近义词是仪器、仪表系统、装置与器材。"}],"abstract":[{"en":"Picture a traveller whose bag holds exactly the tools the journey needs.","cn":"想象一位旅人，包里正好装着旅程所需的工具。"},{"en":"Picture a kitchen where every pot has one job and no pot is missing.","cn":"想象一间厨房，每口锅只干一件事，且一口不缺。"},{"en":"Picture a mind carrying patience and method the way a toolbox carries hammers.","cn":"想象一个头脑像工具箱装锤子那样装着耐心与方法。"}]},"examples":[{"en":"The crew unloaded the equipment before the wind rose.","cn":"船员在起风前卸下了设备。"},{"en":"Climbing equipment must be checked by a second person.","cn":"攀登装备必须由第二个人检查。"},{"en":"The hospital treats equipment maintenance as part of patient safety.","cn":"医院把设备维护视为病人安全的一部分。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「给船配齐」→ 给任何活配齐一整套家伙","word":"equipment"},"root":"源自法语「为船配齐人员物资」，该法语词很可能来自老诺斯语「安排、配人」；更早来源不确定，英语加结果词尾构成名词。","sensesIntro":{"en":"Eight senses follow one idea: a task is fitted out with a set. The set may be industrial machines, camping gear, lab analysers, a unit's stores, or a person's patience.","cn":"八个义项围绕一个观念：为一项任务配齐一套东西。这一套可以是工业机械、露营装备、实验室分析仪、部队物资，或一个人的耐心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a labelled set of tools laid out for one job, nothing extra and nothing missing.","cn":"核心意象：为一项工作摆开的一整套贴标签的工具，不多一件也不少一件。"},"chain":["SET OF TOOLS","FOR A TASK","POWERED MACHINES","LAB AND CLINIC","OUTDOOR GEAR","MANAGED ASSETS"],"branches":[{"senses":"01 · 05","en":"THE CORE AND ITS ACTION: the fitted-out set, and the act of fitting it out.","cn":"核心与动作：配齐的一套，以及配齐的动作。"},{"senses":"02 · 08","en":"THE LARGE-SCALE VERSION: factory machines and official expedition stores.","cn":"大规模版本：工厂机械与正式远征物资。"},{"senses":"03","en":"THE PERSONAL VERSION: gear carried for camping, climbing or a sport.","cn":"个人版本：为露营、攀登或运动携带的器材。"},{"senses":"04","en":"THE BENCH VERSION: lab and clinic analysers and supplies.","cn":"台面版本：实验室与诊所的分析仪与耗材。"},{"senses":"06 · 07","en":"THE OWNED AND METAPHORICAL VERSION: tracked assets, and a person's mental kit.","cn":"资产与比喻版本：被登记管理的资产，以及个人的心智装备。"}]},"affixes":{"intro":{"en":"The word is French and Norse in origin, not Latin: a ship fitted out, then any task fitted out, then the set itself.","cn":"这个词源自法语与诺斯语，而非拉丁语：先是为船配齐，再是为任何任务配齐，最后指配齐的那一套本身。"},"latinIntro":{"en":"No Latin root stands behind equipment, so the Latin entry list is empty.","cn":"这个词背后没有拉丁词根，因此拉丁词条列表留空。"},"items":[{"word":"skipa","structure":"Old Norse verb","meaning":"to arrange, to man a ship","meaningCN":"安排、为船配人","example":"The Norse verb supplied the core meaning.","exampleCN":"诺斯语动词提供了核心含义。"},{"word":"skip","structure":"Old Norse noun","meaning":"ship","meaningCN":"船","example":"The noun stands behind the verb, though the deeper origin is uncertain.","exampleCN":"名词支撑该动词，但更早来源不确定。"},{"word":"esquiper","structure":"Old French verb","meaning":"to fit out a ship","meaningCN":"为船配齐","example":"French carried the word to English.","exampleCN":"法语把词带到英语。"},{"word":"equip","structure":"English verb","meaning":"to supply what is needed","meaningCN":"提供所需之物","example":"The verb generalized beyond ships.","exampleCN":"动词从船只推广到一般。"},{"word":"-ment","structure":"English noun ending","meaning":"result or means of an action","meaningCN":"动作的结果或手段","example":"It turns the verb into the set supplied.","exampleCN":"它把动词变成被配齐的那一套。"},{"word":"equipment","structure":"English noun","meaning":"the set of things supplied","meaningCN":"配齐的一套东西","example":"The noun is uncountable in standard use.","exampleCN":"这个名词在标准用法中不可数。"},{"word":"equipped","structure":"English adjective","meaning":"fitted out","meaningCN":"已配齐的","example":"The completed-state ending marks the result.","exampleCN":"已然词尾标记结果状态。"},{"word":"equipping","structure":"English noun","meaning":"the work of fitting out","meaningCN":"配齐装备的工作","example":"The action ending marks the process.","exampleCN":"动作词尾标记过程。"}],"latinEntries":[],"derivatives":[{"word":"equip","pos":"v.","zh":"由法语「为船配齐」进入英语，义为「装备」"},{"word":"equipped","pos":"adj.","zh":"由「装备」加已然词尾构成，义为「配备齐全的」"},{"word":"equipping","pos":"n.","zh":"由「装备」加动名词词尾构成，义为「配备工作」"},{"word":"equipage","pos":"n.","zh":"由「装备」加集合名词词尾构成，义为「成套装备」"}]}},{"word":"instrument","ipa_uk":"/ˈɪnstrəmənt/","ipa_us":"/ˈɪnstrəmənt/","definition_zh":"用于测量、记录或操作的精密器具；也指乐器、法律文书或被人利用的手段","definition_en":"a precision tool for measuring, recording or operating, or a musical, legal or figurative means","core_image":"三脚架上架着一台带刻度盘与微调螺旋的测量器具，气泡居中时，读数才准","scene":"测绘现场，测量员把水准仪架在三脚架上，转动微调螺旋对准标尺。The surveyor calibrated the instrument before each reading.","sceneCN":"这里指用于测量的精密器具（第 1 个义项：用于测量、记录或操作的精密器具）；句意：测量员在每次读数前都校准了这台仪器。","pos":[{"tag":"n.","zh":"仪器；乐器；工具；文书"}],"collocations":[{"phrase":"measuring instrument","zh":"测量仪器"},{"phrase":"musical instrument","zh":"乐器"},{"phrase":"surgical instrument","zh":"手术器械"},{"phrase":"instrument panel","zh":"仪表盘"},{"phrase":"legal instrument","zh":"法律文书"},{"phrase":"precision instrument","zh":"精密仪器"}],"forms":[{"label":"单数形式","form":"instrument"},{"label":"复数形式","form":"instruments"},{"label":"形容词形式","form":"instrumental"},{"label":"名词形式","form":"instrumentation"},{"label":"动词形式","form":"instrument"},{"label":"副词形式","form":"instrumentally"}],"derivatives":[{"word":"instrumental","pos":"adj.","zh":"由「器具」加形容词词尾构成，义为「起作用的、仪器的」"},{"word":"instrumentation","pos":"n.","zh":"由「仪器」加集合与动作名词词尾构成，义为「仪表系统」"},{"word":"instrumentality","pos":"n.","zh":"由「起作用的」加抽象名词词尾构成，义为「工具性、手段作用」"},{"word":"instrumentalist","pos":"n.","zh":"由「乐器演奏的」加人称词尾构成，义为「器乐演奏者」"},{"word":"instruct","pos":"v.","zh":"与「器具」共享「建造、布置」词根，义为「指导」"}],"senses":[{"no":"01","title":"A measuring device","titleCN":"测量器具","definition":"a device built to measure, record or display a physical quantity with precision","definitionCN":"为精密测量、记录或显示某一物理量而造的器具","example":"The thermometer is the oldest instrument in the clinic.","exampleCN":"温度计是诊所里最古老的仪器。","why":"Instrument names a made thing that serves a precise purpose, and measurement is its most typical purpose.","whyCN":"「仪器」指为某个精确目的而造的东西，而测量是它最典型的用途。"},{"no":"02","title":"A musical instrument","titleCN":"乐器","definition":"a device played to produce music, such as a violin, flute or piano","definitionCN":"为演奏音乐而使用的器具，如小提琴、长笛或钢琴","example":"She plays three instruments but teaches only one.","exampleCN":"她会演奏三种乐器，但只教一种。","why":"The word for a tool extends to the tools of music, because a violin is also a made thing used for a skilled purpose.","whyCN":"「工具」一词扩展到音乐工具，因为小提琴同样是为一项技艺目的而造的东西。"},{"no":"03","title":"A means to an end","titleCN":"达成目的的手段","definition":"something used to bring about a result, especially in policy or negotiation","definitionCN":"为带来某种结果而使用的东西，尤指政策或谈判中的手段","example":"Tariffs became an instrument of pressure rather than a source of income.","exampleCN":"关税成了施压手段，而不是收入来源。","why":"A tool need not be physical, so the word serves for any means that produces an effect.","whyCN":"工具不必是实体的，因此这个词可用于任何产生效果的手段。"},{"no":"04","title":"A formal legal document","titleCN":"正式法律文书","definition":"a written document that creates rights or records an official act","definitionCN":"设定权利或记录官方行为的书面文件","example":"The treaty was signed as a single instrument.","exampleCN":"这份条约作为一份单一文书签署。","why":"Law borrows tool words for documents because a deed is the device by which a right is made to work.","whyCN":"法律借用了工具类词来指文书，因为契约正是让权利生效的器具。"},{"no":"05","title":"A surgical tool","titleCN":"手术器械","definition":"a hand tool used by a surgeon to cut, hold or suture tissue","definitionCN":"外科医生用来切开、夹持或缝合组织的手持工具","example":"The nurse counted every instrument before the operation.","exampleCN":"护士在手术前清点了每一件器械。","why":"Surgery is precise handwork, so its tools take the general word for a precise tool.","whyCN":"手术是精细的手上功夫，其工具便沿用了「精密器具」的泛称。"},{"no":"06","title":"A cockpit gauge","titleCN":"驾驶舱仪表","definition":"a dial or display in an aircraft or vehicle that shows speed, height or pressure","definitionCN":"飞机或车辆上显示速度、高度或压力的表盘或显示屏","example":"The altimeter is the instrument the pilot watches most.","exampleCN":"高度表是飞行员最常看的仪表。","why":"A pilot flies by readings, so each gauge is called an instrument and the set is the instrument panel.","whyCN":"飞行员靠读数飞行，因此每个表都被称为仪表，整组则叫仪表盘。"},{"no":"07","title":"A person used as a tool","titleCN":"被当作工具利用的人","definition":"someone controlled by another to achieve that other's purpose","definitionCN":"被他人控制以实现其目的的人","example":"He was an instrument of the faction, not its leader.","exampleCN":"他是那个派系的工具，而不是领袖。","why":"The metaphor turns a person into a device, which is a harsh way of denying them independent will.","whyCN":"这个比喻把人变成器具，是一种否认其独立意志的严厉说法。"},{"no":"08","title":"A negotiable financial document","titleCN":"可转让金融票据","definition":"a cheque, bill or note that transfers payment or credit from one party to another","definitionCN":"把付款或信用从一方转给另一方的支票、汇票或本票","example":"The bank refused the instrument because the signature was unclear.","exampleCN":"银行因签名不清而拒收了这张票据。","why":"Finance uses the legal sense of instrument for paper that carries a right, here a right to payment.","whyCN":"金融沿用「文书」义，指承载权利的纸，这里指收款权。"}],"etymology":{"intro":{"en":"Instrument comes from a Latin noun for equipment, built on a verb meaning to set up or furnish; the sense narrowed from any fitted-out thing to a precise tool.","cn":"「仪器」来自拉丁语中表示「装备」的名词，其动词意为布置、配备；词义从任何配齐之物缩小为精密器具。"},"items":[{"era":"LATIN STRUERE","en":"Struere meant to build or arrange in layers; it is the direct Latin source, while its deeper origin is a reconstruction often linked to a spreading root without proof.","cn":"这个拉丁语动词指建造或分层排列；它是本词的直接拉丁语来源，其更早词根属重构性质，常被联结到表示「铺展」的词根，但无确证。"},{"era":"LATIN INSTRUERE","en":"The prefix in- plus struere produced instruere, to set up, equip or prepare, and also to teach by arranging knowledge.","cn":"前缀「在内」加「建造」构成了「布置、配备、准备」的动词，也引申为把知识安排进去的「教导」。"},{"era":"LATIN INSTRUMENTUM","en":"Instrumentum named the equipment or the means by which something is done, including written records that make an act valid.","cn":"这个拉丁语名词指装备或做事所凭借的手段，也包括使行为生效的书面记录。"},{"era":"ENGLISH INSTRUMENT · FIRST RECORD DATE UNCERTAIN","en":"English kept both the tool sense and the document sense, then extended the tool sense to music and to gauges; the exact year of the borrowing is uncertain.","cn":"英语同时保留了工具义与文书义，随后把工具义扩展到音乐与仪表；这一借词的具体首见年代不确定。"},{"era":"SCIENTIFIC NARROWING","en":"As exact measurement became central to science, the most common sense narrowed to a precision measuring device.","cn":"随着精确测量成为科学的核心，最常见的词义缩小为精密测量器具。"},{"era":"MODERN FIGURATIVE USE","en":"The word still works as a metaphor for a means or for a person controlled by another, because both are imagined as tools.","cn":"这个词至今仍用作手段或受控之人的比喻，因为两者都被想象成工具。"}]},"similar":{"note":{"en":"The first group shares the set-up root; the second group places the four kit words side by side.","cn":"第一组共享「布置」词根；第二组把四个器械词并排区分。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"instrumental","ipa":"/ˌɪnstrəˈmentəl/","tag":"adjective","definition":"Serving as a means, or belonging to instruments; it describes a role.","definitionCN":"作为手段的，或属于仪器的；描述作用。"},{"word":"instrumentation","ipa":"/ˌɪnstrəmenˈteɪʃən/","tag":"noun","definition":"A whole system of instruments, not one device.","definitionCN":"整套仪表系统，不是单件器具。"},{"word":"instruct","ipa":"/ɪnˈstrʌkt/","tag":"verb","definition":"To teach or order; the same root, with knowledge being built in.","definitionCN":"教导或命令；同词根，把知识建进去。"},{"word":"instrumentalist","ipa":"/ˌɪnstrəˈmentəlɪst/","tag":"noun","definition":"A player of instruments rather than a singer.","definitionCN":"器乐演奏者，而非歌手。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equipment","ipa":"/ɪˈkwɪpmənt/","tag":"noun","definition":"The whole set of machines and tools; the target is one precise member of such a set.","definitionCN":"整套机器与工具；目标词是其中一件精密器具。"},{"word":"instrumentation","ipa":"/ˌɪnstrəmenˈteɪʃən/","tag":"noun","definition":"The arranged system of instruments and controls in a plant or aircraft.","definitionCN":"工厂或飞机中布置好的仪表与控制系统。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"noun","definition":"A setup assembled for an experiment; the target is usually a single measuring tool.","definitionCN":"为实验组装的一套装置；目标词通常是单件测量工具。"},{"word":"device","ipa":"/dɪˈvaɪs/","tag":"noun","definition":"Any made thing with a function; it is broader and less precise than an instrument.","definitionCN":"任何有功能的制成品；比仪器更宽、更不精密。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The root means to set up or furnish, so an instrument is a fitted-out tool.","cn":"词根意为布置、配备，因此仪器就是配齐的工具。"},{"en":"The family runs instrument, instrumental, instrumentation, instrumentality.","cn":"同族词包括仪器、起作用的、仪表系统、工具性。"},{"en":"Fixed phrases mark it: measuring instrument, musical instrument, surgical instrument, legal instrument.","cn":"固定搭配可标记它：测量仪器、乐器、手术器械、法律文书。"},{"en":"The same word covers a violin, a treaty and an altimeter.","cn":"同一个词覆盖小提琴、条约与高度表。"},{"en":"What separates it from equipment is precision and a single purpose.","cn":"它与设备的区别在于精密与单一用途。"}],"abstract":[{"en":"Picture a hand that can feel a hair's width of difference.","cn":"想象一只手能感觉出一根头发丝的差别。"},{"en":"Picture a paper that quietly makes a right exist.","cn":"想象一张纸悄悄让一项权利成立。"},{"en":"Picture a person played by another as one plays a violin.","cn":"想象一个人被别人像拉小提琴一样操控。"}]},"examples":[{"en":"The instrument must be zeroed before every series of readings.","cn":"仪器在每组读数前都必须归零。"},{"en":"A legal instrument can create a duty without a handshake.","cn":"法律文书无需握手就能创设义务。"},{"en":"The violin is the instrument she practices before dawn.","cn":"小提琴是她天亮前练习的乐器。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"拉丁语「布置好的东西」→ 量得准的器具，也成了乐器与文书","word":"instrument"},"root":"源自拉丁语「布置、配备」的动词及其结果名词，词义从配齐之物缩小为精密器具，再扩展到乐器、文书与票据。","sensesIntro":{"en":"Eight senses follow one idea: a made thing serves a precise purpose. The purpose may be measurement, music, surgery, flight, law, payment, policy or control over a person.","cn":"八个义项围绕一个观念：人造之物服务于一个精确目的。这个目的可以是测量、音乐、手术、飞行、法律、付款、政策，或控制他人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand tool with a dial and a fine screw, held steady until the reading settles.","cn":"核心意象：一件带刻度盘与微调螺旋的手持器具，稳稳握住直到读数稳定。"},"chain":["PRECISE TOOL","MEASURE","PLAY MUSIC","LEGAL PAPER","SURGERY","POLICY MEANS"],"branches":[{"senses":"01 · 06","en":"THE MEASURING CORE: lab devices and cockpit gauges, both read by eye.","cn":"测量核心：实验室器具与驾驶舱仪表，都靠眼睛读数。"},{"senses":"02","en":"THE MUSICAL VERSION: a tool played for art rather than measurement.","cn":"音乐版本：为艺术而非测量演奏的工具。"},{"senses":"03 · 07","en":"THE MEANS VERSION: policy tools and people treated as tools.","cn":"手段版本：政策工具与被当作工具的人。"},{"senses":"04 · 08","en":"THE DOCUMENT VERSION: legal deeds and negotiable paper.","cn":"文书版本：法律契约与可转让票据。"},{"senses":"05","en":"THE SURGICAL VERSION: hand tools that cut and hold.","cn":"手术版本：切开与夹持的手持工具。"}]},"affixes":{"intro":{"en":"The word is built on the Latin verb for setting up or furnishing, with a result noun ending.","cn":"这个词建立在拉丁语表示「布置、配备」的动词上，并带一个结果名词词尾。"},"latinIntro":{"en":"Latin instruere and instrumentum supply the whole word; the English ending is only the shortened form of the Latin one.","cn":"拉丁语的「布置」与「装备」提供了整个词；英语词尾只是拉丁词尾的缩短形式。"},"items":[{"word":"struere","structure":"Latin verb","meaning":"to build, arrange","meaningCN":"建造、排列","example":"The base of the build family.","exampleCN":"建造词族的基动词。"},{"word":"in-","structure":"Latin prefix","meaning":"in, into","meaningCN":"在内、进入","example":"It makes instruere, set up in place.","exampleCN":"它构成「安放就位」。"},{"word":"instruere","structure":"Latin verb","meaning":"to set up, equip, teach","meaningCN":"布置、配备、教导","example":"The verb behind instrument.","exampleCN":"「仪器」背后的动词。"},{"word":"-mentum","structure":"Latin noun ending","meaning":"result or means","meaningCN":"结果或手段","example":"It makes instrumentum, the thing set up.","exampleCN":"它构成「被布置之物」。"},{"word":"instrumentum","structure":"Latin noun","meaning":"equipment; a means; a record","meaningCN":"装备；手段；记录","example":"English took it as instrument.","exampleCN":"英语以「仪器」接收它。"},{"word":"instrument","structure":"English noun","meaning":"a precise tool or means","meaningCN":"精密器具或手段","example":"The word covers tools, music, law and finance.","exampleCN":"这个词覆盖工具、音乐、法律与金融。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It forms instrumental.","exampleCN":"它构成「起作用的」。"},{"word":"-ation","structure":"noun ending","meaning":"system or process","meaningCN":"系统或过程","example":"It forms instrumentation.","exampleCN":"它构成「仪表系统」。"},{"word":"-ity","structure":"noun ending","meaning":"quality of","meaningCN":"……的性质","example":"It forms instrumentality.","exampleCN":"它构成「工具性」。"}],"latinEntries":[{"word":"struere","structure":"struere, struxi, structum (v., third conjugation)","meaning":"to build, arrange","meaningCN":"建造、排列"},{"word":"instruere","structure":"instruere, instruxi, instructum (v., third conjugation)","meaning":"to set up, equip","meaningCN":"布置、配备"},{"word":"instrumentum","structure":"instrumentum, instrumenti (n., second declension)","meaning":"equipment; a means","meaningCN":"装备；手段"}],"derivatives":[{"word":"instrumental","pos":"adj.","zh":"由「仪器」加形容词词尾构成，义为「起作用的」"},{"word":"instrumentation","pos":"n.","zh":"由「仪器」加系统名词词尾构成，义为「仪表系统」"},{"word":"instrumentality","pos":"n.","zh":"由「起作用的」加抽象名词词尾构成，义为「工具性」"},{"word":"instrumentalist","pos":"n.","zh":"由「器乐的」加人称词尾构成，义为「器乐演奏者」"},{"word":"instruct","pos":"v.","zh":"由「在内」加「建造」构成，义为「指导」"},{"word":"instruction","pos":"n.","zh":"由「指导」加名词词尾构成，义为「指示、说明」"}]}},{"word":"instrumentation","ipa_uk":"/ˌɪnstrəmenˈteɪʃən/","ipa_us":"/ˌɪnstrəmenˈteɪʃən/","definition_zh":"一套系统中用于测量、显示与控制的各种仪表之总称；也指仪表工程与音乐配器","definition_en":"the collection of instruments used to measure, display and control a system, or the field and art of arranging them","core_image":"控制室整面盘台上排满压力表、温度计与记录仪，指针同时轻微摆动，把整座工厂的状态缩成一片刻度","scene":"飞机驾驶舱里，一整面仪表板布满高度表、油量表与警告灯，指针同时轻微摆动。The cockpit instrumentation warned the crew about the drop in pressure.","sceneCN":"这里指飞机驾驶舱内成套的仪表系统（第 1 个义项：一套系统中用于测量、显示与控制的各种仪表之总称）；句意：驾驶舱仪表系统向机组发出了压力下降的警告。","pos":[{"tag":"n.","zh":"仪表系统；仪表工程；配器"}],"collocations":[{"phrase":"process instrumentation","zh":"过程仪表系统"},{"phrase":"industrial instrumentation","zh":"工业仪表"},{"phrase":"instrumentation engineer","zh":"仪表工程师"},{"phrase":"instrumentation and control","zh":"仪表与控制"},{"phrase":"medical instrumentation","zh":"医疗仪表"},{"phrase":"instrumentation calibration","zh":"仪表校准"}],"forms":[{"label":"不可数名词","form":"instrumentation"},{"label":"单数名词","form":"instrument"},{"label":"复数名词","form":"instruments"},{"label":"形容词形式","form":"instrumental"},{"label":"动词形式","form":"instrument"},{"label":"从业者","form":"instrumentation engineer"}],"derivatives":[{"word":"instrument","pos":"n.","zh":"由拉丁语「布置、配备」的结果名词进入英语，义为「仪器」"},{"word":"instrumental","pos":"adj.","zh":"由「仪器」加形容词词尾构成，义为「仪器的、起作用的」"},{"word":"instrumentality","pos":"n.","zh":"由「起作用的」加抽象名词词尾构成，义为「工具性」"},{"word":"instruct","pos":"v.","zh":"与「仪器」共享「布置」词根，义为「指导」"},{"word":"instruction","pos":"n.","zh":"由「指导」加名词词尾构成，义为「说明、指令」"}],"senses":[{"no":"01","title":"The instruments of a plant, as a set","titleCN":"工厂仪表的总体","definition":"the whole set of measuring, indicating and recording devices installed in a process or vehicle","definitionCN":"安装在一个工艺过程或运载工具中的整套测量、显示与记录装置","example":"The plant's instrumentation fills three control cabinets.","exampleCN":"这座工厂的仪表系统装满了三个控制柜。","why":"The ending adds a collective sense to instrument, so the word names the arranged set rather than one gauge.","whyCN":"词尾给「仪器」加上集合含义，因此这个词指布置好的一整套，而不是一块表。"},{"no":"02","title":"Instrumentation engineering","titleCN":"仪表工程","definition":"the branch of engineering that specifies, installs and maintains measuring and control devices","definitionCN":"负责规定、安装与维护测量及控制装置的工程分支","example":"She studied instrumentation before moving into plant safety.","exampleCN":"她在转向工厂安全之前学的是仪表工程。","why":"A body of devices needs its own discipline, so the collective noun also names the profession.","whyCN":"成体系的装置需要自己的学科，因此这个集合名词也指专业。"},{"no":"03","title":"Measurement and data acquisition","titleCN":"测量与数据采集","definition":"the chain from sensor to signal to recorded value","definitionCN":"从传感器到信号再到记录值的整条链路","example":"Good instrumentation turns a slow chemical change into a clean trend line.","exampleCN":"良好的仪表系统把缓慢的化学变化变成干净的趋势线。","why":"The purpose of the set is to make a process observable, and that purpose names the activity.","whyCN":"这一套的目的就是让过程可观测，而这个目的也成了活动之名。"},{"no":"04","title":"Instruments in a control loop","titleCN":"控制回路中的仪表配置","definition":"the sensor, controller and final element that together hold a variable at its set point","definitionCN":"把某一变量稳定在设定值上的传感器、控制器与执行器组合","example":"The loop's instrumentation was rebuilt around a faster sensor.","exampleCN":"这个回路的仪表配置围绕一个更快的传感器重建。","why":"Measurement exists to drive control, so the word also covers the devices inside one loop.","whyCN":"测量是为了驱动控制，因此这个词也指一个回路内的装置。"},{"no":"05","title":"Instruments of a scientific setup","titleCN":"科学装置中的仪器配置","definition":"the detectors, meters and recorders arranged for an experiment","definitionCN":"为一项实验布置的探测器、计量表与记录器","example":"The telescope's instrumentation includes four separate detectors.","exampleCN":"这台望远镜的仪器配置包括四个独立探测器。","why":"An experiment is only as good as its readings, so its measuring set takes the collective name.","whyCN":"实验的好坏取决于读数，因此其测量装置也使用这个集合名称。"},{"no":"06","title":"Orchestration in music","titleCN":"音乐配器","definition":"the art of writing and arranging music for the instruments of an orchestra","definitionCN":"为管弦乐队各乐器写作与安排音乐的艺术","example":"The composer's instrumentation is richer in the second movement.","exampleCN":"作曲家在第二乐章的配器更丰富。","why":"The musical sense of instrument returns in a collective form, naming how a whole score uses its players.","whyCN":"「乐器」的音乐义以集合形式回归，指整份总谱如何运用演奏者。"},{"no":"07","title":"Installation, calibration and upkeep","titleCN":"安装、校准与维护","definition":"the field work of mounting, wiring, testing and recalibrating instruments","definitionCN":"安装、接线、试验并重新校准仪器的现场工作","example":"Instrumentation work closed the line for a single afternoon.","exampleCN":"仪表工作让产线停了一个下午。","why":"Devices must be fitted and trusted, so the word also covers the work that keeps them true.","whyCN":"装置必须被安装并可信，因此这个词也涵盖使它们保持准确的工作。"},{"no":"08","title":"Field devices in automation","titleCN":"自动化现场仪表","definition":"the transmitters, valves and positioners distributed around an automated plant","definitionCN":"分布在自动化工厂各处的变送器、阀门与定位器","example":"The automation project added instrumentation to every tank.","exampleCN":"这个自动化项目给每个罐都加了现场仪表。","why":"Automation reaches the physical world through field devices, and those devices are called instrumentation.","whyCN":"自动化通过现场装置触及物理世界，而这些装置就叫仪表。"}],"etymology":{"intro":{"en":"Instrumentation is instrument plus a Latin-derived ending for a system or process; the word collects many single tools into one arrangement.","cn":"「仪表系统」是「仪器」加上一个源自拉丁语、表示系统或过程的名词词尾；这个词把许多单件器具收拢成一套布置。"},"items":[{"era":"LATIN INSTRUERE","en":"Instruere meant to set up or equip; instruere and instrumentum are the direct Latin sources, while the deeper origin of struere is a reconstruction.","cn":"这个拉丁语动词指布置、配备；这一动词与其结果名词是本词的直接拉丁语来源，而更早的词根属重构性质。"},{"era":"LATIN INSTRUMENTUM","en":"Instrumentum named a piece of equipment or a means, and English shortened it to instrument.","cn":"这个拉丁语名词指一件装备或一种手段，英语把它缩短为「仪器」。"},{"era":"LATIN -ATIO","en":"The ending -atio named an action or a system of actions, and English -ation took over that function.","cn":"拉丁语词尾表示动作或动作体系，英语的相应词尾接过了这一功能。"},{"era":"NINETEENTH CENTURY COLLECTIVE · FIRST RECORD DATE UNCERTAIN","en":"As factories and ships gained many gauges, the new collective noun named the whole arrangement rather than one dial; the exact year of first record is uncertain.","cn":"随着工厂与船舶装上许多表，这个新的集合名词指整套布置，而不是一块表盘；具体首见年代不确定。"},{"era":"INDUSTRIAL CONTROL GROWTH","en":"Process control made instrumentation a recognised engineering field with its own standards and technicians.","cn":"过程控制使仪表成为有自身标准与技术员的公认工程领域。"},{"era":"MUSICAL BORROWING","en":"Music uses the same collective word for the way a score distributes material among instruments.","cn":"音乐用同一个集合词表示总谱在各乐器间分配材料的方式。"}]},"similar":{"note":{"en":"The first group shares the instrument root; the second group separates collector words from single tools.","cn":"第一组共享「仪器」词根；第二组区分集合词与单件工具。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"instrument","ipa":"/ˈɪnstrəmənt/","tag":"noun","definition":"One precise device; the collective word names many of them arranged together.","definitionCN":"单件精密器具；集合词指许多件一起布置。"},{"word":"instrumental","ipa":"/ˌɪnstrəˈmentəl/","tag":"adjective","definition":"Serving as a means or belonging to instruments.","definitionCN":"作为手段的，或属于仪器的。"},{"word":"instrumentality","ipa":"/ˌɪnstrəmenˈtæləti/","tag":"noun","definition":"The quality of being a means to an end.","definitionCN":"作为达成目的之手段的性质。"},{"word":"instrumentalist","ipa":"/ˌɪnstrəˈmentəlɪst/","tag":"noun","definition":"A musician who plays an instrument.","definitionCN":"演奏乐器的音乐家。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equipment","ipa":"/ɪˈkwɪpmənt/","tag":"noun","definition":"Any fitted-out set; it may be mechanical and need not measure.","definitionCN":"任何配齐的一套；可以是机械的，也不必测量。"},{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"noun","definition":"A setup assembled for one experiment; it is arranged for a task, not installed for a plant.","definitionCN":"为一次实验组装的装置；按任务布置，而非为工厂安装。"},{"word":"control system","ipa":"/kənˈtrəʊl ˌsɪstəm/","tag":"noun","definition":"The whole regulating system, of which instrumentation is the sensing and indicating part.","definitionCN":"整个调节系统，仪表系统只是其中感知与显示的部分。"},{"word":"telemetry","ipa":"/təˈlemətri/","tag":"noun","definition":"The transmission of readings to a distant point; it is one function of instrumentation.","definitionCN":"把读数传到远方的技术；是仪表系统的一项功能。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Instrument plus a system ending equals the whole arranged set.","cn":"「仪器」加表示系统的词尾，等于整套布置。"},{"en":"The family runs instrument, instrumental, instrumentation, instrumentality.","cn":"同族词包括仪器、仪器的、仪表系统、工具性。"},{"en":"Fixed phrases mark it: process instrumentation, instrumentation and control.","cn":"固定搭配可标记它：过程仪表系统、仪表与控制。"},{"en":"A control room wall of dials is the clearest picture of the word.","cn":"控制室一整墙的表盘是这个词最清晰的画面。"},{"en":"It differs from equipment by measuring, and from instrument by being a set.","cn":"它与设备的差别在于测量，与仪器的差别在于成套。"}],"abstract":[{"en":"Picture a patient whose whole body is covered in small sensors, each reporting one number.","cn":"想象一位病人全身贴满小传感器，每个都报告一个数字。"},{"en":"Picture an orchestra where every player knows the same score but plays a different line.","cn":"想象一支乐队，每位乐手都懂同一份总谱，却各奏不同声部。"},{"en":"Picture a wall of eyes that never blink and never forget a reading.","cn":"想象一墙永不眨眼、也永不忘记读数的眼睛。"}]},"examples":[{"en":"The instrumentation logged the pressure every ten seconds.","cn":"仪表系统每十秒记录一次压力。"},{"en":"Poor instrumentation made the fault invisible for a week.","cn":"糟糕的仪表配置让故障一周都没被发现。"},{"en":"Her thesis compares the instrumentation of two aircraft.","cn":"她的论文比较了两架飞机的仪表系统。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「仪器」+「系统」——把一墙的表收成一套会说话的装置","word":"instrumentation"},"root":"由拉丁语「布置、配备」的结果名词加表示系统或过程的名词词尾构成；词根更早来源不确定。","sensesIntro":{"en":"Eight senses follow one function: make a system visible and controllable. The set may sit in a plant, a cockpit, a lab, an orchestra or an automation line.","cn":"八个义项围绕一个功能：让一个系统变得可见、可控。这一套可以位于工厂、驾驶舱、实验室、乐队或自动化产线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall of dials and recorders turning a large process into a row of readable numbers.","cn":"核心意象：一墙表盘与记录仪，把庞大的过程变成一排可读的数字。"},"chain":["SENSING","SIGNAL","READOUT","CONTROL LOOP","CALIBRATION","AUTOMATION"],"branches":[{"senses":"01","en":"THE COLLECTIVE CORE: the whole installed set of measuring and indicating devices.","cn":"集合核心：整套安装好的测量与显示装置。"},{"senses":"02 · 03","en":"THE FIELD AND ITS CHAIN: instrumentation engineering, and sensor-to-record measurement.","cn":"领域与其链路：仪表工程，以及从传感器到记录的测量。"},{"senses":"04 · 08","en":"THE CONTROL VERSION: loop devices and the field instruments of automation.","cn":"控制版本：回路装置与自动化的现场仪表。"},{"senses":"05","en":"THE LAB VERSION: detectors and recorders arranged for one experiment.","cn":"实验室版本：为一项实验布置的探测器与记录器。"},{"senses":"06 · 07","en":"THE MUSICAL AND MAINTENANCE VERSION: orchestration, and installation and calibration.","cn":"音乐与维护版本：配器，以及安装与校准。"}]},"affixes":{"intro":{"en":"Instrumentation is a Latin-rooted tool word plus a Latin-rooted system ending; it turns one gauge into an arranged whole.","cn":"「仪表系统」是拉丁语词根的「工具」加拉丁语词根的「系统」词尾；它把一块表变成一套布置。"},"latinIntro":{"en":"Latin instrumentum and the ending -atio supply the word; English shortened both.","cn":"拉丁语的「装备」与动作名词词尾提供了这个词；英语把两者都缩短了。"},"items":[{"word":"struere","structure":"Latin verb","meaning":"to build, arrange","meaningCN":"建造、排列","example":"The base of the instrument family.","exampleCN":"仪器词族的基动词。"},{"word":"in-","structure":"Latin prefix","meaning":"in, into","meaningCN":"在内、进入","example":"It forms instruere.","exampleCN":"它构成「布置」。"},{"word":"instruere","structure":"Latin verb","meaning":"to set up, equip","meaningCN":"布置、配备","example":"The verb behind instrument.","exampleCN":"「仪器」背后的动词。"},{"word":"instrumentum","structure":"Latin noun","meaning":"equipment; a means","meaningCN":"装备；手段","example":"English shortened it to instrument.","exampleCN":"英语把它缩短为「仪器」。"},{"word":"-ment","structure":"English noun ending","meaning":"result or means","meaningCN":"结果或手段","example":"It marks the single tool.","exampleCN":"它标记单件工具。"},{"word":"-ation","structure":"English noun ending","meaning":"system, process or result","meaningCN":"系统、过程或结果","example":"It makes the collective noun.","exampleCN":"它构成集合名词。"},{"word":"instrument","structure":"English noun","meaning":"one precise device","meaningCN":"单件精密装置","example":"The base of the target.","exampleCN":"目标词的基词。"},{"word":"instrumentation","structure":"English noun","meaning":"an arranged set of devices","meaningCN":"布置好的一套装置","example":"The target itself.","exampleCN":"目标词本身。"},{"word":"instrumental","structure":"English adjective","meaning":"serving as a means","meaningCN":"作为手段的","example":"The adjective keeps the tool sense.","exampleCN":"形容词保留工具含义。"}],"latinEntries":[{"word":"instruere","structure":"instruere, instruxi, instructum (v., third conjugation)","meaning":"to set up, equip","meaningCN":"布置、配备"},{"word":"instrumentum","structure":"instrumentum, instrumenti (n., second declension)","meaning":"equipment; a means","meaningCN":"装备；手段"},{"word":"-atio","structure":"-atio, -ationis (n., third declension)","meaning":"action or system of actions","meaningCN":"动作或动作体系"}],"derivatives":[{"word":"instrument","pos":"n.","zh":"由拉丁语「装备」缩短而来，义为「仪器」"},{"word":"instrumental","pos":"adj.","zh":"由「仪器」加形容词词尾构成，义为「仪器的」"},{"word":"instrumentality","pos":"n.","zh":"由「起作用的」加抽象名词词尾构成，义为「工具性」"},{"word":"instruct","pos":"v.","zh":"由「在内」加「建造」构成，义为「指导」"},{"word":"instruction","pos":"n.","zh":"由「指导」加名词词尾构成，义为「说明」"}]}},{"word":"apparatus","ipa_uk":"/ˌæpəˈreɪtəs/","ipa_us":"/ˌæpəˈrætəs/","definition_zh":"为特定用途配置的一整套器械或装置；也可指机构、组织等抽象体系","definition_en":"a set of equipment assembled for a particular purpose, or an organized system such as a state or party structure","core_image":"实验台上，玻璃管、支架、气瓶与阀门连成一套，每一段都扣在指定的位置，只为完成一次反应","scene":"潜水前，队员检查背上的气瓶、减压阀与面罩，确认每一处接头都不漏气。The diver checked the breathing apparatus before the descent.","sceneCN":"这里指成套的呼吸装置（第 2 个义项：为潜水或消防配置的呼吸器）；句意：潜水员在下潜前检查了呼吸装置。","pos":[{"tag":"n.","zh":"装置；器械；机构"}],"collocations":[{"phrase":"laboratory apparatus","zh":"实验装置"},{"phrase":"breathing apparatus","zh":"呼吸器"},{"phrase":"state apparatus","zh":"国家机构"},{"phrase":"gymnastic apparatus","zh":"体操器械"},{"phrase":"optical apparatus","zh":"光学装置"},{"phrase":"critical apparatus","zh":"校勘资料"}],"forms":[{"label":"单数形式","form":"apparatus"},{"label":"复数形式（拉丁）","form":"apparatus"},{"label":"复数形式（英语常用）","form":"apparatuses"},{"label":"形容词形式","form":"apparatal"},{"label":"相关名词","form":"apparatus design"},{"label":"相关动词","form":"prepare"}],"derivatives":[{"word":"apparatuses","pos":"n.","zh":"由「装置」加英语复数词尾构成，义为「多套装置」"},{"word":"prepare","pos":"v.","zh":"由拉丁语「预先准备」经法语进入英语，义为「准备」"},{"word":"preparation","pos":"n.","zh":"由「准备」加名词词尾构成，义为「准备、制备」"},{"word":"preparatory","pos":"adj.","zh":"由「准备」加形容词词尾构成，义为「预备的」"},{"word":"repair","pos":"v.","zh":"由拉丁语「重新准备」经法语进入英语，义为「修理」"}],"senses":[{"no":"01","title":"A set assembled for an experiment","titleCN":"为实验组装的一套器械","definition":"the connected pieces of equipment set up to carry out a particular experiment or operation","definitionCN":"为完成某项实验或操作而连接起来的一套器材","example":"The whole apparatus was rebuilt after the glass tube broke.","exampleCN":"玻璃管破裂后，整套装置被重新组装。","why":"Apparatus names a prepared set, not a single tool, because its root verb means to make ready.","whyCN":"「装置」指准备好的一套，而不是单件工具，因为其词根动词意为「准备」。"},{"no":"02","title":"Breathing gear","titleCN":"呼吸器","definition":"the cylinder, regulator and mask that let a person breathe under water, in smoke or at altitude","definitionCN":"让人在水下、烟雾中或高空呼吸的气瓶、调节器与面罩组合","example":"Firefighters carry breathing apparatus into every smoke-filled room.","exampleCN":"消防员进入每个烟雾弥漫的房间都携带呼吸器。","why":"A life-support set is prepared before entry, so the general word attaches to this specialised kit.","whyCN":"生命维持装备要在进入前准备好，因此这个泛称也附着于这套专用器材。"},{"no":"03","title":"The machinery of an organization","titleCN":"组织的机构体系","definition":"the offices, departments and procedures through which a state, party or large body acts","definitionCN":"国家、政党或大型团体赖以行动的机关、部门与程序","example":"The reform aimed at the party apparatus rather than at voters.","exampleCN":"这项改革针对的是政党机构，而不是选民。","why":"An organisation acts through prepared parts, so the tool word becomes a metaphor for institutional machinery.","whyCN":"组织通过准备好的各个部件行动，于是工具词变成了机构机械的比喻。"},{"no":"04","title":"Gymnastic equipment","titleCN":"体操器械","definition":"the fixed or portable frames and bars used in gymnastics, such as the rings or parallel bars","definitionCN":"体操中使用的固定或可移动框架与横杆，如吊环或双杠","example":"The hall's apparatus was inspected before the competition.","exampleCN":"比赛前，馆内的体操器械接受了检查。","why":"Sporting equipment is also a prepared set, so the word serves for bars, rings and beams.","whyCN":"运动器材同样是准备好的一套，因此这个词也用于横杆、吊环与平衡木。"},{"no":"05","title":"Optical or measuring setup","titleCN":"光学或测量装置","definition":"a bench of lenses, mirrors, lasers and detectors aligned for one measurement","definitionCN":"为一次测量而对准的透镜、反射镜、激光器与探测器组合","example":"The optical apparatus had to stay aligned within a micron.","exampleCN":"这套光学装置必须在微米范围内保持对准。","why":"Precision work needs many parts fixed in relation to one another, which is exactly what apparatus means.","whyCN":"精密工作需要许多部件按相对位置固定，这正是「装置」所指。"},{"no":"06","title":"Textual collation notes","titleCN":"校勘资料","definition":"the recorded variants and editorial notes that accompany a scholarly edition of a text","definitionCN":"学术版本正文旁记录的异文与编者说明","example":"The critical apparatus lists every manuscript reading.","exampleCN":"校勘资料列出了每种抄本的读法。","why":"Scholars prepare a text with supporting parts, and the old word for equipment names those supporting notes.","whyCN":"学者为正文准备支撑材料，古老的「装备」一词便用来指这些辅助记录。"},{"no":"07","title":"The assembly of a machine","titleCN":"机器的一套部件","definition":"the connected parts of a machine considered as one working whole","definitionCN":"把一台机器的各连接部件视为一个运作整体","example":"The valve is only one part of the pumping apparatus.","exampleCN":"阀门只是泵送装置的一部分。","why":"The word can name the whole working assembly, not only a bench setup, whenever the parts act together.","whyCN":"只要部件协同运作，这个词就可指整个工作总成，而不只是台面装置。"},{"no":"08","title":"Darkroom and photographic gear","titleCN":"暗房与摄影器材","definition":"the enlarger, trays, tanks and safelights used to develop photographs","definitionCN":"用于冲洗照片的放大机、药盘、罐与安全灯","example":"The school still keeps a darkroom apparatus behind the studio.","exampleCN":"学校仍在摄影室后面保留着一套暗房器材。","why":"A craft that needs a fixed sequence of prepared tools give the word another specialised home.","whyCN":"需要固定工序与预备工具的技艺，又给这个词添了一个专用场所。"}],"etymology":{"intro":{"en":"Apparatus is a Latin noun for equipment, built on a verb meaning to prepare; English borrowed it whole, including its Latin plural.","cn":"「装置」是拉丁语中表示装备的名词，建立在表示「准备」的动词上；英语整体借入，连拉丁语复数形式也一并保留。"},"items":[{"era":"LATIN PARARE","en":"Parare meant to prepare, make ready or furnish; it is the direct Latin source, while its deeper origin is uncertain and the link to a producing root is only a suggestion.","cn":"这个拉丁语动词指准备、备好或供给；它是本词的直接拉丁语来源，其更早来源存疑，与表示「产出」之古词根的关联仅为推测。"},{"era":"LATIN AD-","en":"The prefix ad-, meaning toward, combined with parare to give apparare, to get ready for a purpose.","cn":"表示「朝向」的前缀与「准备」结合，构成「为某目的做好准备」的动词。"},{"era":"LATIN APPARATUS","en":"Apparatus was the result noun: the state of being prepared and the set of things prepared, especially for a task.","cn":"这个词是结果名词，指准备好的状态以及准备好的一套东西，尤指为某项任务所备。"},{"era":"LATIN PLURAL APPARATUS","en":"The Latin fourth-declension noun kept the same form in the plural, and English still allows apparatus as a plural.","cn":"这个拉丁语第四变格名词的复数与原形同形，英语至今仍允许用原形作复数。"},{"era":"ENGLISH BORROWING · FIRST RECORD DATE UNCERTAIN","en":"English took the word in the seventeenth century for a prepared set of instruments, especially in science; the exact year of the borrowing is uncertain.","cn":"英语在十七世纪借入这个词，指准备好的一套器具，尤用于科学；具体借入年代不确定。"},{"era":"FIGURATIVE EXTENSION","en":"The same picture of prepared parts was later applied to state and party machinery and to the notes that support an edited text.","cn":"同一幅「准备好的部件」画面后来被用于国家与政党机构，以及支撑校勘版本的注释。"}]},"similar":{"note":{"en":"The first group shares the prepare root; the second group separates the four kit words.","cn":"第一组共享「准备」词根；第二组区分四个器械名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"apparatuses","ipa":"/ˌæpəˈreɪtəsɪz/","tag":"noun","definition":"The English plural, used when several separate sets are counted.","definitionCN":"英语复数，用于清点几套分开的装置。"},{"word":"prepare","ipa":"/prɪˈpeə/","tag":"verb","definition":"To make ready; the action behind the noun.","definitionCN":"做好准备；名词背后的动作。"},{"word":"preparation","ipa":"/ˌprepəˈreɪʃən/","tag":"noun","definition":"The act of making ready; it stresses the process, not the set.","definitionCN":"准备的动作；强调过程而非成套之物。"},{"word":"repair","ipa":"/rɪˈpeə/","tag":"verb","definition":"To make ready again; it shares the prepare root with a again-prefix.","definitionCN":"重新备好；共享「准备」词根并带「再次」前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equipment","ipa":"/ɪˈkwɪpmənt/","tag":"noun","definition":"A bought or issued set of machines and tools; apparatus is assembled for a task.","definitionCN":"采购或配发的成套机器工具；装置是为任务组装起来的。"},{"word":"instrument","ipa":"/ˈɪnstrəmənt/","tag":"noun","definition":"One precision measuring tool; apparatus is the whole setup around it.","definitionCN":"单件精密测量器具；装置是围绕它的整套布置。"},{"word":"instrumentation","ipa":"/ˌɪnstrəmenˈteɪʃən/","tag":"noun","definition":"The installed system of measuring and control devices in a plant.","definitionCN":"工厂中安装的测量与控制仪表系统。"},{"word":"rig","ipa":"/rɪɡ/","tag":"noun","definition":"An improvised or temporary setup; apparatus is more deliberate and complete.","definitionCN":"临时拼搭的装置；目标词更像有意搭成的完整一套。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The root verb means to prepare, so apparatus is the set made ready.","cn":"词根动词意为准备，因此装置就是准备好的一套。"},{"en":"The family runs prepare, preparation, preparatory, repair and apparatus.","cn":"同族词包括准备、制备、预备的、修理与装置。"},{"en":"Fixed phrases mark it: laboratory apparatus, breathing apparatus, state apparatus.","cn":"固定搭配可标记它：实验装置、呼吸器、国家机构。"},{"en":"The Latin plural is the same word, though English also allows apparatuses.","cn":"拉丁语复数与原形同形，英语也允许加复数词尾。"},{"en":"Its cousins are equipment, instrument, instrumentation and rig.","cn":"它的近亲是设备、仪器、仪表系统与临时装置。"}],"abstract":[{"en":"Picture a table where every glass tube knows exactly where it belongs.","cn":"想象一张桌子，每根玻璃管都清楚自己该在哪里。"},{"en":"Picture a mask that turns a hostile environment into breathable air.","cn":"想象一副面罩，把恶劣环境变成可呼吸的空气。"},{"en":"Picture a building full of offices acting like one prepared machine.","cn":"想象一栋装满办公室的建筑，像一台准备好的机器那样运作。"}]},"examples":[{"en":"The apparatus must be assembled in the order given in the manual.","cn":"这套装置必须按手册给定的顺序组装。"},{"en":"The state apparatus moved faster than the ministry itself.","cn":"国家机构比部委本身行动得更快。"},{"en":"A broken seal can ruin an entire breathing apparatus.","cn":"一处密封破损就能毁掉整套呼吸装置。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「预先备好」的一整套器械，连复数都沿用拉丁原形","word":"apparatus"},"root":"源自拉丁语「为某目的准备」的动词及其结果名词；更早词源不确定，英语十七世纪整体借入。","sensesIntro":{"en":"Eight senses follow one idea: parts prepared and joined for a purpose. The purpose may be an experiment, breathing, sport, measurement, scholarship or the action of an organization.","cn":"八个义项围绕一个观念：部件为某目的备好并连接起来。这个目的可以是实验、呼吸、运动、测量、校勘，或一个组织的行动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bench of parts clipped into place, each in its fixed position, ready for one operation.","cn":"核心意象：一台面部件被扣在各自固定位置，为一套操作准备就绪。"},"chain":["SET OF PARTS","LAB USE","BODY SUPPORT","PUBLIC POWER","MEASURE","TEXT EDITION"],"branches":[{"senses":"01 · 07","en":"THE CORE: an assembled set for an experiment, and the working parts of a machine.","cn":"核心：为实验组装的整套器械，以及机器的工作部件。"},{"senses":"02","en":"THE LIFE-SUPPORT VERSION: cylinders, regulators and masks.","cn":"生命维持版本：气瓶、调节器与面罩。"},{"senses":"03","en":"THE INSTITUTIONAL VERSION: the offices and procedures of a state or party.","cn":"机构版本：国家或政党的机关与程序。"},{"senses":"04 · 08","en":"THE SPORT AND DARKROOM VERSION: rings, bars, enlargers and trays.","cn":"运动与暗房版本：吊环、横杆、放大机与药盘。"},{"senses":"05 · 06","en":"THE PRECISION AND SCHOLARLY VERSION: aligned optical benches and collation notes.","cn":"精密与学术版本：对准的光学台与校勘注释。"}]},"affixes":{"intro":{"en":"The word is wholly Latin: a preparing verb, a purpose prefix and a result noun.","cn":"这个词完全来自拉丁语：一个「准备」动词、一个表目的前缀与一个结果名词。"},"latinIntro":{"en":"Latin apparare and apparatus supply the form; the plural is the same Latin form.","cn":"拉丁语的「准备」与「装置」提供了词形；复数沿用同一拉丁形式。"},"items":[{"word":"parare","structure":"Latin verb","meaning":"to prepare, make ready","meaningCN":"准备、备好","example":"The base verb of the family.","exampleCN":"该词族的基动词。"},{"word":"ad-","structure":"Latin prefix","meaning":"toward, for","meaningCN":"朝向、为了","example":"It becomes ap- before p.","exampleCN":"在辅音前变为另一形式。"},{"word":"apparare","structure":"Latin verb","meaning":"to get ready for a purpose","meaningCN":"为某目的做好准备","example":"The verb behind apparatus.","exampleCN":"「装置」背后的动词。"},{"word":"-atus","structure":"Latin noun ending","meaning":"result of an action","meaningCN":"动作的结果","example":"It makes the result noun.","exampleCN":"它构成结果名词。"},{"word":"apparatus","structure":"Latin noun","meaning":"a prepared set; equipment","meaningCN":"备好的一套；装备","example":"English borrowed the whole form.","exampleCN":"英语整体借入该形式。"},{"word":"-s","structure":"English plural ending","meaning":"more than one","meaningCN":"多于一个","example":"It forms apparatuses beside the Latin plural.","exampleCN":"它与拉丁复数并存构成英语复数。"},{"word":"prepare","structure":"English verb","meaning":"to make ready","meaningCN":"准备","example":"The verb entered through French.","exampleCN":"动词经法语进入英语。"},{"word":"preparation","structure":"English noun","meaning":"the act of preparing","meaningCN":"准备的动作","example":"The same root with a noun ending.","exampleCN":"同词根加名词词尾。"},{"word":"repair","structure":"English verb","meaning":"to make ready again","meaningCN":"重新备好、修理","example":"The again-prefix plus the prepare root.","exampleCN":"「再次」前缀加「准备」词根。"}],"latinEntries":[{"word":"parare","structure":"parare, paravi, paratum (v., first conjugation)","meaning":"to prepare, make ready","meaningCN":"准备、备好"},{"word":"apparare","structure":"apparare, apparavi, apparatum (v., first conjugation)","meaning":"to get ready for","meaningCN":"为……做好准备"},{"word":"apparatus","structure":"apparatus, apparatus (n., fourth declension)","meaning":"equipment; a prepared set","meaningCN":"装备；备好的一套"}],"derivatives":[{"word":"prepare","pos":"v.","zh":"由拉丁语「准备」经法语进入英语，义为「准备」"},{"word":"preparation","pos":"n.","zh":"由「准备」加名词词尾构成，义为「准备」"},{"word":"preparatory","pos":"adj.","zh":"由「准备」加形容词词尾构成，义为「预备的」"},{"word":"repair","pos":"v.","zh":"由「再次」加「准备」构成，义为「修理」"},{"word":"apparatuses","pos":"n.","zh":"由「装置」加英语复数词尾构成，义为「多套装置」"}]}},{"word":"apparatus design","ipa_uk":"/ˌæpəˈreɪtəs dɪˈzaɪn/","ipa_us":"/ˌæpəˈrætəs dɪˈzaɪn/","definition_zh":"为实验、演示或专用操作设计一整套装置的工作，包括支架、气路、防护与人机操作","definition_en":"the work of designing a complete setup for an experiment, demonstration or specialised operation, including frame, flow paths, safety and controls","core_image":"空台面上先摆出支架、气路与防护罩的位置，再逐件画尺寸，最后合成一张装配图","scene":"实验台前，工程师把支架、气路与防护罩逐件摆开，先量尺寸再画装配图。The team revised the apparatus design after the first trial failed.","sceneCN":"这里指整套装置的方案设计（第 1 个义项：为实验、演示或专用操作设计一整套装置的工作）；句意：首次试验失败后，团队修改了装置设计。","pos":[{"tag":"n.","zh":"装置设计；器械设计"}],"collocations":[{"phrase":"apparatus design review","zh":"装置设计评审"},{"phrase":"apparatus design drawing","zh":"装置设计图"},{"phrase":"laboratory apparatus design","zh":"实验室装置设计"},{"phrase":"apparatus design change","zh":"装置设计变更"},{"phrase":"apparatus design safety","zh":"装置设计安全"}],"forms":[{"label":"单数形式","form":"apparatus design"},{"label":"复数形式","form":"apparatus designs"},{"label":"动词形式","form":"design"},{"label":"名词形式","form":"designer"},{"label":"相关名词","form":"apparatus"},{"label":"形容词形式","form":"apparatal"}],"derivatives":[{"word":"apparatus","pos":"n.","zh":"由拉丁语「准备」的结果名词借入，义为「装置」"},{"word":"design","pos":"n./v.","zh":"由拉丁语「标出」经法语进入英语，义为「设计」"},{"word":"designer","pos":"n.","zh":"由「设计」加人称词尾构成，义为「设计师」"},{"word":"designate","pos":"v.","zh":"由拉丁语「标出」构成，义为「指定」"},{"word":"prepare","pos":"v.","zh":"由拉丁语「准备」经法语进入英语，义为「准备」"},{"word":"assembly","pos":"n.","zh":"由拉丁语「一起收集」进入英语，义为「装配、组件」"}],"senses":[{"no":"01","title":"Designing the whole setup","titleCN":"设计整套装置","definition":"the work of planning every part of a setup so that it performs one intended operation","definitionCN":"规划一套装置的所有部件，使它们完成一项预期操作的工作","example":"Good apparatus design starts from the operation, not from the parts.","exampleCN":"良好的装置设计从操作出发，而不是从零件出发。","why":"Apparatus names the assembled set and design names the planning, so the phrase is planning the whole set.","whyCN":"「装置」指组装好的一套，「设计」指规划，因此这个词组就是规划整套装置。"},{"no":"02","title":"Frame and support","titleCN":"支架与支承","definition":"the design of the bench, frame, clamps and mounts that hold every part in place","definitionCN":"设计把每个部件固定住的工作台、框架、夹具与支座","example":"The apparatus design used an aluminium frame to keep the optics steady.","exampleCN":"装置设计用铝型材框架让光学件保持稳定。","why":"Nothing can be measured if it moves, so the supporting frame is the first structural decision.","whyCN":"部件一动就测不准，因此支承框架是第一个结构决定。"},{"no":"03","title":"Gas and fluid paths","titleCN":"气路与液路","definition":"the layout of tubes, valves, seals and reservoirs that carry gas or liquid","definitionCN":"输送气体或液体的管路、阀门、密封与储罐布置","example":"The apparatus design put the regulator upstream of every valve.","exampleCN":"装置设计把调节器放在每个阀门的上游。","why":"Many setups exist to move a fluid, and the path of that fluid shapes the whole layout.","whyCN":"许多装置的存在就是为了输送流体，而流体的路径决定整体布置。"},{"no":"04","title":"Safety and containment","titleCN":"安全与防护","definition":"the guards, shields, vents and interlocks that keep an experiment from harming people","definitionCN":"防止实验伤人的护罩、屏蔽、泄放口与联锁","example":"The apparatus design added a shield after the first pressure spike.","exampleCN":"第一次压力骤升之后，装置设计增加了一层护罩。","why":"A setup concentrates energy and chemicals, so its design must decide where that energy may go.","whyCN":"装置把能量与化学品集中起来，因此其设计必须决定能量允许去哪里。"},{"no":"05","title":"Controls and operator interface","titleCN":"控制与操作界面","definition":"the placement of switches, gauges and touch points so that a person can run the setup safely","definitionCN":"安排开关、仪表与操作点，使人能安全运行装置","example":"The apparatus design moved the emergency stop within arm's reach.","exampleCN":"装置设计把急停按钮移到伸手可及处。","why":"A setup is run by hands, so the layout of controls is part of its design, not an afterthought.","whyCN":"装置由人手操作，因此控制布局是其设计的一部分，而不是事后补的。"},{"no":"06","title":"Serviceability and assembly","titleCN":"可维护性与拆装","definition":"the design of joints, access panels and part numbering so the setup can be built and repaired","definitionCN":"设计接头、检修口与零件编号，使装置能被组装与修理","example":"The apparatus design let one person change the filter in a minute.","exampleCN":"装置设计让一个人一分钟就能换掉滤芯。","why":"A bench setup is taken apart as often as it is used, so ease of service belongs in the design.","whyCN":"台面装置被拆开的次数不亚于使用次数，因此易维护也应纳入设计。"},{"no":"07","title":"Teaching demonstration setups","titleCN":"教学演示装置","definition":"the design of simple visible equipment that shows a principle to a class","definitionCN":"设计简单可见、能向课堂展示某一原理的器材","example":"The apparatus design for the lecture used only transparent parts.","exampleCN":"这堂讲座的装置设计只用了透明部件。","why":"When the purpose is to show rather than to measure, visibility becomes the leading design rule.","whyCN":"当目的是展示而非测量时，可见性就成了首要设计规则。"},{"no":"08","title":"Verification and trial runs","titleCN":"验证与试运行","definition":"the testing, leak checking and revision that follows a first design","definitionCN":"首版设计之后的试验、查漏与改版","example":"The apparatus design was signed off only after three trial runs.","exampleCN":"装置设计在三次试运行之后才获批准。","why":"A design for a setup is a claim about behaviour, and only a trial can confirm it.","whyCN":"装置设计是关于行为的断言，只有试运行才能证实它。"}],"etymology":{"intro":{"en":"Apparatus design joins a Latin result noun for a prepared set with a Latin-rooted verb for marking out a plan.","cn":"「装置设计」把一个拉丁语中表示「备好的一套」的结果名词，与一个拉丁语词根、表示「标出计划」的动词组合。"},"items":[{"era":"LATIN PARARE","en":"Parare meant to prepare or make ready; it is the direct Latin source, while its deeper origin is uncertain and the link to a producing root is only a suggestion.","cn":"这个拉丁语动词指准备、备好；它是本词的直接拉丁语来源，其更早来源存疑，与表示「产出」之古词根的关联仅为推测。"},{"era":"LATIN APPARATUS","en":"Apparatus named the prepared set itself, and English borrowed the whole Latin form in the seventeenth century.","cn":"这个拉丁语名词指备好的一套本身，英语在十七世纪整体借入该拉丁形式。"},{"era":"LATIN SIGNUM","en":"Signum meant a mark or sign; designare meant to mark out, and English design came through French and Italian.","cn":"这个拉丁语名词指标记或符号；相应动词表示标出，英语的「设计」经法语与意大利语进入。"},{"era":"NINETEENTH CENTURY LAB WORK","en":"As experimental science built custom benches, planning the whole setup became a distinct task with drawings and trials.","cn":"随着实验科学搭起定制台架，规划整套装置成为一项有图纸与试验的独立任务。"},{"era":"SAFETY AND STANDARDS","en":"Pressure, heat and chemicals forced designers to treat guards and interlocks as part of the plan.","cn":"压力、高温与化学品迫使设计者把护罩与联锁纳入方案。"},{"era":"MODERN PHRASE · FIRST RECORD DATE UNCERTAIN","en":"The two words became a fixed phrase for the engineering of a complete experimental or industrial setup; the exact year of first record is uncertain.","cn":"这两个词固定成词组，指完整实验或工业装置的工程工作；具体首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the prepare root; the second group names adjacent design tasks.","cn":"第一组共享「准备」词根；第二组是相邻的设计任务。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"apparatus","ipa":"/ˌæpəˈreɪtəs/","tag":"noun","definition":"The assembled set itself; the target is the plan for it.","definitionCN":"组装好的装置本身；目标词是它的方案。"},{"word":"prepare","ipa":"/prɪˈpeə/","tag":"verb","definition":"To make ready; the root action behind apparatus.","definitionCN":"准备；装置背后的词根动作。"},{"word":"design","ipa":"/dɪˈzaɪn/","tag":"noun/verb","definition":"A plan or the act of planning.","definitionCN":"计划或规划行为。"},{"word":"designer","ipa":"/dɪˈzaɪnə/","tag":"noun","definition":"The person who makes the plan.","definitionCN":"制定方案的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equipment design","ipa":"/ɪˈkwɪpmənt dɪˈzaɪn/","tag":"noun","definition":"Designing a purchased set of machines; the target is usually a bespoke lab setup.","definitionCN":"设计采购来的成套机器；目标词通常指定制的实验装置。"},{"word":"fixture design","ipa":"/ˈfɪkstʃə dɪˈzaɪn/","tag":"noun","definition":"Designing the holding devices for manufacturing; narrower than a whole apparatus.","definitionCN":"设计制造用的夹持装置；比整套装置窄。"},{"word":"rig design","ipa":"/rɪɡ dɪˈzaɪn/","tag":"noun","definition":"Designing a temporary test setup; the target suggests a more permanent, finished arrangement.","definitionCN":"设计临时试验台；目标词暗示更永久、更完整的布置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Apparatus is the prepared set; design is the plan marked out in advance.","cn":"装置是备好的一套，设计是预先标出的方案。"},{"en":"The family runs apparatus, prepare, design, designer, designate.","cn":"同族词包括装置、准备、设计、设计师、指定。"},{"en":"Fixed phrases mark it: apparatus design review, apparatus design drawing.","cn":"固定搭配可标记它：装置设计评审、装置设计图。"},{"en":"Its four layers are frame, flow path, safety and controls.","cn":"它的四层是框架、流路、安全与控制。"},{"en":"Its proof is a trial run with no leak and no surprise.","cn":"它的证明是一次无泄漏、无意外的试运行。"}],"abstract":[{"en":"Picture a table that holds every glass part exactly still while hands work around it.","cn":"想象一张桌子，在所有手围绕它操作时把每个玻璃件稳稳固定。"},{"en":"Picture a cage that lets heat out but keeps fingers in.","cn":"想象一个只放热、不放手指进来的罩子。"},{"en":"Picture a switch placed where a frightened hand will find it first.","cn":"想象一个开关放在惊慌的手最先能摸到的地方。"}]},"examples":[{"en":"The apparatus design had to fit through a standard doorway.","cn":"这套装置设计必须能通过一扇标准门。"},{"en":"Safety review stopped the apparatus design until the vent was moved.","cn":"安全评审叫停了装置设计，直到泄放口被移位。"},{"en":"Students compare two apparatus designs for the same reaction.","cn":"学生们比较同一反应的两种装置设计。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「装置」+「设计」——把一整套器械先在纸上摆稳","word":"apparatus design"},"root":"前半源自拉丁语「备好的一套」，后半源自拉丁语「标出、规划」；两词根更早来源均存疑。","sensesIntro":{"en":"Eight senses follow a setup from purpose to proof: frame, flow, safety, controls, service, teaching and trial. The phrase covers the plan for a whole experimental or industrial arrangement.","cn":"八个义项跟随一套装置从目的走到验证：框架、流路、安全、控制、维护、教学与试运行。这个词组覆盖完整实验或工业装置的方案。"},"semanticMap":{"core":{"en":"CORE IMAGE: an empty bench where the places of frame, tubes, shield and switch are marked before anything is built.","cn":"核心意象：一张空台面，在动手之前先标出框架、管路、护罩与开关的位置。"},"chain":["PURPOSE","FRAME","FLOW","SAFETY","CONTROL","TEST"],"branches":[{"senses":"01","en":"THE WHOLE PLAN: every part planned around one intended operation.","cn":"整体方案：围绕一项预期操作规划所有部件。"},{"senses":"02","en":"THE SUPPORT VERSION: bench, frame, clamps and mounts.","cn":"支承版本：工作台、框架、夹具与支座。"},{"senses":"03","en":"THE FLOW VERSION: tubes, valves, seals and reservoirs.","cn":"流路版本：管路、阀门、密封与储罐。"},{"senses":"04 · 05","en":"THE SAFE-USE VERSION: guards and interlocks, plus controls within reach.","cn":"安全使用版本：护罩与联锁，以及伸手可及的控制。"},{"senses":"06 · 07 · 08","en":"THE SERVICE, TEACHING AND PROOF VERSION: access, visibility and trial runs.","cn":"维护、教学与验证版本：检修口、可见性与试运行。"}]},"affixes":{"intro":{"en":"One half is the Latin prepared set; the other is the Latin-rooted plan marked out with signs.","cn":"一半是拉丁语「备好的一套」，另一半是拉丁语词根、用符号标出的方案。"},"latinIntro":{"en":"Latin apparatus supplies the first half; signum and designare supply the second.","cn":"拉丁语的「装置」提供前半，符号与「标出」提供后半。"},"items":[{"word":"parare","structure":"Latin verb","meaning":"to prepare","meaningCN":"准备","example":"The root of apparatus.","exampleCN":"「装置」的词根。"},{"word":"apparare","structure":"Latin verb","meaning":"to get ready for","meaningCN":"为……准备","example":"The verb behind the noun.","exampleCN":"名词背后的动词。"},{"word":"apparatus","structure":"Latin noun","meaning":"a prepared set","meaningCN":"备好的一套","example":"The first half of the target.","exampleCN":"目标词的前半。"},{"word":"signum","structure":"Latin noun","meaning":"a mark, a sign","meaningCN":"标记、符号","example":"The root of design.","exampleCN":"「设计」的词根。"},{"word":"designare","structure":"Latin verb","meaning":"to mark out, plan","meaningCN":"标出、规划","example":"It became English design.","exampleCN":"它成为英语的「设计」。"},{"word":"design","structure":"English noun and verb","meaning":"a plan; to plan","meaningCN":"方案；规划","example":"The second half of the target.","exampleCN":"目标词的后半。"},{"word":"-er","structure":"agent ending","meaning":"one who does","meaningCN":"做……的人","example":"It forms designer.","exampleCN":"它构成「设计师」。"},{"word":"assembly","structure":"English noun","meaning":"parts put together","meaningCN":"装配、组件","example":"It names the built result of the plan.","exampleCN":"它指方案建成后的结果。"},{"word":"fixture","structure":"English noun","meaning":"a holding device","meaningCN":"夹持装置","example":"A small apparatus for holding work.","exampleCN":"用于夹持工件的小装置。"}],"latinEntries":[{"word":"apparare","structure":"apparare, apparavi, apparatum (v., first conjugation)","meaning":"to get ready for","meaningCN":"为……准备"},{"word":"apparatus","structure":"apparatus, apparatus (n., fourth declension)","meaning":"a prepared set","meaningCN":"备好的一套"},{"word":"designare","structure":"designare, designavi, designatum (v., first conjugation)","meaning":"to mark out, plan","meaningCN":"标出、规划"}],"derivatives":[{"word":"apparatus","pos":"n.","zh":"由拉丁语「准备」的结果名词借入，义为「装置」"},{"word":"design","pos":"n./v.","zh":"由拉丁语「标出」经法语进入英语，义为「设计」"},{"word":"designer","pos":"n.","zh":"由「设计」加人称词尾构成，义为「设计师」"},{"word":"designate","pos":"v.","zh":"由「标出」构成，义为「指定」"},{"word":"prepare","pos":"v.","zh":"由拉丁语「准备」经法语进入英语，义为「准备」"},{"word":"assembly","pos":"n.","zh":"由拉丁语「一起收集」进入英语，义为「装配」"}]}},{"word":"prototype","ipa_uk":"/ˈprəʊtətaɪp/","ipa_us":"/ˈproʊtətaɪp/","definition_zh":"为测试设计而造出的第一个完整模型或样机；也指某类事物的早期范例","definition_en":"the first full working model of a design, built for testing, or an early example that a later type follows","core_image":"工作台上，一台用螺栓临时拼起的样机正在空转，外壳未喷漆，线束裸露，却已能完成主要动作","scene":"工作台上，一台用螺栓临时拼起的样机正在空转，外壳还没喷漆，线束露在外面。They built a prototype of the pump in a single week.","sceneCN":"这里指用于测试的样机（第 1 个义项：为测试设计而造出的第一个完整模型或样机）；句意：他们用一周时间造出了泵的样机。","pos":[{"tag":"n.","zh":"原型；样机；范例"}],"collocations":[{"phrase":"working prototype","zh":"可运行的样机"},{"phrase":"prototype stage","zh":"原型阶段"},{"phrase":"prototype testing","zh":"样机测试"},{"phrase":"software prototype","zh":"软件原型"},{"phrase":"prototype model","zh":"原型模型"},{"phrase":"early prototype","zh":"早期原型"}],"forms":[{"label":"单数形式","form":"prototype"},{"label":"复数形式","form":"prototypes"},{"label":"动词形式","form":"prototype"},{"label":"现在分词","form":"prototyping"},{"label":"形容词形式","form":"prototypical"},{"label":"相关名词","form":"prototyping"}],"derivatives":[{"word":"prototypical","pos":"adj.","zh":"由「原型」加形容词词尾构成，义为「典型的、原型的」"},{"word":"prototypically","pos":"adv.","zh":"由「典型的」加副词词尾构成，义为「典型地」"},{"word":"prototyping","pos":"n.","zh":"由「做原型」加动名词词尾构成，义为「原型制作」"},{"word":"archetype","pos":"n.","zh":"由希腊语「最初的」与「印模」构成，义为「典范、原型」"}],"senses":[{"no":"01","title":"The first working model","titleCN":"第一个可工作的模型","definition":"the first complete model of a product, built so that its design can be tested","definitionCN":"为测试设计而造出的产品第一个完整模型","example":"The prototype ran for ten minutes before the seal failed.","exampleCN":"样机运行了十分钟后密封失效。","why":"Proto- means first and type means model, so the word is the first model of a kind.","whyCN":"「第一」与「印模」相加，这个词就是同类中的第一个模型。"},{"no":"02","title":"A pre-production sample","titleCN":"量产前的试制样品","definition":"a sample made with production methods to check tooling and assembly before mass output","definitionCN":"用生产方式做出、在批量产出前检查工装与装配的样品","example":"The factory built ten prototypes before releasing the moulds.","exampleCN":"工厂在开模之前造了十件试制样品。","why":"As a design approaches production, the first model becomes a sample that tests the factory, not only the idea.","whyCN":"当设计接近生产时，第一个模型就变成检验工厂而不只检验想法的样品。"},{"no":"03","title":"A clickable software model","titleCN":"可点击的软件原型","definition":"an interactive mock-up of screens used to test a workflow before code is written","definitionCN":"在写代码之前用来测试流程的屏幕交互模型","example":"The team tested the checkout prototype with five users.","exampleCN":"团队用五名用户测试了结账流程原型。","why":"Software has no metal to bend, so its first model is a set of linked screens.","whyCN":"软件没有可弯的金属，因此它的第一个模型是一组相连的屏幕。"},{"no":"04","title":"A concept vehicle","titleCN":"概念样车","definition":"a one-off vehicle built to show a design direction rather than to be sold","definitionCN":"为展示设计方向而非出售而造的单台车辆","example":"The concept prototype had no door handles at all.","exampleCN":"这台概念样车完全没有门把手。","why":"Transport design uses a full-size model to judge proportion, and that model is a prototype.","whyCN":"交通工具设计用全尺寸模型判断比例，这个模型就是原型。"},{"no":"05","title":"A flight test article","titleCN":"航空试验样机","definition":"an aircraft or engine built for flight testing before a production standard is fixed","definitionCN":"在确定生产标准之前为飞行试验而造的飞机或发动机","example":"The first flight prototype carried extra sensors instead of seats.","exampleCN":"第一架飞行样机装的是额外传感器而不是座椅。","why":"Flight cannot be simulated fully, so aviation builds a prototype that is meant to be flown and measured.","whyCN":"飞行无法完全模拟，因此航空会造一架用于飞行与测量的原型。"},{"no":"06","title":"An early example of a type","titleCN":"某类事物的早期范例","definition":"a person or thing that later examples are modelled on","definitionCN":"后来同类事物据以塑造的早期人或物","example":"The village is a prototype of the new eco-settlement.","exampleCN":"这个村庄是新生态聚落的原型。","why":"From first model comes the wider sense of a pattern that later things copy.","whyCN":"从「第一个模型」引申出更宽的「后来者仿效的范式」之义。"},{"no":"07","title":"The best example of a category","titleCN":"范畴中的典型样本","definition":"the member of a category that most people regard as most typical of it","definitionCN":"一个范畴中最被大众视为典型的那一个成员","example":"In prototype theory, a robin is a better prototype than an ostrich.","exampleCN":"在原型理论中，知更鸟比鸵鸟更像典型样本。","why":"Psychology borrowed the word for the mental best example that organizes a category.","whyCN":"心理学借这个词指组织范畴的心理最佳样本。"},{"no":"08","title":"A rough first version","titleCN":"粗坯初版","definition":"any preliminary version of a document, plan or product made for comment","definitionCN":"为征求意见而做的最初版本文件、方案或产品","example":"This report is only a prototype; the numbers will change.","exampleCN":"这份报告只是初版，数字还会变。","why":"Any first attempt can be called a prototype because it is made to be tested and replaced.","whyCN":"任何第一次尝试都可称原型，因为它本来就是用来试验并替换的。"}],"etymology":{"intro":{"en":"Prototype joins two Greek elements, first and impression, and reached English through Latin; the modern industrial sense grew from the idea of an original impression.","cn":"「原型」把两个希腊语成分「第一」与「印模」组合，经拉丁语进入英语；现代工业义从「最初的印痕」这一观念发展而来。"},"items":[{"era":"GREEK PROTOS","en":"Protos meant first or foremost, and it begins many English words about priority.","cn":"这个希腊语词指第一或最前，它是许多表示优先的英语词的开头。"},{"era":"GREEK TYPOS","en":"Typos meant a blow, the mark left by a blow, and so a model or impression; it is the source of English type.","cn":"这个希腊语名词指击打、击打留下的痕记，因此也指模子或印痕；它是英语「类型」的来源。"},{"era":"GREEK PROTOTYPON","en":"The compound meant an original model or first impression, the pattern from which copies are made.","cn":"这个复合词指最初的模子或第一次印痕，即据以复制出副本的范式。"},{"era":"LATIN PROTOTYPUM","en":"Late Latin took the Greek compound as prototypum, keeping the sense of an original form.","cn":"晚期拉丁语把这个希腊复合词接收为「最初的模子」，保留了「原初形式」之义。"},{"era":"ENGLISH EARLY USE","en":"English used prototype from the sixteenth century for an original or a model, often in learned and religious writing.","cn":"英语从十六世纪起用这个词指原初之物或模子，多见于学术与宗教写作。"},{"era":"MODERN INDUSTRIAL SENSE","en":"Twentieth-century engineering narrowed the word to the first full model of a product, built to be tested before production.","cn":"二十世纪工程把词义缩小为产品的第一个完整模型，为生产前的测试而造。"}]},"similar":{"note":{"en":"The first group shares the type root; the second group names nearby model words.","cn":"第一组共享「印模」词根；第二组是相邻的模型用语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"type","ipa":"/taɪp/","tag":"noun","definition":"A kind or a printed character; the root word behind prototype.","definitionCN":"种类或印刷字符；原型背后的词根词。"},{"word":"prototypical","ipa":"/ˌprəʊtəˈtɪpɪkəl/","tag":"adjective","definition":"Most typical of a category; derived from the same word.","definitionCN":"某范畴中最典型的；由同一个词派生。"},{"word":"archetype","ipa":"/ˈɑːkitaɪp/","tag":"noun","definition":"An original pattern or ideal model; it stresses origin more than testing.","definitionCN":"原初范式或理想模型；强调起源而非测试。"},{"word":"stereotype","ipa":"/ˈsteriətaɪp/","tag":"noun","definition":"A fixed oversimplified image; it shares the impression element.","definitionCN":"固定而简化的印象；共享「印痕」成分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mock-up","ipa":"/ˈmɒk ʌp/","tag":"noun","definition":"A full-size model for appearance or layout, often not working.","definitionCN":"用于看外观或布局的全尺寸模型，常不能运转。"},{"word":"sample","ipa":"/ˈsɑːmpəl/","tag":"noun","definition":"One item taken to represent a batch; it need not be the first model.","definitionCN":"从一批中取出代表整体的一个；不必是第一个模型。"},{"word":"pilot","ipa":"/ˈpaɪlət/","tag":"noun","definition":"A small trial production or plant before full scale; it stresses scale-up, not the first model.","definitionCN":"全面推广前的小规模试产或试验厂；强调放大，而非第一个模型。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"First plus impression equals the first model of a kind.","cn":"「第一」加「印模」，等于同类中的第一个模型。"},{"en":"The family runs prototype, prototypical, prototyping, archetype, stereotype.","cn":"同族词包括原型、典型的、原型制作、原初范式、刻板印象。"},{"en":"Fixed phrases mark it: working prototype, prototype stage, prototype testing.","cn":"固定搭配可标记它：可运行样机、原型阶段、样机测试。"},{"en":"A prototype is built to be broken, measured and replaced.","cn":"原型本来就是用来被弄坏、被测量并替换的。"},{"en":"It differs from a mock-up by working, and from a sample by being first.","cn":"它与模型样板的差别在于能运转，与样品的差别在于它是第一个。"}],"abstract":[{"en":"Picture a rough clay figure made only to see whether the pose works.","cn":"想象一个粗捏的泥人，只为看看姿势是否成立。"},{"en":"Picture a key cut from soft wax before the metal is touched.","cn":"想象在碰金属之前先用软蜡削出一把钥匙。"},{"en":"Picture a first draft written in pencil so that it can be erased without regret.","cn":"想象一份用铅笔写的初稿，擦掉也不心疼。"}]},"examples":[{"en":"The prototype leaked, so the seal was redesigned.","cn":"样机漏了，于是密封被重新设计。"},{"en":"A prototype is judged by what it teaches, not by how it looks.","cn":"样机的价值在于它教给我们什么，而不在于它好不好看。"},{"en":"The museum keeps the prototype of the first electric kettle.","cn":"博物馆保存着第一只电水壶的原型。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「第一」个「印模」——先压出一个样子，再照着做","word":"prototype"},"root":"由希腊语「第一」与「击打留下的印痕、模子」复合，经晚期拉丁语进入英语；现代工业义为生产前测试的第一个完整模型。","sensesIntro":{"en":"Eight senses follow one first model: it is built, tested, shown, flown, copied and finally treated as the type of its kind.","cn":"八个义项跟随一个最初的模型：它被造出、被测试、被展示、被飞行、被仿效，最后被视为同类之型。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rough first build standing on a bench, wires showing, made only to be tested.","cn":"核心意象：一台粗糙的初版样机立在台面上，线束外露，生来就是为了被测试。"},"chain":["FIRST BUILD","TEST MODEL","SOFTWARE MOCK","VEHICLE MULE","FLIGHT ARTICLE","TYPICAL EXAMPLE"],"branches":[{"senses":"01 · 02","en":"THE PHYSICAL FIRST: a working model and a pre-production sample.","cn":"实体初版：可工作的模型与量产前样品。"},{"senses":"03","en":"THE SOFTWARE VERSION: linked screens instead of metal.","cn":"软件版本：相连的屏幕而非金属。"},{"senses":"04 · 05","en":"THE TRANSPORT VERSION: concept vehicles and flight test articles.","cn":"交通版本：概念样车与飞行试验样机。"},{"senses":"06 · 07","en":"THE EXAMPLE VERSION: an early pattern, and the best member of a category.","cn":"范例版本：早期范式与范畴中的最佳样本。"},{"senses":"08","en":"THE DRAFT VERSION: any rough first version offered for comment.","cn":"草案版本：任何供征求意见的粗略初版。"}]},"affixes":{"intro":{"en":"Both elements are Greek: first, and the mark left by a blow that became the word for type.","cn":"两个成分都是希腊语：表示「第一」的词，以及击打留下的痕记，后者成为「类型」一词。"},"latinIntro":{"en":"Late Latin prototypum carried the Greek compound into European use.","cn":"晚期拉丁语的「最初模子」把这个希腊复合词带入欧洲语言。"},"items":[{"word":"protos","structure":"Greek adjective","meaning":"first, foremost","meaningCN":"第一、最前","example":"It begins the compound.","exampleCN":"它构成复合词的前半。"},{"word":"typos","structure":"Greek noun","meaning":"a blow; the mark left; a model","meaningCN":"击打；留下的痕记；模子","example":"It supplies the impression half.","exampleCN":"它提供「印痕」一半。"},{"word":"typein","structure":"Greek verb","meaning":"to strike, impress","meaningCN":"击打、压印","example":"The verb behind typos.","exampleCN":"「印痕」背后的动词。"},{"word":"prototypon","structure":"Greek compound noun","meaning":"an original model","meaningCN":"最初的模子","example":"The whole compound.","exampleCN":"整个复合词。"},{"word":"prototypum","structure":"Late Latin noun","meaning":"an original form","meaningCN":"原初形式","example":"Latin carried it to English.","exampleCN":"拉丁语把它带到英语。"},{"word":"prototype","structure":"English noun","meaning":"a first working model","meaningCN":"第一个可工作的模型","example":"The modern sense is industrial.","exampleCN":"现代义属工业领域。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It forms prototypical.","exampleCN":"它构成「典型的」。"},{"word":"-ing","structure":"noun ending","meaning":"the activity of","meaningCN":"……的活动","example":"It forms prototyping.","exampleCN":"它构成「原型制作」。"},{"word":"arch-","structure":"Greek prefix","meaning":"beginning, first","meaningCN":"开端、最初","example":"It forms archetype beside prototype.","exampleCN":"它与目标词并列构成「原初范式」。"}],"latinEntries":[{"word":"prototypum","structure":"prototypum, prototypi (n., second declension, from Greek)","meaning":"an original model","meaningCN":"最初的模子"},{"word":"typus","structure":"typus, typi (n., second declension, from Greek)","meaning":"a mark, model, type","meaningCN":"印记、模子、类型"}],"derivatives":[{"word":"prototypical","pos":"adj.","zh":"由「原型」加形容词词尾构成，义为「典型的」"},{"word":"prototypically","pos":"adv.","zh":"由「典型的」加副词词尾构成，义为「典型地」"},{"word":"prototyping","pos":"n.","zh":"由「做原型」加动名词词尾构成，义为「原型制作」"},{"word":"archetype","pos":"n.","zh":"由希腊语「最初」与「模子」构成，义为「原初范式」"},{"word":"stereotype","pos":"n.","zh":"由希腊语「坚硬」与「印痕」构成，义为「刻板印象」"}]}},{"word":"prototyping","ipa_uk":"/ˈprəʊtətaɪpɪŋ/","ipa_us":"/ˈproʊtətaɪpɪŋ/","definition_zh":"制作原型并反复测试、修改的过程","definition_en":"the process of building prototypes and testing and revising them repeatedly","core_image":"同一件外壳在工作台上换了一版又一版，每版装到样机上试一下，坏处被记下，下一版立刻改掉","scene":"车间里，同一件外壳在三天内打印了四版，每一版都装到样机上试用。Rapid prototyping cut the cost of every iteration.","sceneCN":"这里指快速原型制作这一过程（第 2 个义项：用增材制造快速做出原型的过程）；句意：快速原型制作降低了每一次迭代的成本。","pos":[{"tag":"n.","zh":"原型制作；样机试制"}],"collocations":[{"phrase":"rapid prototyping","zh":"快速原型制作"},{"phrase":"prototyping stage","zh":"原型制作阶段"},{"phrase":"prototyping tool","zh":"原型制作工具"},{"phrase":"software prototyping","zh":"软件原型制作"},{"phrase":"prototyping service","zh":"原型制作服务"},{"phrase":"iterative prototyping","zh":"迭代式原型制作"}],"forms":[{"label":"不可数名词","form":"prototyping"},{"label":"动词形式","form":"prototype"},{"label":"过去式","form":"prototyped"},{"label":"过去分词","form":"prototyped"},{"label":"现在分词","form":"prototyping"},{"label":"名词形式","form":"prototype"}],"derivatives":[{"word":"prototype","pos":"n./v.","zh":"由希腊语「第一」与「印模」构成，义为「原型；试制」"},{"word":"prototyped","pos":"adj.","zh":"由「试制」加已然词尾构成，义为「已做出原型的」"},{"word":"prototyper","pos":"n.","zh":"由「做原型」加施动词尾构成，义为「原型制作者」"},{"word":"prototypical","pos":"adj.","zh":"由「原型」加形容词词尾构成，义为「典型的」"},{"word":"archetype","pos":"n.","zh":"由希腊语「最初」与「模子」构成，义为「原初范式」"}],"senses":[{"no":"01","title":"The process of building a first model","titleCN":"制作第一个模型的过程","definition":"the work of turning a design idea into a first physical or digital model","definitionCN":"把设计想法变成第一个实体或数字模型的工作","example":"Prototyping started with cardboard before any metal was cut.","exampleCN":"原型制作从硬纸板开始，还没切任何金属。","why":"The action ending turns prototype into the ongoing work of making one.","whyCN":"动作词尾把「原型」变成制作原型的持续工作。"},{"no":"02","title":"Rapid prototyping by additive printing","titleCN":"以增材打印实现的快速原型","definition":"the fast production of models by layer-by-layer printing or machining","definitionCN":"通过逐层打印或加工快速做出模型","example":"Rapid prototyping put a new casing in her hands overnight.","exampleCN":"快速原型制作一夜之间就把新外壳交到她手上。","why":"When printing replaced weeks of tooling, speed became the defining feature of the process.","whyCN":"当打印取代了数周的工装准备，速度就成了这一过程的标志特征。"},{"no":"03","title":"Software prototype iteration","titleCN":"软件原型的迭代","definition":"the repeated building and testing of interactive screens before final code","definitionCN":"在最终代码之前反复搭建并测试交互界面的过程","example":"Prototyping the checkout flow exposed two confusing steps.","exampleCN":"结账流程的原型制作暴露了两个令人困惑的步骤。","why":"Software can be modelled cheaply, so the work is repeated many times before coding.","whyCN":"软件可以低成本建模，因此在写代码前这项工作会被重复许多次。"},{"no":"04","title":"Hardware breadboarding","titleCN":"硬件打样","definition":"the assembly and testing of a rough circuit or mechanism on a bench","definitionCN":"在台面上组装并测试粗略电路或机构","example":"Prototyping on the bench found the loose ground before the board was made.","exampleCN":"台面原型制作在制板前发现了松动的地线。","why":"A rough hand-built version tests an idea before a printed board or a machined part exists.","whyCN":"在印制板或机加工件出现之前，手工粗版用来检验想法。"},{"no":"05","title":"Proof of concept","titleCN":"概念验证","definition":"the making of a model whose only purpose is to show that an idea can work at all","definitionCN":"只为证明某想法能否成立而做模型","example":"Their prototyping answered one question: can this valve seal at all?","exampleCN":"他们的原型制作只回答了一个问题：这个阀门到底能不能密封？","why":"When a model exists only to show feasibility, the work is judged by the single yes or no it produces.","whyCN":"当模型只为证明可行性时，这项工作就以它给出的那一个「行或不行」来评判。"},{"no":"06","title":"Models for user testing","titleCN":"供用户测试的模型","definition":"the building of models that real users try so that their reactions can be observed","definitionCN":"做出让真实用户试用、以便观察反应的模型","example":"Prototyping with five nurses changed the layout of the alarm panel.","exampleCN":"让五名护士参与的原型制作改变了报警面板的布局。","why":"A model in someone else's hands reveals what a designer cannot see alone, so the work moves into observation.","whyCN":"模型到了别人手里，就会显露设计者独自看不到的问题，于是这项工作转入观察。"},{"no":"07","title":"Iterative trial and error","titleCN":"迭代式试错","definition":"the method of making, testing, learning and remaking in short cycles","definitionCN":"在短周期内制作、测试、学习并重做的方法","example":"Prototyping works because each failure is cheap and quick.","exampleCN":"原型制作之所以有效，是因为每次失败都便宜而迅速。","why":"The method replaces one large risk with many small ones, and each small risk is paid off by a lesson.","whyCN":"这种方法用许多小风险替代一个大风险，而每个小风险都由一次教训来偿还。"},{"no":"08","title":"A prototyping service or role","titleCN":"原型制作服务或岗位","definition":"a workshop, team or job whose business is making models for others","definitionCN":"以替他人制作模型为业的工坊、团队或岗位","example":"The university runs a prototyping lab for student projects.","exampleCN":"大学为学生项目办了一个原型制作实验室。","why":"Once the activity is needed regularly, it becomes a place and a job, and the action noun names that service.","whyCN":"当这项活动需要定期进行时，它就变成场所与岗位，动作名词便命名这种服务。"}],"etymology":{"intro":{"en":"Prototyping is prototype plus an action ending; it names the repeated work rather than the model itself.","cn":"「原型制作」是「原型」加动作词尾；它命名反复进行的工作，而不是模型本身。"},"items":[{"era":"GREEK PROTOS","en":"Protos meant first, and it begins the older compound from which prototype comes.","cn":"这个希腊语词指第一，它是「原型」所自的古老复合词的开头。"},{"era":"GREEK TYPOS","en":"Typos meant a blow and the mark it leaves, hence a model; English type comes from the same word.","cn":"这个希腊语名词指击打及其留下的痕记，因此指模子；英语「类型」也来自同一个词。"},{"era":"GREEK PROTOTYPON","en":"The compound named an original model from which copies are made, and Latin carried it into English.","cn":"这个复合词指据以复制的最初模子，拉丁语把它带入英语。"},{"era":"ENGLISH ACTION NOUN","en":"Adding the action ending produced a noun for the activity of making such models, first in craft and later in industry.","cn":"加上动作词尾后，产生了指制作此类模型活动的名词，先用于手艺，后用于工业。"},{"era":"DIGITAL AND ADDITIVE SHIFT","en":"Late twentieth-century computing and printing turned the activity into a fast, repeated loop of build, test and revise.","cn":"二十世纪后期的计算与打印技术把这项活动变成快速重复的「制作、测试、修改」循环。"},{"era":"MODERN PRACTICE","en":"The word now covers cardboard models, printed parts, breadboards and clickable screens, all governed by the same short cycle.","cn":"这个词如今涵盖纸板模型、打印件、电路打样板与可点击屏幕，它们都遵循同一个短周期。"}]},"similar":{"note":{"en":"The first group shares the prototype stem; the second group names adjacent model-making practices.","cn":"第一组共享「原型」词干；第二组是相邻的制模做法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prototype","ipa":"/ˈprəʊtətaɪp/","tag":"noun","definition":"The model itself; the target is the work of making and testing it.","definitionCN":"模型本身；目标词是制作与测试它的工作。"},{"word":"prototyped","ipa":"/ˈprəʊtətaɪpt/","tag":"adjective","definition":"Already made as a prototype; it describes a state.","definitionCN":"已做成原型的；描述状态。"},{"word":"prototyper","ipa":"/ˈprəʊtətaɪpə/","tag":"noun","definition":"A person or tool that makes prototypes.","definitionCN":"制作原型的人或工具。"},{"word":"prototypical","ipa":"/ˌprəʊtəˈtɪpɪkəl/","tag":"adjective","definition":"Most typical; it belongs to the example sense, not the making sense.","definitionCN":"最典型的；属于范例义，而非制作义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rapid prototyping","ipa":"/ˈræpɪd ˈprəʊtətaɪpɪŋ/","tag":"noun","definition":"The fast, often printed, form of the activity; narrower than the whole process.","definitionCN":"快速、常用打印的活动形式；比整个流程窄。"},{"word":"model making","ipa":"/ˈmɒdəl ˌmeɪkɪŋ/","tag":"noun","definition":"Craft work producing scale models; it need not test a design.","definitionCN":"制作比例模型的手艺；不一定检验设计。"},{"word":"pilot production","ipa":"/ˈpaɪlət prəˈdʌkʃən/","tag":"noun","definition":"A small production run that tests the factory rather than the design idea.","definitionCN":"检验工厂而非设计想法的小批量生产。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"Prototype plus the action ending equals the work of making models.","cn":"「原型」加动作词尾，等于制作模型的工作。"},{"en":"The family runs prototype, prototyped, prototyper, prototypical, prototyping.","cn":"同族词包括原型、已试制的、原型制作者、典型的、原型制作。"},{"en":"Fixed phrases mark it: rapid prototyping, prototyping stage, prototyping tool.","cn":"固定搭配可标记它：快速原型制作、原型制作阶段、原型制作工具。"},{"en":"Its cycle is short: build, test, learn, rebuild.","cn":"它的循环很短：制作、测试、学习、重做。"},{"en":"Its value comes from cheap failure, not from a perfect first model.","cn":"它的价值来自廉价的失败，而不是完美的首版模型。"}],"abstract":[{"en":"Picture a potter who throws a bowl away after each lesson and starts again.","cn":"想象一位陶工，每学一课就扔掉一只碗，再重新开始。"},{"en":"Picture a key cut in wax again and again until the lock turns.","cn":"想象用蜡反复削钥匙，直到锁能转动。"},{"en":"Picture a rehearsal where mistakes cost nothing and are welcome.","cn":"想象一次排练，犯错不花钱，而且受欢迎。"}]},"examples":[{"en":"Prototyping shortens the distance between an idea and a test.","cn":"原型制作缩短了想法与测试之间的距离。"},{"en":"They spent two weeks prototyping before touching the production line.","cn":"他们在碰生产线之前花了两周做原型。"},{"en":"Her job is prototyping control panels for new machines.","cn":"她的工作是为新机器做控制面板原型。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「原型」加「制作」——快速做出、快速试错、快速再改","word":"prototyping"},"root":"由希腊语「第一」与「印痕、模子」的复合词加动名词词尾构成；现代义强调快速重复的制作与测试循环。","sensesIntro":{"en":"Eight senses follow one short cycle: build a rough model, test it, learn, rebuild. The cycle may involve cardboard, printed parts, circuits, screens or a service team.","cn":"八个义项围绕一个短循环：做出粗模、测试、学习、重做。这个循环可以涉及纸板、打印件、电路、屏幕或一个服务团队。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new version of the same casing appearing on the bench every few hours, each tested and replaced.","cn":"核心意象：同一件外壳每隔几小时就在台面上出现一个新版本，每个都被测试然后替换。"},"chain":["ROUGH BUILD","QUICK LOOP","TEST","REVISE","ITERATE","PROVE"],"branches":[{"senses":"01","en":"THE CORE PROCESS: turning an idea into a first model by hand or by tool.","cn":"核心过程：用手或工具把想法变成第一个模型。"},{"senses":"02 · 04","en":"THE FAST PHYSICAL VERSION: printed parts and bench breadboards.","cn":"快速实体版本：打印件与台面打样。"},{"senses":"03","en":"THE SOFTWARE VERSION: repeated screens tested before code.","cn":"软件版本：写代码前反复测试的界面。"},{"senses":"05 · 06","en":"THE PROOF AND USER VERSION: showing an idea can work, then letting users try it.","cn":"验证与用户版本：证明想法能行，再让用户试用。"},{"senses":"07 · 08","en":"THE METHOD AND SERVICE VERSION: short trial cycles, and a lab that does it for others.","cn":"方法与服务版本：短试错循环，以及替他人制作的实验室。"}]},"affixes":{"intro":{"en":"The word is a Greek compound for an original model plus an English action ending; the ending makes it the work, not the thing.","cn":"这个词是希腊语「最初模子」的复合词加英语动作词尾；词尾使它指工作，而不是物件。"},"latinIntro":{"en":"Late Latin prototypum carried the Greek compound; the action ending is English.","cn":"晚期拉丁语的「最初模子」承载了这个希腊复合词；动作词尾属英语。"},"items":[{"word":"protos","structure":"Greek adjective","meaning":"first","meaningCN":"第一","example":"It begins the compound.","exampleCN":"它构成复合词前半。"},{"word":"typos","structure":"Greek noun","meaning":"mark, model","meaningCN":"印痕、模子","example":"It ends the compound.","exampleCN":"它构成复合词后半。"},{"word":"typein","structure":"Greek verb","meaning":"to strike, impress","meaningCN":"击打、压印","example":"The verb behind typos.","exampleCN":"「印痕」背后的动词。"},{"word":"prototypon","structure":"Greek compound","meaning":"an original model","meaningCN":"最初的模子","example":"The source of prototype.","exampleCN":"「原型」的来源。"},{"word":"prototypum","structure":"Late Latin noun","meaning":"an original form","meaningCN":"原初形式","example":"It reached English as prototype.","exampleCN":"它作为「原型」进入英语。"},{"word":"prototype","structure":"English noun and verb","meaning":"a first model; to make one","meaningCN":"第一个模型；试制","example":"The base of the target.","exampleCN":"目标词的基词。"},{"word":"-ing","structure":"English action ending","meaning":"the activity of","meaningCN":"……的活动","example":"It forms the target noun.","exampleCN":"它构成目标名词。"},{"word":"-er","structure":"agent ending","meaning":"one who does","meaningCN":"做……的人","example":"It forms prototyper.","exampleCN":"它构成「原型制作者」。"},{"word":"-ed","structure":"completed-state ending","meaning":"already done","meaningCN":"已经完成的","example":"It forms prototyped.","exampleCN":"它构成「已试制的」。"}],"latinEntries":[{"word":"prototypum","structure":"prototypum, prototypi (n., second declension, from Greek)","meaning":"an original model","meaningCN":"最初的模子"}],"derivatives":[{"word":"prototype","pos":"n./v.","zh":"由希腊语「第一」与「印模」构成，义为「原型；试制」"},{"word":"prototyped","pos":"adj.","zh":"由「试制」加已然词尾构成，义为「已做成原型的」"},{"word":"prototyper","pos":"n.","zh":"由「做原型」加施动词尾构成，义为「原型制作者」"},{"word":"prototypical","pos":"adj.","zh":"由「原型」加形容词词尾构成，义为「典型的」"},{"word":"archetype","pos":"n.","zh":"由希腊语「最初」与「模子」构成，义为「原初范式」"}]}},{"word":"fabrication","ipa_uk":"/ˌfæbrɪˈkeɪʃən/","ipa_us":"/ˌfæbrɪˈkeɪʃən/","definition_zh":"把材料切割、成形并装配成构件的过程；也指捏造、伪造之事","definition_en":"the process of cutting, forming and assembling materials into a structure, or the act of inventing something false","core_image":"钢板上先画线，再被等离子弧切开，边缘打磨后吊到胎架上点焊，一块构件就这样从平板变成梁","scene":"加工车间里，钢板被等离子切割机切开，边角打磨后吊到胎架上点焊成梁。Sheet-metal fabrication requires precise measurements.","sceneCN":"这里指金属板材的加工与成型过程（第 1 个义项：把材料切割、成形并装配成构件的过程）；句意：金属板材加工需要精确的测量。","pos":[{"tag":"n.","zh":"制造；加工；装配；捏造"}],"collocations":[{"phrase":"metal fabrication","zh":"金属加工"},{"phrase":"steel fabrication","zh":"钢结构加工"},{"phrase":"fabrication shop","zh":"加工车间"},{"phrase":"fabrication process","zh":"加工工艺"},{"phrase":"fabrication of evidence","zh":"伪造证据"},{"phrase":"wafer fabrication","zh":"晶圆制造"}],"forms":[{"label":"不可数名词","form":"fabrication"},{"label":"动词形式","form":"fabricate"},{"label":"过去式","form":"fabricated"},{"label":"过去分词","form":"fabricated"},{"label":"现在分词","form":"fabricating"},{"label":"施动名词","form":"fabricator"}],"derivatives":[{"word":"fabricate","pos":"v.","zh":"由拉丁语「工匠制作」进入英语，义为「制造；捏造」"},{"word":"fabricated","pos":"adj.","zh":"由「制造」加已然词尾构成，义为「制造的；捏造的」"},{"word":"fabricator","pos":"n.","zh":"由「制造」加施动词尾构成，义为「制造者、加工商」"},{"word":"fabric","pos":"n.","zh":"由拉丁语「工坊、织物」进入英语，义为「织物、结构」"},{"word":"prefabricate","pos":"v.","zh":"由「预先」加「制造」构成，义为「预制」"},{"word":"prefabrication","pos":"n.","zh":"由「预制」加名词词尾构成，义为「预制加工」"}],"senses":[{"no":"01","title":"Cutting and forming metal","titleCN":"金属的切割与成形","definition":"the industrial process of cutting, bending and welding material into finished parts","definitionCN":"把材料切割、弯折并焊接成成品构件的工业过程","example":"The fabrication of the frame took four days in the shop.","exampleCN":"框架的加工在车间里花了四天。","why":"The root verb means to make by a craftsman, so the noun names the making of a built object.","whyCN":"词根动词意为工匠制作，因此这个名词指把物件做出来的过程。"},{"no":"02","title":"Assembly of parts into a whole","titleCN":"把部件装配成整体","definition":"the joining of cut parts into a single structure or machine","definitionCN":"把切好的部件连接成一个结构或机器","example":"Fabrication and erection are separate contracts on this site.","exampleCN":"在这个工地上，加工与安装是两份分开的合同。","why":"Making a structure needs both cutting and joining, and the word covers the joined result as well as the cutting.","whyCN":"造结构既需切割也需连接，这个词既指切割，也指连接后的成品。"},{"no":"03","title":"Inventing a false story","titleCN":"编造虚假说法","definition":"the act of inventing facts, an account or an excuse that is not true","definitionCN":"编造不真实的事实、叙述或借口","example":"The whole rumour was a fabrication from a single anonymous post.","exampleCN":"整个谣言只是从一个匿名帖子编造出来的。","why":"A thing made can be made without material, so the word extends from building objects to building lies.","whyCN":"造物可以不用材料，于是这个词从造物件扩展到造谎言。"},{"no":"04","title":"Forging a document or evidence","titleCN":"伪造文件或证据","definition":"the deliberate making of a false document, record or piece of evidence","definitionCN":"有意制作虚假文件、记录或证据","example":"The court found the letter to be a fabrication.","exampleCN":"法庭认定这封信是伪造的。","why":"False paper is also made by a maker, so the manufacturing word serves for deliberate forgery.","whyCN":"假文件同样由制作者做出，因此制造词也用于有意的伪造。"},{"no":"05","title":"Semiconductor manufacturing","titleCN":"半导体制造","definition":"the sequence of deposition, etching and patterning that turns a wafer into chips","definitionCN":"把晶圆变成芯片的沉积、刻蚀与图形化流程","example":"Wafer fabrication needs a clean room cleaner than an operating theatre.","exampleCN":"晶圆制造需要比手术室更洁净的洁净室。","why":"Chip making is a highly controlled kind of making, so the general word names the whole factory process.","whyCN":"芯片制造是高度受控的制造，因此这个泛称指整个工厂流程。"},{"no":"06","title":"Steel structure work","titleCN":"钢结构加工","definition":"the cutting, drilling and welding of steel members in a fabrication shop","definitionCN":"在加工车间对钢构件进行切割、钻孔与焊接","example":"The bridge's fabrication was checked against the shop drawings.","exampleCN":"这座桥的钢结构加工对照车间图纸进行了检查。","why":"Steel is cut and joined away from site, and that shop work is the clearest industrial use of the word.","whyCN":"钢在现场之外被切割与连接，这种车间工作是该词最清晰的工业用法。"},{"no":"07","title":"A made-up thing","titleCN":"捏造出来的东西","definition":"a story, excuse or claim that has been invented and does not exist as described","definitionCN":"被编造出来、并不如所述存在的说法、借口或主张","example":"His alibi was a fabrication with no supporting detail.","exampleCN":"他的不在场证明是捏造的，没有任何细节支撑。","why":"The noun can name the false thing itself, not only the act of making it.","whyCN":"这个名词可指虚假之物本身，而不只是编造的动作。"},{"no":"08","title":"A fabrication shop or trade","titleCN":"加工车间或行业","definition":"the workshop, business or trade that cuts and assembles material for construction","definitionCN":"为建筑切割并组装材料的车间、企业或行业","example":"She learned welding in a small fabrication on the coast.","exampleCN":"她在海边一家小型加工车间学会了焊接。","why":"The place where the work is done takes the name of the work, a common shift in trade words.","whyCN":"干活的地方沿用工作的名称，这是行业词常见的转义。"}],"etymology":{"intro":{"en":"Fabrication comes from Latin words for a craftsman and his workshop; English first used it for making things and later for making things that are not true.","cn":"「制造」来自拉丁语中表示工匠及其工坊的词；英语先用它指造物，后来也指造出不真实的东西。"},"items":[{"era":"LATIN FABER","en":"Faber meant a craftsman, especially a smith or carpenter; it is the direct Latin source, while its deeper origin is uncertain and the link to a shaping root is only a suggestion.","cn":"这个拉丁语名词指工匠，尤指铁匠或木匠；它是本词的直接拉丁语来源，其更早来源存疑，与表示「塑造」之词根的关联仅为推测。"},{"era":"LATIN FABRICA","en":"Fabrica named a workshop and also the craft or structure made there, and English fabric later narrowed to woven cloth.","cn":"这个拉丁语名词指工坊，也指在那里做出的手艺或结构；英语的「织物」后来缩小为编织布料。"},{"era":"LATIN FABRICARE","en":"Fabricare meant to make, build or shape something in a workshop, with no hint of deceit.","cn":"这个拉丁语动词指在工坊里制作、建造或塑造，完全没有欺骗含义。"},{"era":"LATIN FABRICATIO · FIRST RECORD DATE UNCERTAIN","en":"Fabricatio named the act of making, and English fabrication kept that sense for metal, timber and stone work; the earliest English record of the borrowed noun is not precisely dated.","cn":"这个拉丁语名词指制作的行为，英语的「制造」保留了用于金属、木材与石材工作的含义；英语借入这一名词的最早记录年代不确定。"},{"era":"SENSE OF FALSEHOOD","en":"From the idea of building a thing comes the idea of building a story, and by the eighteenth century fabrication could mean a lie.","cn":"从「造物」的观念衍生出「造故事」的观念，到十八世纪，这个词已可指谎言。"},{"era":"MODERN TECHNICAL USE","en":"Engineering kept the honest sense for cutting and welding, while semiconductor work gave it a high-technology meaning.","cn":"工程保留了切割与焊接的诚实义，半导体工作又给了它一个高科技含义。"}]},"similar":{"note":{"en":"The first group shares the craftsman root; the second group separates making words from falsehood words.","cn":"第一组共享「工匠」词根；第二组区分制造词与虚假词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fabricate","ipa":"/ˈfæbrɪkeɪt/","tag":"verb","definition":"To make or to invent falsely; the action behind the noun.","definitionCN":"制造或编造；名词背后的动作。"},{"word":"fabricated","ipa":"/ˈfæbrɪkeɪtɪd/","tag":"adjective","definition":"Made, or invented in order to deceive.","definitionCN":"已制造的，或为欺骗而编造的。"},{"word":"fabricator","ipa":"/ˈfæbrɪkeɪtə/","tag":"noun","definition":"A maker or a person who invents false accounts.","definitionCN":"制造者，或编造虚假说法的人。"},{"word":"fabric","ipa":"/fəˈbrɪk/","tag":"noun","definition":"Woven cloth or the structure of a building; the same root, narrowed.","definitionCN":"织物或建筑的结构；同词根，词义缩小。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manufacture","ipa":"/ˌmænjuˈfæktʃə/","tag":"noun","definition":"Making goods on a large scale by hand or machine; it stresses volume, not a single built member.","definitionCN":"大规模手工或机器制造；强调产量，而非单件构件。"},{"word":"assembly","ipa":"/əˈsemblɪ/","tag":"noun","definition":"Putting finished parts together; fabrication also cuts and forms those parts.","definitionCN":"把成品零件装在一起；目标词还包含切割与成形。"},{"word":"forgery","ipa":"/ˈfɔːdʒəri/","tag":"noun","definition":"A false document made to deceive; narrower than the falsehood sense of the target.","definitionCN":"为欺骗而做的假文件；比目标词的虚假义窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real fixed terms, not invented rhymes.","cn":"正常联想：真实的构词成分与真实固定搭配，而不是编造的顺口溜。"},"normal":[{"en":"The root is the craftsman in his workshop, making what he is asked to make.","cn":"词根是工坊里的工匠，按要求制作东西。"},{"en":"The family runs fabricate, fabricated, fabricator, fabric, prefabricate.","cn":"同族词包括制造、制造的、制造者、织物、预制。"},{"en":"Fixed phrases mark it: metal fabrication, fabrication shop, fabrication of evidence.","cn":"固定搭配可标记它：金属加工、加工车间、伪造证据。"},{"en":"The honest sense cuts and welds; the dishonest sense invents and forges.","cn":"诚实义用于切割与焊接，不诚实义用于编造与伪造。"},{"en":"Its test is material: a lie has no shop drawing.","cn":"它的检验是物质性的：谎言没有车间图纸。"}],"abstract":[{"en":"Picture a flat plate becoming a beam after one cut and one weld.","cn":"想象一块平板经过一次切割与一次焊接变成一根梁。"},{"en":"Picture a story assembled from spare parts that no supplier ever sold.","cn":"想象一个用从未有供应商卖过的零件拼成的故事。"},{"en":"Picture a signature drawn by a hand that never owned the name.","cn":"想象一个从未拥有该姓名的手画出的签名。"}]},"examples":[{"en":"Metal fabrication holds the tolerance better than site cutting.","cn":"金属加工比现场切割更能保证公差。"},{"en":"The report's key quotation turned out to be a fabrication.","cn":"报告的关键引文结果是捏造的。"},{"en":"He runs a small fabrication behind the railway yard.","cn":"他在铁路场后面经营一家小型加工车间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「工匠在工坊里做活」——既能造梁，也能造谎","word":"fabrication"},"root":"源自拉丁语「工匠」及其「工坊、制作」的词族；诚实义指切割焊接，虚假义指编造与伪造；工匠一词更早来源不确定。","sensesIntro":{"en":"Eight senses follow one maker: material is cut and joined, chips are patterned, and stories are invented. The same word covers honest making and deliberate falsehood.","cn":"八个义项围绕一个制作者：材料被切割与连接，芯片被图形化，故事被编造。同一个词既覆盖诚实的制造，也覆盖有意的虚假。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flat steel plate cut, ground and welded into a beam; the same gesture can also assemble a lie.","cn":"核心意象：一块平板钢被切割、打磨并焊成梁；同一个动作也能拼出一个谎言。"},"chain":["MAKE FROM PARTS","CUT AND WELD","ASSEMBLE","FALSE STORY","FORGE DOCUMENT","SEMICONDUCTOR FAB"],"branches":[{"senses":"01 · 02","en":"THE HONEST CORE: cutting, forming and joining material into a member.","cn":"诚实核心：把材料切割、成形并连接成构件。"},{"senses":"03 · 07","en":"THE FALSEHOOD VERSION: inventing a story, and the invented thing itself.","cn":"虚假版本：编造说法，以及被编造出来的东西。"},{"senses":"04","en":"THE DOCUMENT VERSION: deliberate forgery of paper or evidence.","cn":"文书版本：有意伪造文件或证据。"},{"senses":"05","en":"THE CHIP VERSION: deposition, etching and patterning on a wafer.","cn":"芯片版本：晶圆上的沉积、刻蚀与图形化。"},{"senses":"06 · 08","en":"THE SHOP VERSION: steel structure work and the workshop that does it.","cn":"车间版本：钢结构加工与从事加工的车间。"}]},"affixes":{"intro":{"en":"The word is Latin: a craftsman, his workshop, the act of making there, and then a story made without material.","cn":"这个词来自拉丁语：工匠、他的工坊、在那里制作的行为，以及随后不用材料造出的故事。"},"latinIntro":{"en":"Latin faber, fabrica and fabricatio supply the whole family, including fabric and prefabricate.","cn":"拉丁语的工匠、工坊与制作提供了整个词族，包括织物与预制。"},"items":[{"word":"faber","structure":"Latin noun","meaning":"craftsman, smith","meaningCN":"工匠、铁匠","example":"The root of the whole family.","exampleCN":"整个词族的词根。"},{"word":"fabrica","structure":"Latin noun","meaning":"workshop; craft; structure","meaningCN":"工坊；手艺；结构","example":"It also gave English fabric.","exampleCN":"它还给英语提供了「织物」。"},{"word":"fabricare","structure":"Latin verb","meaning":"to make in a workshop","meaningCN":"在工坊制作","example":"The verb behind fabrication.","exampleCN":"「制造」背后的动词。"},{"word":"fabricatio","structure":"Latin noun","meaning":"the act of making","meaningCN":"制作行为","example":"English kept it as fabrication.","exampleCN":"英语以「制造」保留它。"},{"word":"-ation","structure":"English noun ending","meaning":"action or result","meaningCN":"动作或结果","example":"It marks the process and the product.","exampleCN":"它标记过程与产物。"},{"word":"fabricate","structure":"English verb","meaning":"to make; to invent falsely","meaningCN":"制造；编造","example":"The verb carries both senses.","exampleCN":"动词兼有这两义。"},{"word":"fabricator","structure":"English noun","meaning":"a maker","meaningCN":"制造者","example":"The agent ending names the person or firm.","exampleCN":"施动词尾指人或企业。"},{"word":"fabric","structure":"English noun","meaning":"woven cloth; structure","meaningCN":"织物；结构","example":"A narrowed descendant of the workshop word.","exampleCN":"工坊词的缩小后裔。"},{"word":"pre-","structure":"Latin prefix","meaning":"before, in advance","meaningCN":"预先","example":"It forms prefabricate.","exampleCN":"它构成「预制」。"},{"word":"prefabrication","structure":"English noun","meaning":"making parts in advance","meaningCN":"预先制作构件","example":"The compound keeps the honest sense only.","exampleCN":"这个复合词只保留诚实义。"}],"latinEntries":[{"word":"faber","structure":"faber, fabri (n., second declension)","meaning":"craftsman, smith","meaningCN":"工匠、铁匠"},{"word":"fabrica","structure":"fabrica, fabricae (n., first declension)","meaning":"workshop; craft","meaningCN":"工坊；手艺"},{"word":"fabricatio","structure":"fabricatio, fabricationis (n., third declension)","meaning":"the act of making","meaningCN":"制作行为"}],"derivatives":[{"word":"fabricate","pos":"v.","zh":"由拉丁语「工坊制作」进入英语，义为「制造；编造」"},{"word":"fabricated","pos":"adj.","zh":"由「制造」加已然词尾构成，义为「制造的；捏造的」"},{"word":"fabricator","pos":"n.","zh":"由「制造」加施动词尾构成，义为「加工商」"},{"word":"fabric","pos":"n.","zh":"由拉丁语「工坊」缩小而来，义为「织物」"},{"word":"prefabricate","pos":"v.","zh":"由「预先」加「制造」构成，义为「预制」"},{"word":"prefabrication","pos":"n.","zh":"由「预制」加名词词尾构成，义为「预制加工」"}]}}]);
